"""Conservative identity and grouping rules for research dataset isolation."""

from __future__ import annotations

from typing import Any


def identity_keys(sample: dict[str, Any]) -> set[tuple[str, ...]]:
    """Metadata changes must not separate a known cover from its derivatives.

    Content-hash lineages are global identities; human-assigned lineages are
    namespaced by source. Camera/device metadata is deliberately not identity.
    This cannot infer undocumented ancestry or detect perceptual duplicates.
    """
    keys: set[tuple[str, ...]] = set()
    digest = str(sample.get("sha256") or "").lower()
    if digest:
        keys.add(("hash", digest))
    lineage = str(sample.get("lineage") or "")
    if lineage:
        if len(lineage) == 64 and all(c in "0123456789abcdef" for c in lineage.lower()):
            keys.add(("hash", lineage.lower()))
        else:
            keys.add(("lineage", str(sample.get("source_group") or "unspecified"), lineage))
    return keys


def grouped_indices(samples: list[dict[str, Any]]) -> list[list[int]]:
    """Connected components sharing identity, camera or device within a source."""
    parents = list(range(len(samples)))

    def root(index: int) -> int:
        while parents[index] != index:
            parents[index] = parents[parents[index]]
            index = parents[index]
        return index

    owners: dict[tuple[str, ...], int] = {}
    for index, sample in enumerate(samples):
        keys = identity_keys(sample)
        for field in ("camera", "device"):
            if sample.get(field):
                keys.add((field, str(sample["source_group"]), str(sample[field])))
        for key in sorted(keys):
            previous = owners.setdefault(key, index)
            parents[root(index)] = root(previous)
    groups: dict[int, list[int]] = {}
    for index in range(len(samples)):
        groups.setdefault(root(index), []).append(index)
    return list(groups.values())

core/document_corpus.py.utf8:
"""Bounded local document pilot; no downloads, fitting or detector scores."""
from __future__ import annotations

import hashlib
import io
import json
import os
import re
import stat
import time
import zipfile
from pathlib import Path, PurePosixPath
from typing import Any

MAX_FILE = 2 * 1024**2
MAX_OUTPUT = 16 * 1024**2
MAX_DOCUMENTS = 64
MAX_SECONDS = 120
EXTENSIONS = (".pdf", ".txt", ".md", ".zip")


def digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def regular_read(path: Path, limit: int) -> bytes:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("document input symlink")
    descriptor = os.open(path, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW)
    with os.fdopen(descriptor, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or not 0 < info.st_size <= limit:
            raise ValueError("document input type/size")
        raw = stream.read(limit + 1)
    if len(raw) != info.st_size or len(raw) > limit:
        raise ValueError("document input changed or oversized")
    return raw


def _token(value: str) -> str:
    if not isinstance(value, str) or re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9_.+:-]{0,127}", value
    ) is None:
        raise ValueError("document public identity")
    return value


def _put(path: Path, raw: bytes) -> None:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("document output symlink")
    with path.open("xb") as stream:
        stream.write(raw)


def inspect(raw: bytes, extension: str) -> dict:
    """Only structural inventory checks, never a clean-file verdict."""
    if extension in (".txt", ".md"):
        text = raw.decode("utf-8")
        if "\0" in text or not text.strip():
            raise ValueError("document UTF-8 text required")
        return {"kind": "utf8_text", "characters": len(text)}
    if extension == ".pdf":
        if not raw.startswith(b"%PDF-") or b"%%EOF" not in raw[-1024:]:
            raise ValueError("document PDF header/end required")
        return {"kind": "pdf", "full_parser_validation": "unavailable"}
    if extension != ".zip":
        raise ValueError("unsupported document extension")
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        members = archive.infolist()
        if not 0 < len(members) <= 512 or sum(m.file_size for m in members) > MAX_OUTPUT:
            raise ValueError("document archive member/expanded bound")
        for member in members:
            name = PurePosixPath(member.filename.replace("\\", "/"))
            mode = member.external_attr >> 16
            if (name.is_absolute() or ".." in name.parts or stat.S_ISLNK(mode)
                    or member.flag_bits & 1):
                raise ValueError("document unsafe/encrypted archive member")
    return {"kind": "zip", "members": len(members), "member_extraction": "not_performed"}


def _variants(raw: bytes, extension: str) -> tuple[bytes, bytes, str, str]:
    payload = hashlib.sha256(b"document-pilot-v1:" + raw).digest()
    if extension in (".txt", ".md"):
        bits = f"{int.from_bytes(payload, 'big'):0256b}"
        suffix = "".join("\u200b" if bit == "0" else "\u200c" for bit in bits).encode()
        method = "unicode-suffix-bitpair-v1"
    else:
        suffix = payload
        method = "opaque-append32-v1"
    return raw + suffix, raw + b" " * len(suffix), digest(payload), method


def recover(raw: bytes, original_bytes: int, method: str) -> bytes:
    """Scalar oracle uses known original extent, not autonomous recovery."""
    suffix = raw[original_bytes:]
    if method == "opaque-append32-v1":
        if len(suffix) != 32:
            raise ValueError("document opaque payload extent")
        return suffix
    if method != "unicode-suffix-bitpair-v1":
        raise ValueError("document oracle method")
    text = suffix.decode("utf-8")
    if len(text) != 256 or any(char not in "\u200b\u200c" for char in text):
        raise ValueError("document Unicode payload extent/alphabet")
    result = bytearray(32)
    for position, char in enumerate(text):
        result[position // 8] |= (char == "\u200c") << (7 - position % 8)
    return bytes(result)


def prepare(config: dict, out: Path, *, clock=time.monotonic) -> dict:
    started = clock()
    records = config.get("documents")
    if config.get("schema_version") != "local-document-pilot-config-v1" or (
        not isinstance(records, list) or not 1 <= len(records) <= MAX_DOCUMENTS
    ):
        raise ValueError("document configuration/count")
    if out.exists() or any(p.is_symlink() for p in (out, *out.parents)):
        raise ValueError("document fresh nonsymlink output required")
    blobs: dict[str, bytes] = {}
    sources: dict[Path, str] = {}
    samples: list[dict[str, Any]] = []
    seen: set[str] = set()

    def deadline():
        if clock() - started >= MAX_SECONDS:
            raise TimeoutError("document preparation deadline")

    for index, record in enumerate(records):
        deadline()
        source = Path(record["input"])
        license_path = Path(record["license_input"])
        if any(p.absolute().is_relative_to(out.absolute()) for p in (source, license_path)):
            raise ValueError("document input inside output")
        raw = regular_read(source, MAX_FILE)
        license_raw = regular_read(license_path, MAX_FILE)
        sha, license_sha = digest(raw), digest(license_raw)
        if sha != record["sha256"] or license_sha != record["license_sha256"] or sha in seen:
            raise ValueError("document checksum/duplicate")
        if record.get("license_review") != "declared_file_scope_reviewed":
            raise ValueError("document file-scope license review required")
        seen.add(sha)
        sources.update({source: sha, license_path: license_sha})
        extension = source.suffix.lower()
        inventory = inspect(raw, extension)
        positive, negative, payload_sha, method = _variants(raw, extension)
        if digest(recover(positive, len(raw), method)) != payload_sha:
            raise ValueError("document scalar payload oracle")
        license_name = "license-" + license_sha + ".txt"
        blobs[license_name] = license_raw
        variants = {}
        for role, contents in (("original", raw), ("controlled_positive", positive),
                               ("whitespace_control", negative)):
            name = f"document-{index:03d}-{role}{extension}"
            blobs[name] = contents
            variants[role] = {"artifact": name, "sha256": digest(contents), "bytes": len(contents)}
        samples.append({"source_id": _token(record["source_id"]),
                        "source_group": _token(record["source_group"]),
                        "license": _token(record["license"]), "license_artifact": license_name,
                        "license_sha256": license_sha, "original_sha256": sha,
                        "extension": extension, "split": "development_unassigned",
                        "cover_certification": "unavailable; natural source is a benign candidate",
                        "inventory": inventory, "method": method, "payload_bytes": 32,
                        "payload_sha256": payload_sha, "variants": variants})
        if sum(map(len, blobs.values())) > MAX_OUTPUT:
            raise ValueError("document aggregate output bound")
    report = {"schema_version": "local-document-pilot-v1", "status": "prepared_unassigned",
              "original_files": len(samples),
              "source_groups": len({s["source_group"] for s in samples}),
              "samples": samples, "training_ready": False, "optimizer_updates": 0,
              "statistical_detection": "unavailable", "downloaded_bytes": 0,
              "test_media_opened": False, "independent_recording_count": "unavailable",
              "autonomous_recovery": "unavailable; oracle needs original extent",
              "artifact_bytes_excluding_manifest": sum(map(len, blobs.values()))}
    encoded = (json.dumps(report, indent=2, allow_nan=False) + "\n").encode()
    if sum(map(len, blobs.values())) + len(encoded) > MAX_OUTPUT:
        raise ValueError("document manifest/output bound")
    deadline()
    if any(digest(regular_read(path, MAX_FILE)) != sha for path, sha in sources.items()):
        raise ValueError("document source mutation")
    out.mkdir(parents=True, mode=0o700)
    for name, raw in blobs.items():
        deadline()
        _put(out / name, raw)
        if digest(regular_read(out / name, MAX_FILE + 768)) != digest(raw):
            raise ValueError("document output checksum")
    for sample in samples:
        deadline()
        original = sample["variants"]["original"]
        positive = sample["variants"]["controlled_positive"]
        raw = regular_read(out / positive["artifact"], MAX_FILE + 768)
        if digest(raw) != positive["sha256"] or digest(recover(
            raw, original["bytes"], sample["method"]
        )) != sample["payload_sha256"]:
            raise ValueError("document on-disk oracle/checksum")
    deadline()
    if any(digest(regular_read(path, MAX_FILE)) != sha for path, sha in sources.items()):
        raise ValueError("document source mutation after write")
    _put(out / "manifest.json", encoded)
    return report

core/feature_model.py.utf8:
"""Reconstruct an explicit research feature model, with optional train-only scaling."""

from typing import Any

LINEAR = "linear-v1"
RESIDUAL_MLP = "residual-mlp64-v1"


def feature_network(features: int, architecture: str = LINEAR) -> Any:
    """Fixed, bounded opt-in architectures; no validation-driven shape selection."""
    import torch

    if type(features) is not int or not 1 <= features <= 4096:
        raise ValueError("invalid feature dimension")
    if architecture == LINEAR:
        return torch.nn.Linear(features, 1)
    if architecture != RESIDUAL_MLP:
        raise ValueError("invalid feature architecture")

    class ResidualMLP(torch.nn.Module):
        def __init__(self) -> None:
            super().__init__()
            self.skip = torch.nn.Linear(features, 1)
            self.hidden = torch.nn.Linear(features, 64)
            self.output = torch.nn.Linear(64, 1)

        def forward(self, values):
            return self.skip(values) + self.output(torch.relu(self.hidden(values)))

    return ResidualMLP()


def feature_model(checkpoint: dict[str, Any]) -> Any:
    import torch

    linear = feature_network(
        checkpoint["features"], checkpoint["preprocessing"].get("architecture", LINEAR)
    )
    linear.load_state_dict(checkpoint["state_dict"])
    if not all(bool(torch.isfinite(p).all()) for p in linear.parameters()):
        raise ValueError("nonfinite feature model parameters")
    arithmetic = checkpoint["preprocessing"].get("inference_arithmetic", "float32")
    if arithmetic not in {"float32", "float64"}:
        raise ValueError("invalid inference arithmetic contract")
    dtype = torch.float64 if arithmetic == "float64" else torch.float32
    linear = linear.to(dtype=dtype)
    normalization = checkpoint["preprocessing"].get("normalization")
    if normalization is None and arithmetic == "float32":
        return linear
    mean = torch.tensor(normalization["mean"], dtype=dtype) if normalization else None
    scale = torch.tensor(normalization["scale"], dtype=dtype) if normalization else None
    if normalization is not None and (
        mean is None
        or scale is None
        or normalization.get("method") != "train-only-standardization"
        or mean.shape != (checkpoint["features"],)
        or scale.shape != mean.shape
        or not bool(torch.isfinite(mean).all())
        or not bool(torch.isfinite(scale).all())
        or not bool((scale > 0).all())
    ):
        raise ValueError("invalid feature normalization contract")

    class StandardizedLinear(torch.nn.Module):
        def __init__(self) -> None:
            super().__init__()
            self.linear = linear
            self.register_buffer("mean", mean)
            self.register_buffer("scale", scale)

        def forward(self, values):
            values = values.to(dtype=dtype)
            if self.mean is not None:
                values = (values - self.mean) / self.scale
            # Accumulate opt-in double arithmetic; keep the existing float I/O.
            return self.linear(values).to(dtype=torch.float32)

    return StandardizedLinear()

core/filetype.py.utf8:
"""Small, dependency-free content type detection used for dispatch and evidence."""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class DetectedType:
    name: str
    mime_type: str
    extension: str | None
    compatible_extensions: frozenset[str]


_UNKNOWN = DetectedType("unknown", "application/octet-stream", None, frozenset())


def detect_type(path: Path) -> DetectedType:
    """Identify supported formats by magic bytes, falling back to UTF-8 text."""
    try:
        with path.open("rb") as stream:
            head = stream.read(8192)
    except OSError:
        return _UNKNOWN

    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return DetectedType("png", "image/png", ".png", frozenset({".png"}))
    if head.startswith(b"\xff\xd8\xff"):
        return DetectedType(
            "jpeg", "image/jpeg", ".jpg", frozenset({".jpg", ".jpeg"})
        )
    if head.startswith((b"GIF87a", b"GIF89a")):
        return DetectedType("gif", "image/gif", ".gif", frozenset({".gif"}))
    if head.startswith(b"%PDF-"):
        return DetectedType(
            "pdf", "application/pdf", ".pdf", frozenset({".pdf"})
        )
    if head.startswith(b"BM"):
        return DetectedType("bmp", "image/bmp", ".bmp", frozenset({".bmp"}))
    if head.startswith((b"II*\x00", b"MM\x00*")):
        return DetectedType(
            "tiff", "image/tiff", ".tiff", frozenset({".tif", ".tiff"})
        )
    if len(head) >= 12 and head[:4] == b"RIFF" and head[8:12] == b"WAVE":
        return DetectedType("wav", "audio/wav", ".wav", frozenset({".wav"}))
    if head.startswith(b"ID3") or (
        len(head) >= 2 and head[0] == 0xFF and (head[1] & 0xE0) == 0xE0
    ):
        return DetectedType("mp3", "audio/mpeg", ".mp3", frozenset({".mp3"}))
    if _looks_like_text(head):
        suffix = path.suffix.lower()
        canonical = suffix if suffix in {".txt", ".md"} else ".txt"
        return DetectedType(
            "text", "text/plain", canonical, frozenset({".txt", ".md"})
        )
    return _UNKNOWN


def extension_mismatch(path: Path, detected: DetectedType) -> bool:
    suffix = path.suffix.lower()
    return bool(detected.compatible_extensions and suffix not in detected.compatible_extensions)


def _looks_like_text(data: bytes) -> bool:
    if not data or b"\x00" in data:
        return False
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return False
    printable = sum(char.isprintable() or char in "\r\n\t" for char in text)
    return printable / max(len(text), 1) >= 0.95

core/jpeg_cnn_model.py.utf8:
"""Bounded numeric-only serialization for the fixed pixel CNN; no pickle."""

from __future__ import annotations

import hashlib
import io
import math
import zipfile
from pathlib import Path

import numpy as np

from core import jpeg_cnn as cnn

MAX_BYTES = 1024**2
SHAPES = {
    "filters": (3, 1, 3, 3),
    "layers.0.weight": (8, 3, 3, 3),
    "layers.0.bias": (8,),
    "layers.3.weight": (16, 8, 3, 3),
    "layers.3.bias": (16,),
    "layers.6.weight": (16, 16, 3, 3),
    "layers.6.bias": (16,),
    "layers.10.weight": (1, 16),
    "layers.10.bias": (1,),
}


def validate(arrays, *, architecture=cnn.ARCHITECTURE):
    filters, _ = cnn.residual_contract(architecture)
    if set(arrays) != set(SHAPES) or any(
        arrays[k].shape != shape
        or arrays[k].dtype != np.dtype("<f4")
        or not np.isfinite(arrays[k]).all()
        for k, shape in SHAPES.items()
    ):
        raise ValueError("pixel model dimensions/dtype/parameters mismatch")
    if not np.array_equal(arrays["filters"], filters):
        raise ValueError("pixel model fixed filters changed")


def save_model(model, path: Path) -> str:
    if path.exists() or any(p.is_symlink() for p in (path, *path.parents)):
        raise FileExistsError("pixel model output exists or uses a symlink")
    arrays = {k: v.detach().cpu().numpy().astype("<f4") for k, v in model.state_dict().items()}
    validate(arrays, architecture=getattr(model, "architecture", cnn.ARCHITECTURE))
    buffer = io.BytesIO()
    np.savez(buffer, **arrays)
    data = buffer.getvalue()
    if len(data) > MAX_BYTES:
        raise ValueError("pixel model exceeds byte limit")
    with path.open("xb") as stream:
        stream.write(data)
    return hashlib.sha256(data).hexdigest()


def load_model(path: Path, *, checksum: str, architecture=cnn.ARCHITECTURE):
    cnn.residual_contract(architecture)
    if (
        not path.is_file()
        or any(p.is_symlink() for p in (path, *path.parents))
        or path.stat().st_size > MAX_BYTES
    ):
        raise ValueError("pixel model must be bounded, regular and non-symlink")
    with path.open("rb") as stream:
        data = stream.read(MAX_BYTES + 1)
    if len(data) > MAX_BYTES or hashlib.sha256(data).hexdigest() != checksum:
        raise ValueError("pixel model checksum/byte limit failure")
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        members = archive.infolist()
        if (
            len(members) != len(SHAPES)
            or {m.filename for m in members} != {k + ".npy" for k in SHAPES}
            or sum(m.file_size for m in members) > MAX_BYTES
        ):
            raise ValueError("pixel model archive contract mismatch")
        for member in members:
            with archive.open(member) as stream:
                version = np.lib.format.read_magic(stream)
                if version == (1, 0):
                    shape, _, dtype = np.lib.format.read_array_header_1_0(
                        stream, max_header_size=4096
                    )
                elif version == (2, 0):
                    shape, _, dtype = np.lib.format.read_array_header_2_0(
                        stream, max_header_size=4096
                    )
                else:
                    raise ValueError("unsupported pixel model array header")
                if (
                    shape != SHAPES[member.filename[:-4]]
                    or dtype != np.dtype("<f4")
                    or stream.tell() + math.prod(shape) * dtype.itemsize != member.file_size
                ):
                    raise ValueError("pixel model array header/size mismatch")
    with np.load(io.BytesIO(data), allow_pickle=False, max_header_size=4096) as archive:
        arrays = {k: archive[k] for k in SHAPES}
    validate(arrays, architecture=architecture)
    import torch

    model = cnn.network(architecture)
    model.load_state_dict({k: torch.from_numpy(v.copy()) for k, v in arrays.items()}, strict=True)
    return model.eval()

core/jpeg_crop_signal.py.utf8:
"""Read-only train-crop signal accounting; no fitting or accuracy assertion."""

from __future__ import annotations

import numpy as np

from core.jpeg_timing_probe import AUDIT_SHA, MANIFEST_SHA, TimingReader
from core.srnet_stream import deadline_after


def summarize(samples, fetch):
    if len(samples) != 480 or any(r["split"] != "train" for r in samples):
        raise ValueError("crop signal requires the complete training kit")
    groups: dict[str, set[str]] = {}
    for row in samples:
        groups.setdefault(row["source_group"], set()).add(row["lineage"])
    if len(groups) != 3 or any(len(v) != 32 for v in groups.values()):
        raise ValueError("crop signal original accounting mismatch")
    fit = {s: set(sorted(v)[:24]) for s, v in groups.items()}
    covers = {
        (r["source_group"], r["lineage"], r["quality_factor"]): i
        for i, r in enumerate(samples)
        if r["label"] == "cover"
    }
    cells: dict[tuple[str, int | None, str], list[tuple[int, float]]] = {}
    for index, row in enumerate(samples):
        if row["label"] != "stego" or row["lineage"] not in fit[row["source_group"]]:
            continue
        key = (row["source_group"], row["quality_factor"], row["method"])
        cover = covers[(row["source_group"], row["lineage"], row["quality_factor"])]
        batch = fetch(np.array([cover, index, cover, index], dtype=np.int64))
        if (
            batch.shape != (4, 1, 256, 256)
            or batch.dtype != np.dtype("<f4")
            or (not np.isfinite(batch).all() or np.any(np.abs(batch) > 2**36))
        ):
            raise ValueError("crop signal invalid decoded batch")
        delta = batch[1].astype(np.float64) - batch[0].astype(np.float64)
        values = (int(np.count_nonzero(delta)), float(np.sqrt(np.mean(delta * delta))))
        cells.setdefault(key, []).append(values)
    if len(cells) != 10 or any(len(v) != 24 for v in cells.values()):
        raise ValueError("crop signal complete fit pair accounting required")
    return [
        {
            "source_group": key[0],
            "quality_factor": key[1],
            "method": key[2],
            "fit_pairs": len(values),
            "identical_crops": sum(count == 0 for count, _ in values),
            "minimum_rms_pixel_difference": min(rms for _, rms in values),
            "maximum_rms_pixel_difference": max(rms for _, rms in values),
        }
        for key, values in sorted(cells.items(), key=lambda item: str(item[0]))
    ]


def inspect_fit_signal(root, audit):
    with TimingReader(root, audit, deadline=deadline_after(120)) as reader:
        cells = summarize(reader.samples, reader.batch)
        reader.verify()
    identical = sum(c["identical_crops"] for c in cells)
    return {
        "schema_version": "jpeg-train-crop-signal-v1",
        "status": "completed",
        "manifest_sha256": MANIFEST_SHA,
        "audit_sha256": AUDIT_SHA,
        "fit_pairs": 240,
        "identical_crops": identical,
        "crop_signal_coverage": "partial" if identical else "complete",
        "cells": cells,
        "probe_pixels_read": 0,
        "validation_test_used": False,
        "optimizer_updates": 0,
        "accuracy_qualification": "unavailable",
        "deployed": False,
    }

core/jpeg_refine_metrics.py.utf8:
"""Original-pair intervals and the frozen all-source/all-seed research gate."""

from __future__ import annotations

import numpy as np

from core import jpeg_refine_schedule as schedule
from core import jpeg_study as study
from core import jpeg_study_data as data


def measured(pairs):
    negatives, positives = pairs[:, 0], pairs[:, 1]
    tn, tp = float(np.mean(negatives < 0.5)), float(np.mean(positives >= 0.5))
    flat = pairs.ravel()
    labels = np.tile([0, 1], len(pairs))
    bins = np.minimum((flat * 10).astype(int), 9)
    ece = sum(
        float(mask.mean() * abs(flat[mask].mean() - labels[mask].mean()))
        for i in range(10)
        if (mask := bins == i).any()
    )
    return {
        "balanced_accuracy": (tn + tp) / 2,
        "recall": tp,
        "false_positive_rate": 1 - tn,
        "ece": ece,
        "tp": float(np.sum(positives >= 0.5)),
        "tn": float(np.sum(negatives < 0.5)),
        "fp": float(np.sum(negatives >= 0.5)),
        "fn": float(np.sum(positives < 0.5)),
    }


def statistics(samples, scores, *, baseline=None, role="development"):
    if role not in ("fit", "development") or any(r["role"] != role for r in samples):
        raise ValueError("refine metric role mismatch")
    # Historical validator computes paired AUC intervals with identical draws.
    adapted = [{**r, "role": "development"} for r in samples]
    cells = study.statistics(adapted, scores, baseline=baseline)
    for cell in cells:
        indices = [
            i // 2
            for i in range(0, len(samples), 2)
            if samples[i]["source_group"] == cell["source_group"]
        ]
        pairs = np.asarray(scores).reshape(-1, 2)[indices]
        rng = np.random.default_rng(study.SEEDS[0])
        estimates: dict[str, list[float]] = {k: [] for k in measured(pairs)}
        for _ in range(1000):
            draw = rng.integers(len(pairs), size=len(pairs))
            for key, value in measured(pairs[draw]).items():
                estimates[key].append(value)
        cell["metric_ci95"] = {
            k: np.quantile(v, [0.025, 0.975]).tolist() for k, v in estimates.items()
        }
        cell["role"] = role
        if role == "fit":
            cell["learning_gate"] = False
        if baseline is not None:
            prior = np.asarray(baseline).reshape(-1, 2)[indices]
            cell["paired_auc_delta"] = study.auc(pairs) - study.auc(prior)
    return cells


def compare(manifest, evaluations):
    expected = {(a, s) for s in study.SEEDS for a in ("warmup", *schedule.ARMS)}
    if (
        len(evaluations) != 6
        or {(v["metadata"]["arm"], v["metadata"]["seed"]) for v in evaluations} != expected
        or any(
            v.get("status") != "completed"
            or v.get("real_gpu_evaluation") is not True
            or v.get("model_sha256_before") != v.get("model_sha256_after")
            or v["metadata"]["total_updates"]
            != (schedule.WARMUP if v["metadata"]["arm"] == "warmup" else schedule.FINAL)
            for v in evaluations
        )
    ):
        raise ValueError("refine metrics require complete immutable GPU matrix")
    indexed = {(v["metadata"]["arm"], v["metadata"]["seed"]): v for v in evaluations}
    results = []
    for seed in study.SEEDS:
        warmup = indexed[("warmup", seed)]
        control = indexed[("paired", seed)]
        for arm in ("warmup", *schedule.ARMS):
            value = indexed[(arm, seed)]
            scores = value["development"]["scores"]
            cells = statistics(
                manifest["samples"]["development"],
                scores,
                baseline=warmup["development"]["scores"] if arm != "warmup" else None,
            )
            result = {
                "arm": arm,
                "seed": seed,
                "cells": cells,
                "checkpoint_sha256": value["checkpoint_sha256"],
                "model_sha256": value["model_sha256_before"],
            }
            if arm != "warmup":
                result["fit_cells"] = statistics(
                    manifest["samples"]["fit"], value["fit"]["scores"], role="fit"
                )
                result["fit_development_auc_gap"] = [
                    {
                        "source_group": fit["source_group"],
                        "auc_gap": fit["metrics"]["roc_auc"] - dev["metrics"]["roc_auc"],
                    }
                    for fit, dev in zip(result["fit_cells"], cells, strict=True)
                ]
            if arm == "unpaired":
                result["against_paired"] = statistics(
                    manifest["samples"]["development"],
                    scores,
                    baseline=control["development"]["scores"],
                )
            results.append(result)
    passing = [
        arm
        for arm in schedule.ARMS
        if all(
            len(r["cells"]) == len(data.ORIGINS) and all(c["learning_gate"] for c in r["cells"])
            for r in results
            if r["arm"] == arm
        )
    ]
    minima = {
        arm: min(c["metrics"]["roc_auc"] for r in results if r["arm"] == arm for c in r["cells"])
        for arm in passing
    }
    selected = max(passing, key=lambda a: (minima[a], a == "paired")) if passing else None
    superior = all(
        c["paired_auc_delta_ci95"][0] > 0
        for r in results
        if r["arm"] == "unpaired"
        for c in r["against_paired"]
    )
    return {
        "trials": results,
        "passing_arms": passing,
        "selected_arm": selected,
        "learning_gate": bool(passing),
        "unpaired_superiority": superior,
        "accuracy_qualification": "unavailable",
        "deployed": False,
    }

core/jpeg_refine_state.py.utf8:
"""Numeric refinement snapshots with explicit branch ancestry; legacy v1 is rejected."""

from __future__ import annotations

import hashlib
import io
import json
import math
import stat
import zipfile

import numpy as np

from core import jpeg_refine_schedule as schedule
from core import srnet_model
from core.jpeg_scale import identity
from core.jpeg_study import SEEDS
from core.srnet_checkpoint import MAX_BYTES, MAX_META, PARAMETERS, header
from core.srnet_stream import regular_open


def capture(model, optimizer, metadata):
    arrays = {"model/" + k: v.detach().cpu().numpy().copy() for k, v in model.state_dict().items()}
    for name, parameter in model.named_parameters():
        for slot in ("exp_avg", "exp_inf", "step"):
            arrays[f"optimizer/{name}/{slot}"] = (
                optimizer.state[parameter][slot].detach().cpu().numpy().astype("<f4", copy=True)
            )
    result = {"metadata": dict(metadata), "arrays": arrays}
    validate(result)
    return result


def metadata(binding, arm, seed, stop, schedule_sha256, parent=None, warmup=None):
    return {
        "schema_version": "jpeg-refine-snapshot-v2",
        "binding": binding,
        "arm": arm,
        "seed": seed,
        "total_updates": stop,
        "new_updates": schedule.INTERVAL,
        "next_update": stop,
        "schedule_sha256": schedule_sha256,
        "parent_sha256": parent,
        "parent_binding": binding if parent else None,
        "warmup_sha256": warmup,
    }


def validate_metadata(meta):
    if (
        not isinstance(meta, dict)
        or set(meta)
        != {
            "schema_version",
            "binding",
            "arm",
            "seed",
            "total_updates",
            "new_updates",
            "next_update",
            "schedule_sha256",
            "parent_sha256",
            "parent_binding",
            "warmup_sha256",
        }
        or meta["schema_version"] != "jpeg-refine-snapshot-v2"
        or meta["arm"] not in ("warmup", *schedule.ARMS)
        or type(meta["seed"]) is not int
        or meta["seed"] not in SEEDS
        or type(meta["total_updates"]) is not int
        or type(meta["new_updates"]) is not int
        or meta["new_updates"] != schedule.INTERVAL
        or type(meta["next_update"]) is not int
        or meta["next_update"] != meta["total_updates"]
    ):
        raise ValueError("refine snapshot metadata invalid")
    stop = meta["total_updates"]
    if (
        stop % schedule.INTERVAL
        or not schedule.INTERVAL <= stop <= schedule.FINAL
        or ((stop <= schedule.WARMUP) != (meta["arm"] == "warmup"))
    ):
        raise ValueError("refine snapshot exposure/arm mismatch")
    for key in ("binding", "schedule_sha256"):
        identity(meta[key])
    if stop == schedule.INTERVAL:
        if meta["parent_sha256"] is not None or meta["parent_binding"] is not None:
            raise ValueError("refine initial snapshot cannot have a parent")
    else:
        identity(meta["parent_sha256"])
        if meta["parent_binding"] != meta["binding"]:
            raise ValueError("refine parent binding mismatch")
    if meta["arm"] == "warmup":
        if meta["warmup_sha256"] is not None:
            raise ValueError("refine warmup cannot import a historical model")
    else:
        identity(meta["warmup_sha256"])
        if stop == schedule.WARMUP + schedule.INTERVAL and (
            meta["warmup_sha256"] != meta["parent_sha256"]
        ):
            raise ValueError("refine branch must inherit its shared warmup")


def specs():
    result = {"model/" + k: (s, srnet_model.dtype(k)) for k, s in srnet_model.SHAPES.items()}
    for name, shape in PARAMETERS.items():
        for slot in ("exp_avg", "exp_inf", "step"):
            result[f"optimizer/{name}/{slot}"] = (() if slot == "step" else shape, np.dtype("<f4"))
    return result


def validate(snapshot):
    if not isinstance(snapshot, dict) or set(snapshot) != {"metadata", "arrays"}:
        raise ValueError("refine snapshot container invalid")
    meta = snapshot["metadata"]
    validate_metadata(meta)
    arrays = snapshot["arrays"]
    expected = specs()
    if not isinstance(arrays, dict) or set(arrays) != set(expected):
        raise ValueError("refine snapshot numeric keys invalid")
    steps = set()
    for name, (shape, dtype) in expected.items():
        value = arrays[name]
        if (
            not isinstance(value, np.ndarray)
            or value.shape != shape
            or value.dtype != dtype
            or not np.isfinite(value).all()
        ):
            raise ValueError("refine snapshot numeric shape/dtype/finite invalid")
        if name.endswith("/exp_inf") and np.any(value < 0):
            raise ValueError("refine snapshot negative infinity norm")
        if name.endswith("/step") or name.endswith("num_batches_tracked"):
            steps.add(float(value))
    if steps != {float(meta["total_updates"])}:
        raise ValueError("refine snapshot inconsistent model/BN/optimizer update counts")
    srnet_model.validate({k: arrays["model/" + k] for k in srnet_model.SHAPES})


def save(snapshot, path):
    from core.jpeg_study_data import fresh

    validate(snapshot)
    fresh(path)
    raw_meta = json.dumps(snapshot["metadata"], sort_keys=True, allow_nan=False).encode()
    buffer = io.BytesIO()
    np.savez(buffer, **snapshot["arrays"], __metadata__=np.frombuffer(raw_meta, dtype="u1"))
    raw = buffer.getvalue()
    if len(raw) > MAX_BYTES:
        raise ValueError("refine snapshot exceeds byte limit")
    with path.open("xb") as stream:
        stream.write(raw)
    return hashlib.sha256(raw).hexdigest()


def load(path, checksum, binding):
    try:
        return _load(path, checksum, binding)
    except (zipfile.BadZipFile, EOFError, OverflowError, RecursionError) as exc:
        raise ValueError("refine malformed numeric archive") from exc


def _load(path, checksum, binding):
    identity(checksum)
    identity(binding)
    with regular_open(path) as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES or hashlib.sha256(raw).hexdigest() != checksum:
        raise ValueError("refine snapshot checksum/byte limit mismatch")
    expected = specs()
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        members = archive.infolist()
        if (
            len(members) != len(expected) + 1
            or {m.filename for m in members}
            != {k + ".npy" for k in expected} | {"__metadata__.npy"}
            or sum(m.file_size for m in members) > MAX_BYTES
            or any(
                m.compress_type != zipfile.ZIP_STORED
                or m.flag_bits & 1
                or stat.S_ISLNK(m.external_attr >> 16)
                for m in members
            )
        ):
            raise ValueError("refine snapshot archive encoding/member/expansion bounds")
        for member in members:
            with archive.open(member) as stream:
                shape, _, dtype = header(stream)
                if member.filename == "__metadata__.npy":
                    if len(shape) != 1 or not 1 <= shape[0] <= MAX_META or dtype != np.dtype("u1"):
                        raise ValueError("refine snapshot metadata header invalid")
                elif (shape, dtype) != expected[member.filename[:-4]]:
                    raise ValueError("refine snapshot array header invalid")
                if stream.tell() + math.prod(shape) * dtype.itemsize != member.file_size:
                    raise ValueError("refine snapshot array length mismatch")
    with np.load(io.BytesIO(raw), allow_pickle=False, max_header_size=4096) as archive:
        meta = json.loads(archive["__metadata__"].tobytes())
        if not isinstance(meta, dict) or meta.get("binding") != binding:
            raise ValueError("refine snapshot recipe/source binding mismatch")
        result = {"metadata": meta, "arrays": {k: archive[k].copy() for k in expected}}
    validate(result)
    return result


def restore(
    snapshot,
    model,
    optimizer,
    binding,
    *,
    arm,
    seed,
    start,
    parent_sha256,
    schedule_sha256,
    warmup_sha256=None,
):
    import torch

    validate(snapshot)
    meta, arrays = snapshot["metadata"], snapshot["arrays"]
    expected_arm = "warmup" if start <= schedule.WARMUP else arm
    if (
        meta["binding"] != binding
        or meta["arm"] != expected_arm
        or meta["seed"] != seed
        or meta["total_updates"] != start
        or meta["schedule_sha256"] != schedule_sha256
        or (
            arm != "warmup"
            and (
                (start == schedule.WARMUP and warmup_sha256 != parent_sha256)
                or (start > schedule.WARMUP and meta["warmup_sha256"] != warmup_sha256)
            )
        )
    ):
        raise ValueError("refine resume source/parent/schedule/arm mismatch")
    identity(parent_sha256)
    model.load_state_dict(
        {k: torch.from_numpy(arrays["model/" + k].copy()) for k in srnet_model.SHAPES}, strict=True
    )
    for name, parameter in model.named_parameters():
        optimizer.state[parameter] = {
            slot: torch.from_numpy(arrays[f"optimizer/{name}/{slot}"].copy()).to(parameter.device)
            for slot in ("exp_avg", "exp_inf", "step")
        }
    return start

core/jpeg_residual.py.utf8:
"""Experimental block-DCT residual/parity descriptor; not DCTR, JRM or SRNet."""

from __future__ import annotations

import numpy as np

from core import jpeg_features as jpeg
from core.jpeg_context import FEATURE_NAMES as CONTEXT_NAMES
from core.jpeg_context import summary_context_features

FEATURE_VERSION = "jpeg-dct-residual-parity-v1"
MODES = tuple(
    sorted(((u, v) for u in range(8) for v in range(8)), key=lambda mode: (sum(mode), *mode))[:32]
)
FEATURE_NAMES = (
    CONTEXT_NAMES
    + tuple(
        f"dct_{u}_{v}_{direction}_residual_{b}"
        for u, v in MODES
        for direction in ("h", "v")
        for b in range(-2, 3)
    )
    + tuple(
        f"dct_{u}_{v}_{direction}_parity_{p}_residual_{b}"
        for u, v in MODES
        for direction in ("h", "v")
        for p in range(2)
        for b in range(-2, 3)
    )
    + tuple(f"dc_abs_{b}" for b in range(8))
)


def coefficient_features(coefficients: np.ndarray, quantization: np.ndarray) -> list[float]:
    # Reuse the signed-16-bit/dimension/budget guards before subtraction or parity.
    prefix = summary_context_features(jpeg.coefficient_features(coefficients, quantization))
    values = coefficients.astype(np.int64)
    residuals = []
    joints = []
    for u, v in MODES:
        plane = values[:, :, u, v]
        for first, second in ((plane[:, :-1], plane[:, 1:]), (plane[:-1, :], plane[1:, :])):
            residual = np.clip(second - first, -2, 2) + 2
            counts = np.bincount(residual.ravel(), minlength=5)
            residuals.extend((counts / counts.sum()).tolist())
            counts = np.bincount(((first & 1) * 5 + residual).ravel(), minlength=10)
            joints.extend((counts / counts.sum()).tolist())
    counts = np.bincount(np.minimum(np.abs(values[:, :, 0, 0]), 7).ravel(), minlength=8)
    return np.round([*prefix, *residuals, *joints, *(counts / counts.sum())], 8).tolist()


def jpeg_residual_features(data: bytes) -> list[float]:
    return jpeg.run_feature_worker(data, "core.jpeg_residual", FEATURE_NAMES)


if __name__ == "__main__":
    raise SystemExit(jpeg.main(coefficient_features))

core/jpeg_scale.py.utf8:
"""Metadata-only whole-lineage layout for bounded JPEG preparation blocks."""

from __future__ import annotations

import hashlib
import re
from collections import defaultdict
from pathlib import PurePosixPath

BLOCK_ORIGINALS = 128
METHODS = ("JUNIWARD", "UERD")


def identity(value):
    if not isinstance(value, str) or not re.fullmatch("[a-f0-9]{64}", value):
        raise ValueError("invalid JPEG scale identity")
    return value


def safe_name(value):
    if not isinstance(value, str) or not value or "\\" in value:
        raise ValueError("unsafe scale source path")
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts:
        raise ValueError("unsafe scale source path")


def layout(alaska, boss, quarantine, reserved):
    """Preserve complete source groups and roles; never select by model score."""
    if (
        not isinstance(alaska, list)
        or not 4 <= len(alaska) <= 4000
        or not isinstance(boss, list)
        or not 2 <= len(boss) <= 1000
        or not isinstance(quarantine, set)
        or not isinstance(reserved, set)
    ):
        raise ValueError("JPEG scale source limits")
    for key in quarantine | reserved:
        identity(key)
    groups: dict[str, list] = defaultdict(list)
    seen: dict[str, str] = {}
    for row in alaska:
        if not isinstance(row, dict):
            raise ValueError("invalid ALASKA scale row")
        safe_name(row.get("path"))
        digest, lineage = identity(row.get("sha256")), identity(row.get("lineage"))
        if (
            row.get("source_group") != "ALASKA2"
            or row.get("format") != "JPEG"
            or row.get("split") not in ("train", "validation")
            or row.get("label") not in ("cover", "stego")
            or {digest, lineage} & reserved
            or seen.setdefault(digest, lineage) != lineage
        ):
            raise ValueError("ALASKA scale roles or reserved overlap")
        groups[lineage].append(row)
    if not quarantine <= groups.keys():
        raise ValueError("unknown quarantine lineage")
    usable = []
    for lineage, rows in groups.items():
        covers = [r for r in rows if r["label"] == "cover"]
        if (
            len(rows) != 4
            or len(covers) != 1
            or covers[0]["sha256"] != lineage
            or covers[0].get("method") is not None
            or {r.get("method") for r in rows} != {None, "JMiPOD", *METHODS}
            or len({r["split"] for r in rows}) != 1
            or any(r["label"] != ("cover" if r.get("method") is None else "stego") for r in rows)
        ):
            raise ValueError("incomplete ALASKA scale lineage")
        unchanged = any(r["label"] == "stego" and r["sha256"] == lineage for r in rows)
        if unchanged != (lineage in quarantine):
            raise ValueError("quarantine does not match unchanged ALASKA pairs")
        if lineage not in quarantine:
            if len({r["sha256"] for r in rows}) != 4:
                raise ValueError("duplicate ALASKA method bytes")
            usable.append(lineage)
    if not usable:
        raise ValueError("no eligible ALASKA scale lineage")
    boss_seen: set[str] = set()
    for row in boss:
        if not isinstance(row, dict):
            raise ValueError("invalid BOSS scale row")
        safe_name(row.get("path"))
        digest = identity(row.get("sha256"))
        if (
            row.get("source_group") != "BOSSbase-1.01"
            or row.get("label") != "cover"
            or row.get("method") is not None
            or row.get("split") not in ("train", "validation")
            or row.get("lineage") != digest
            or digest in boss_seen | reserved | set(seen)
        ):
            raise ValueError("BOSS scale roles or duplicate/reserved identity")
        boss_seen.add(digest)
    ordered = {
        "ALASKA2": sorted(
            usable, key=lambda key: hashlib.sha256(("scale:20261008:" + key).encode()).digest()
        ),
        "BOSSbase-1.01": [
            r["sha256"]
            for r in sorted(
                boss,
                key=lambda r: hashlib.sha256(
                    ("jpeg-context:20261006:" + r["sha256"]).encode()
                ).digest(),
            )
        ],
    }
    blocks = []
    for source, keys in ordered.items():
        for offset in range(0, len(keys), BLOCK_ORIGINALS):
            lineages = keys[offset : offset + BLOCK_ORIGINALS]
            if source == "BOSSbase-1.01" and len(lineages) < 2:
                raise ValueError("BOSS block needs at least two originals; no silent truncation")
            blocks.append({"source_group": source, "offset": offset, "lineages": lineages})
    return blocks

core/jpeg_study_optimizer.py.utf8:
"""Isolated author-rule Adamax and convolution-only L2 research controls.

Equations are independently implemented, not copied from research-use SRNet.
This is not a claim of whole-model TensorFlow parity. Legacy trainers stay intact.
"""

from __future__ import annotations

import math

RULE = "srnet-author-adamax-no-bias-correction-v1"
L2_SCALE = 2e-4


def validate_reference(parameters, states, *, consolidate=None):
    """Complete pre-update checks; batch CUDA booleans, never FP arithmetic."""
    import torch

    checks = []
    for parameter in parameters:
        gradient = parameter.grad
        if (parameter.dtype != torch.float32 or gradient is None
            or gradient.is_sparse or gradient.dtype != torch.float32):
            raise ValueError("reference Adamax requires finite dense FP32 gradients")
        for value in (parameter, gradient):
            checks.append(("gradients", torch.isfinite(value).all()))
        state = states[parameter]
        if not state:
            continue
        if (set(state) != {"step", "exp_avg", "exp_inf"}
            or state["exp_avg"].shape != parameter.shape
            or state["exp_inf"].shape != parameter.shape
            or state["step"].shape != torch.Size([])
            or any(v.dtype != torch.float32 for v in state.values())):
            raise ValueError("reference Adamax state invalid")
        checks.extend(("state", torch.isfinite(value).all()) for value in state.values())
        checks.append(("state", (state["exp_inf"] >= 0).all()))
        step = state["step"]
        checks.append(("state", (step >= 1) & (step == step.floor())))
    by_device: dict[torch.device, list[int]] = {}
    for index, (_, value) in enumerate(checks):
        by_device.setdefault(value.device, []).append(index)
    results = [False] * len(checks)
    for device, indices in by_device.items():
        batched = device.type == "cuda" if consolidate is None else consolidate
        if batched:
            flags = torch.stack([checks[index][1] for index in indices]).cpu().tolist()
        else:
            flags = [bool(checks[index][1]) for index in indices]
        for index, valid in zip(indices, flags, strict=True):
            results[index] = valid
    for (kind, _), valid in zip(checks, results, strict=True):
        if not valid:
            if kind == "gradients":
                raise ValueError("reference Adamax requires finite dense FP32 gradients")
            raise ValueError("reference Adamax state invalid")


def optimizer(model, *, reference=False, corrected_l2=False, learning_rate=0.001):
    import torch

    if (
        type(reference) is not bool or type(corrected_l2) is not bool
        or type(learning_rate) not in (float, int)
        or not math.isfinite(learning_rate) or not 0 < learning_rate <= 0.001
    ):
        raise ValueError("invalid research optimizer settings")
    decay = 0.0 if corrected_l2 else 0.0001
    if not reference:
        return torch.optim.Adamax(
            model.parameters(), lr=learning_rate, weight_decay=decay,
            betas=(0.9, 0.999), eps=1e-8, foreach=False,
        )

    class ReferenceAdamax(torch.optim.Optimizer):
        def __init__(self, parameters):
            super().__init__(parameters, {"lr": learning_rate, "weight_decay": decay})

        @torch.no_grad()
        def step(self, closure=None):
            if closure is not None:
                raise ValueError("research optimizer does not execute closures")
            # Validate every parameter/gradient before changing any parameter.
            validate_reference([p for group in self.param_groups for p in group["params"]],
                               self.state)
            for group in self.param_groups:
                for parameter in group["params"]:
                    gradient = parameter.grad.add(parameter, alpha=group["weight_decay"])
                    state = self.state[parameter]
                    if not state:
                        state["step"] = torch.zeros((), device=parameter.device)
                        state["exp_avg"] = torch.zeros_like(parameter)
                        state["exp_inf"] = torch.zeros_like(parameter)
                    state["step"].add_(1)
                    state["exp_avg"].mul_(0.9).add_(gradient, alpha=0.1)
                    torch.maximum(
                        state["exp_inf"].mul_(0.999).add_(1e-8), gradient.abs(),
                        out=state["exp_inf"],
                    )
                    parameter.addcdiv_(state["exp_avg"], state["exp_inf"], value=-group["lr"])

    return ReferenceAdamax(model.parameters())


def convolution_penalty(model):
    """2e-4 * half squared norm: gradient 2e-4 W, excluding BN/bias/FC."""
    import torch

    weights = [m.weight for m in model.modules() if isinstance(m, torch.nn.Conv2d)]
    if not weights:
        raise ValueError("convolution-only regularization requires convolution weights")
    return sum(w.square().sum() for w in weights) * (L2_SCALE / 2)

core/jpeg_study_process.py.utf8:
"""Bounded owned research workers and portable numeric failure evidence."""

from __future__ import annotations

import os
import signal
import subprocess
import tempfile
import time
from contextlib import suppress
from dataclasses import dataclass
from pathlib import Path

MAX_REPORT = 256 * 1024
MAX_SIMULATION_REPORT = 768 * 1024


@dataclass(frozen=True)
class WorkerExit:
    returncode: int
    stdout_bytes: int

    def record(self):
        number = -self.returncode if self.returncode < 0 else None
        name = None
        if number is not None:
            with suppress(ValueError):
                name = signal.Signals(number).name
        return {"returncode": self.returncode, "signal": number,
                "signal_name": name,
                "stdout_bytes": self.stdout_bytes}


class WorkerFailure(ValueError):
    def __init__(self, execution: WorkerExit, *, output_limit=False):
        self.execution = execution
        if output_limit:
            self.reason = "worker_output_limit"
        elif execution.returncode == -signal.SIGXCPU:
            self.reason = "worker_cpu_limit"
        elif execution.returncode == -signal.SIGXFSZ:
            self.reason = "worker_file_size_limit"
        elif execution.returncode < 0:
            # SIGKILL alone is not evidence of OOM or a CPU hard-limit event.
            self.reason = "worker_signalled"
        elif execution.returncode:
            self.reason = "worker_exit_nonzero"
        else:
            self.reason = "worker_empty_output"
        super().__init__("study worker failed: " + self.reason)

    def unavailable(self):
        return {"status": "unavailable", "reason": self.reason,
                "worker_execution": self.execution.record()}


def run(command, *, cwd: Path, timeout, cancelled=lambda: False,
        payload=None, maximum=MAX_REPORT):
    """Retain exit/signal evidence, never raw command, output or stderr secrets."""
    if payload is not None and len(payload) > 1024**2:
        raise ValueError("study child input exceeds bounds")
    if maximum not in (MAX_REPORT, MAX_SIMULATION_REPORT):
        raise ValueError("study child output limit invalid")
    with tempfile.TemporaryFile() as output, tempfile.TemporaryFile() as input_file:
        if payload is not None:
            input_file.write(payload)
            input_file.seek(0)
        process = subprocess.Popen(  # noqa: S603 - fixed module and arguments, no shell
            command, cwd=cwd, stdin=input_file if payload is not None else subprocess.DEVNULL,
            stdout=output, stderr=subprocess.DEVNULL, start_new_session=True,
            env={**os.environ, "OMP_NUM_THREADS": "2", "OPENBLAS_NUM_THREADS": "1",
                 "NUMBA_NUM_THREADS": "1", "CUBLAS_WORKSPACE_CONFIG": ":4096:8"},
        )
        started, overflow = time.monotonic(), False
        try:
            while process.poll() is None:
                if cancelled():
                    raise InterruptedError("study cancelled")
                if time.monotonic() - started >= timeout:
                    raise TimeoutError("study worker deadline exceeded")
                if os.fstat(output.fileno()).st_size > maximum:
                    overflow = True
                    break
                time.sleep(0.1)
        finally:
            # Kill descendants even if their parent has already exited.
            with suppress(ProcessLookupError):
                os.killpg(process.pid, signal.SIGKILL)
            process.wait()
        size = os.fstat(output.fileno()).st_size
        if overflow or size > maximum or process.returncode or not size:
            raise WorkerFailure(WorkerExit(process.returncode, size),
                                output_limit=overflow or size > maximum)
        output.seek(0)
        raw = output.read(maximum + 1)
        if len(raw) > maximum:
            raise WorkerFailure(WorkerExit(process.returncode, len(raw)), output_limit=True)
        return raw

core/jpeg_study_state.py.utf8:
"""New recipe-bound numeric snapshots; never reinterpret legacy checkpoints."""

from __future__ import annotations

import hashlib
import io
import json
import math
import stat
import zipfile

import numpy as np

from core import srnet_model
from core.jpeg_scale import identity
from core.srnet_checkpoint import MAX_BYTES, MAX_META, PARAMETERS, header
from core.srnet_stream import regular_open


def capture(model, optimizer, binding, presented_rows):
    arrays = {"model/" + k: v.detach().cpu().numpy().copy()
              for k, v in model.state_dict().items()}
    for name, parameter in model.named_parameters():
        for slot in ("exp_avg", "exp_inf", "step"):
            arrays[f"optimizer/{name}/{slot}"] = (
                optimizer.state[parameter][slot].detach().cpu().numpy().astype("<f4", copy=True)
            )
    result = {"metadata": {"schema_version": "jpeg-study-snapshot-v1",
                           "binding": binding, "presented_rows": presented_rows},
              "arrays": arrays}
    validate(result)
    return result


def specs():
    result = {"model/" + k: (s, srnet_model.dtype(k)) for k, s in srnet_model.SHAPES.items()}
    for name, shape in PARAMETERS.items():
        for slot in ("exp_avg", "exp_inf", "step"):
            result[f"optimizer/{name}/{slot}"] = (
                () if slot == "step" else shape, np.dtype("<f4")
            )
    return result


def validate(snapshot):
    if not isinstance(snapshot, dict) or set(snapshot) != {"metadata", "arrays"}:
        raise ValueError("study snapshot container invalid")
    meta = snapshot["metadata"]
    if (not isinstance(meta, dict)
        or set(meta) != {"schema_version", "binding", "presented_rows"}
        or meta["schema_version"] != "jpeg-study-snapshot-v1"
        or type(meta["presented_rows"]) is not int
        or meta["presented_rows"] not in {16384, 32768}):
        raise ValueError("study snapshot metadata invalid")
    identity(meta["binding"])
    arrays = snapshot["arrays"]
    expected = specs()
    if not isinstance(arrays, dict) or set(arrays) != set(expected):
        raise ValueError("study snapshot numeric keys invalid")
    steps = set()
    for name, (shape, dtype) in expected.items():
        value = arrays[name]
        if (not isinstance(value, np.ndarray) or value.shape != shape
            or value.dtype != dtype or not np.isfinite(value).all()):
            raise ValueError("study snapshot numeric shape/dtype/finite invalid")
        if name.endswith("/exp_inf") and np.any(value < 0):
            raise ValueError("study snapshot negative infinity norm")
        if name.endswith("/step") or name.endswith("num_batches_tracked"):
            steps.add(float(value))
    if len(steps) != 1 or next(iter(steps)) not in {
        meta["presented_rows"] // n for n in (4, 8, 16, 32)
    }:
        raise ValueError("study snapshot inconsistent update counts")
    srnet_model.validate({k: arrays["model/" + k] for k in srnet_model.SHAPES})


def save(snapshot, path):
    from core.jpeg_study_data import fresh

    validate(snapshot)
    fresh(path)
    raw_meta = json.dumps(snapshot["metadata"], sort_keys=True, allow_nan=False).encode()
    buffer = io.BytesIO()
    np.savez(buffer, **snapshot["arrays"], __metadata__=np.frombuffer(raw_meta, dtype="u1"))
    raw = buffer.getvalue()
    if len(raw) > MAX_BYTES:
        raise ValueError("study snapshot exceeds byte limit")
    with path.open("xb") as stream:
        stream.write(raw)
    return hashlib.sha256(raw).hexdigest()


def load(path, checksum, binding):
    identity(checksum)
    identity(binding)
    with regular_open(path) as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES or hashlib.sha256(raw).hexdigest() != checksum:
        raise ValueError("study snapshot checksum/byte limit mismatch")
    expected = specs()
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        members = archive.infolist()
        if (len(members) != len(expected) + 1
            or {m.filename for m in members} != {k + ".npy" for k in expected} | {
                "__metadata__.npy"
            } or sum(m.file_size for m in members) > MAX_BYTES
            or any(m.compress_type != zipfile.ZIP_STORED or m.flag_bits & 1
                   or stat.S_ISLNK(m.external_attr >> 16) for m in members)):
            raise ValueError("study snapshot archive encoding/member/expansion bounds")
        for member in members:
            with archive.open(member) as stream:
                shape, _, dtype = header(stream)
                if member.filename == "__metadata__.npy":
                    if len(shape) != 1 or not 1 <= shape[0] <= MAX_META or dtype != np.dtype("u1"):
                        raise ValueError("study snapshot metadata header invalid")
                elif (shape, dtype) != expected[member.filename[:-4]]:
                    raise ValueError("study snapshot array header invalid")
                if stream.tell() + math.prod(shape) * dtype.itemsize != member.file_size:
                    raise ValueError("study snapshot array length mismatch")
    with np.load(io.BytesIO(raw), allow_pickle=False, max_header_size=4096) as archive:
        meta = json.loads(archive["__metadata__"].tobytes())
        if not isinstance(meta, dict) or meta.get("binding") != binding:
            raise ValueError("study snapshot recipe/source binding mismatch")
        result = {"metadata": meta, "arrays": {k: archive[k].copy() for k in expected}}
    validate(result)
    return result


def restore(snapshot, model, optimizer, binding, rows):
    import torch

    validate(snapshot)
    meta, arrays = snapshot["metadata"], snapshot["arrays"]
    if meta["binding"] != binding or type(rows) is not int or rows not in (4, 8, 16, 32):
        raise ValueError("study resume binding/batch mismatch")
    updates = meta["presented_rows"] // rows
    if any(float(arrays[f"optimizer/{name}/step"]) != updates for name in PARAMETERS):
        raise ValueError("study resume update/batch mismatch")
    model.load_state_dict({k: torch.from_numpy(arrays["model/" + k].copy())
                          for k in srnet_model.SHAPES}, strict=True)
    for name, parameter in model.named_parameters():
        # Noncapturable PyTorch Adamax creates its step scalar on CPU even for
        # CUDA parameters. Preserve that placement on resume: identical numbers,
        # without introducing one extra device-to-host scalar read per parameter.
        step_device = ("cpu" if isinstance(optimizer, torch.optim.Adamax)
                       and not optimizer.defaults.get("capturable", False) else parameter.device)
        optimizer.state[parameter] = {
            slot: torch.from_numpy(arrays[f"optimizer/{name}/{slot}"].copy()).to(
                step_device if slot == "step" else parameter.device)
            for slot in ("exp_avg", "exp_inf", "step")
        }
    return meta["presented_rows"]

core/models.py.utf8:
"""Explicit, signed local model installation and runtime discovery."""

from __future__ import annotations

import base64
import hashlib
import json
import math
import os
import shutil
import tempfile
import urllib.request
from pathlib import Path
from typing import Any

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from core.database import Database, utc_now
from core.ensemble import ModelScore


class ModelError(Exception):
    pass


class ModelVerificationError(ModelError):
    pass


class ModelRegistry:
    """Manage opt-in ONNX files. Installation never performs network access."""

    SUPPORTED_DOMAINS = frozenset({"spatial-srnet-v1", "jpeg-srnet-v1"})
    MAX_DOWNLOAD_BYTES = 2 * 1024 * 1024 * 1024

    def __init__(self, database: Database, root: Path) -> None:
        self.database = database
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    def list(self) -> list[dict[str, Any]]:
        with self.database.connect() as connection:
            rows = connection.execute(
                "SELECT * FROM models ORDER BY domain, id, version"
            ).fetchall()
        values = []
        for row in rows:
            value = dict(row)
            value["manifest"] = json.loads(value.pop("manifest_json"))
            values.append(value)
        return values

    @staticmethod
    def catalog(path: Path | None = None) -> dict[str, Any]:
        catalog_path = (
            path or Path(__file__).resolve().parents[1] / "steganography" / "model_catalog.json"
        )
        try:
            value = json.loads(Path(catalog_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise ModelVerificationError(f"cannot read model catalog: {exc}") from exc
        if value.get("schema_version") != "1.0" or not isinstance(value.get("models"), list):
            raise ModelVerificationError("unsupported or malformed model catalog")
        return value

    def install_catalog(
        self,
        target: str,
        *,
        accept_license: bool,
        catalog_path: Path | None = None,
    ) -> dict[str, Any]:
        """Explicitly download and verify one catalog model; never called automatically."""
        if not accept_license:
            raise ModelVerificationError("--accept-license is required for catalog models")
        catalog = self.catalog(catalog_path)
        entry = next(
            (
                item
                for item in catalog["models"]
                if f"{item.get('id')}@{item.get('version')}" == target
            ),
            None,
        )
        if entry is None:
            raise ModelVerificationError(f"model is not present in catalog: {target}")
        manifest = entry.get("manifest")
        public_key = entry.get("public_key")
        download_url = str(entry.get("download_url") or "")
        if (
            not isinstance(manifest, dict)
            or not public_key
            or not download_url.startswith("https://")
        ):
            raise ModelVerificationError("catalog entry lacks a signed manifest or HTTPS URL")
        self.verify_manifest(manifest, public_key=public_key)
        filename = Path(str(manifest.get("file", "")))
        if filename.name != str(filename) or not filename.name:
            raise ModelVerificationError("catalog manifest has an unsafe model filename")
        with tempfile.TemporaryDirectory(prefix="steganography-model-") as temporary_name:
            temporary = Path(temporary_name)
            model_path = temporary / filename.name
            _download_https(download_url, model_path, maximum=self.MAX_DOWNLOAD_BYTES)
            if _sha256(model_path) != manifest.get("sha256"):
                raise ModelVerificationError("downloaded model SHA-256 does not match manifest")
            manifest_path = temporary / "manifest.json"
            manifest_path.write_text(json.dumps(manifest), encoding="utf-8")
            return self.install(manifest_path, public_key=public_key)

    def install(
        self,
        manifest_path: Path,
        *,
        public_key: bytes | str | Path,
    ) -> dict[str, Any]:
        """Verify a local manifest and adjacent model before atomically installing."""
        manifest_path = Path(manifest_path)
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        self.verify_manifest(manifest, public_key=public_key)
        required = {
            "id",
            "version",
            "domain",
            "file",
            "sha256",
            "license",
            "model_card",
            "benchmark_summary",
        }
        missing = sorted(required - manifest.keys())
        if missing:
            raise ModelVerificationError(f"manifest missing fields: {', '.join(missing)}")
        if manifest["domain"] not in self.SUPPORTED_DOMAINS:
            raise ModelVerificationError(f"unsupported model domain: {manifest['domain']}")
        filename = Path(str(manifest["file"]))
        if filename.name != str(manifest["file"]):
            raise ModelVerificationError("model file must be adjacent to the manifest")
        source = manifest_path.parent / filename
        if not source.is_file():
            raise ModelVerificationError(f"model file is missing: {filename}")
        digest = _sha256(source)
        if digest != manifest["sha256"]:
            raise ModelVerificationError("model SHA-256 does not match manifest")
        destination_dir = (
            self.root / _safe_component(manifest["id"]) / _safe_component(manifest["version"])
        )
        destination = destination_dir / filename.name
        destination_dir.mkdir(parents=True, exist_ok=True)
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{filename.name}.", dir=destination_dir
        )
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            shutil.copyfile(source, temporary)
            os.replace(temporary, destination)
        finally:
            temporary.unlink(missing_ok=True)
        canonical = json.dumps(manifest, sort_keys=True, separators=(",", ":"))
        with self.database.transaction() as connection:
            connection.execute(
                """INSERT INTO models
                   (id, domain, version, state, path, sha256, manifest_json, installed_at)
                   VALUES (?, ?, ?, 'installed', ?, ?, ?, ?)
                   ON CONFLICT(id, version) DO UPDATE SET state='installed', path=excluded.path,
                     sha256=excluded.sha256, manifest_json=excluded.manifest_json,
                     installed_at=excluded.installed_at""",
                (
                    manifest["id"],
                    manifest["domain"],
                    manifest["version"],
                    str(destination),
                    digest,
                    canonical,
                    utc_now(),
                ),
            )
            self.database.audit(
                "model.installed",
                object_type="model",
                object_id=f"{manifest['id']}@{manifest['version']}",
                details={"domain": manifest["domain"], "sha256": digest},
                connection=connection,
            )
        return self.get(manifest["id"], manifest["version"])

    def get(self, model_id: str, version: str) -> dict[str, Any]:
        with self.database.connect() as connection:
            row = connection.execute(
                "SELECT * FROM models WHERE id=? AND version=?", (model_id, version)
            ).fetchone()
        if row is None:
            raise LookupError(f"unknown model {model_id}@{version}")
        value = dict(row)
        value["manifest"] = json.loads(value.pop("manifest_json"))
        return value

    def verify_installed(self, model_id: str, version: str) -> bool:
        model = self.get(model_id, version)
        path = Path(model["path"])
        valid = path.is_file() and _sha256(path) == model["sha256"]
        if not valid:
            with self.database.transaction() as connection:
                connection.execute(
                    "UPDATE models SET state='invalid' WHERE id=? AND version=?",
                    (model_id, version),
                )
        return valid

    def score(
        self,
        model_id: str,
        version: str,
        tensor: Any,
        *,
        domain: str,
    ) -> ModelScore:
        """Run an installed ONNX model with CPU-default provider selection."""
        try:
            model = self.get(model_id, version)
        except LookupError as exc:
            return ModelScore(model_id, domain, None, "unavailable", error=str(exc))
        if model["domain"] != domain:
            return ModelScore(
                model_id,
                domain,
                None,
                "unsupported",
                error=f"model domain is {model['domain']}",
            )
        if not self.verify_installed(model_id, version):
            return ModelScore(model_id, domain, None, "error", error="model integrity check failed")
        try:
            import numpy as np
            import onnxruntime as ort
        except ImportError:
            return ModelScore(
                model_id,
                domain,
                None,
                "unavailable",
                error="onnxruntime is not installed",
            )
        available = ort.get_available_providers()
        requested = os.environ.get("STEGANO_ONNX_PROVIDER", "CPU").upper()
        provider = "CPUExecutionProvider"
        if requested == "CUDA" and "CUDAExecutionProvider" in available:
            provider = "CUDAExecutionProvider"
        try:
            session = ort.InferenceSession(model["path"], providers=[provider])
            input_name = session.get_inputs()[0].name
            output = session.run(None, {input_name: tensor})[0]
            raw = float(np.asarray(output).reshape(-1)[0])
            probability = raw if 0 <= raw <= 1 else 1 / (1 + math.exp(-raw))
            actual_provider = session.get_providers()[0]
            return ModelScore(
                model_id,
                domain,
                probability,
                "ok",
                execution_provider=actual_provider,
                calibrated=bool(model["manifest"].get("calibrated", False)),
            )
        except Exception as exc:
            return ModelScore(
                model_id,
                domain,
                None,
                "error",
                execution_provider=provider,
                error=f"{type(exc).__name__}: {exc}",
            )

    @staticmethod
    def verify_manifest(manifest: dict[str, Any], *, public_key: bytes | str | Path) -> None:
        signature_value = manifest.get("signature")
        if not isinstance(signature_value, str):
            raise ModelVerificationError("manifest has no Ed25519 signature")
        unsigned = dict(manifest)
        unsigned.pop("signature", None)
        canonical = json.dumps(unsigned, sort_keys=True, separators=(",", ":")).encode()
        try:
            signature = base64.b64decode(signature_value, validate=True)
            key_bytes = _key_bytes(public_key)
            Ed25519PublicKey.from_public_bytes(key_bytes).verify(signature, canonical)
        except (ValueError, InvalidSignature) as exc:
            raise ModelVerificationError("invalid Ed25519 manifest signature") from exc

    @staticmethod
    def runtime_status() -> dict[str, Any]:
        try:
            import onnxruntime as ort
        except ImportError:
            return {
                "status": "unavailable",
                "reason": "onnxruntime is not installed",
                "available_providers": [],
                "selected_provider": None,
            }
        providers = ort.get_available_providers()
        requested = os.environ.get("STEGANO_ONNX_PROVIDER", "CPU").upper()
        selected = "CPUExecutionProvider"
        if requested == "CUDA" and "CUDAExecutionProvider" in providers:
            selected = "CUDAExecutionProvider"
        return {
            "status": "available",
            "available_providers": providers,
            "selected_provider": selected,
        }


def _key_bytes(value: bytes | str | Path) -> bytes:
    if isinstance(value, bytes):
        raw = value
    else:
        candidate = Path(value)
        try:
            is_file = len(str(value)) < 4096 and candidate.is_file()
        except OSError:
            is_file = False
        raw = candidate.read_bytes() if is_file else str(value).encode()
    if len(raw) == 32:
        return raw
    raw = raw.strip()
    if len(raw) == 32:
        return raw
    try:
        decoded = base64.b64decode(raw, validate=True)
    except ValueError as exc:
        raise ModelVerificationError("public key must be raw or base64 Ed25519 bytes") from exc
    if len(decoded) != 32:
        raise ModelVerificationError("Ed25519 public key must be 32 bytes")
    return decoded


def _safe_component(value: str) -> str:
    allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"
    if not value or any(character not in allowed for character in value):
        raise ModelVerificationError(f"unsafe model identifier: {value!r}")
    return value


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _download_https(url: str, destination: Path, *, maximum: int) -> None:
    request = urllib.request.Request(  # noqa: S310 - caller requires an HTTPS URL
        url, headers={"User-Agent": "steganography-model-installer"}
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:  # noqa: S310 - HTTPS checked
            final_url = response.geturl()
            if not final_url.startswith("https://"):
                raise ModelVerificationError("model download redirected outside HTTPS")
            size = 0
            with destination.open("xb") as output:
                while chunk := response.read(1024 * 1024):
                    size += len(chunk)
                    if size > maximum:
                        raise ModelVerificationError("model download exceeds the byte limit")
                    output.write(chunk)
    except ModelVerificationError:
        destination.unlink(missing_ok=True)
        raise
    except OSError as exc:
        destination.unlink(missing_ok=True)
        raise ModelVerificationError(f"model download failed: {exc}") from exc

core/nonjpeg_audit.py.utf8:
"""Independent scalar corpus audit. Does not import the preparation generator."""

from __future__ import annotations

import argparse
import hashlib
import io
import json
import os
import random
import re
import resource
import stat
import sys
import time
import wave
from collections import Counter
from pathlib import Path
from typing import Any

from PIL import Image


def read(path, limit=32 * 1024**2):
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("audit symlink")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        os.close(fd)
        raise ValueError("audit regular file")
    with os.fdopen(fd, "rb") as stream:
        raw = stream.read(limit + 1)
    if not raw or len(raw) > limit:
        raise ValueError("audit byte bound")
    return raw


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def member(name):
    if (
        not isinstance(name, str)
        or not re.fullmatch(r"[A-Za-z0-9_.-]{1,180}", name)
        or name in (".", "..")
    ):
        raise ValueError("audit unsafe member")
    return name


def decode(raw, origin, fmt=None):
    if origin in ("DIV2K", "BOWS2"):
        with Image.open(io.BytesIO(raw)) as image:
            mode = "RGB" if origin == "DIV2K" else "L"
            if (
                image.mode != mode
                or image.width * image.height > 8_000_000
                or min(image.size) < 256
                or getattr(image, "n_frames", 1) != 1
                or image.format != (fmt or ("PNG" if mode == "RGB" else "PPM"))
            ):
                raise ValueError("audit image representation")
            if fmt is None:
                x, y = (image.width - 256) // 2, (image.height - 256) // 2
                return image.crop((x, y, x + 256, y + 256)).tobytes(), (mode, x, y)
            if image.size != (256, 256):
                raise ValueError("audit saved image size")
            return image.tobytes(), (mode,)
    with wave.open(io.BytesIO(raw)) as audio:
        p = audio.getparams()
        if (
            p.nchannels != 1
            or p.sampwidth != 2
            or p.comptype != "NONE"
            or p.framerate != (8000 if origin == "FSDD-v1.0.10" else 44100)
            or not 160 <= p.nframes <= 220500
        ):
            raise ValueError("audit PCM contract")
        pcm = audio.readframes(p.nframes)
        if len(pcm) != p.nframes * 2:
            raise ValueError("audit PCM truncation")
    return pcm, (p.framerate, p.nframes)


def audit(config_path: Path, root: Path, expected_sources: dict[str, str]):
    started = time.monotonic()

    def deadline():
        if time.monotonic() - started > 1800:
            raise TimeoutError("audit deadline")

    config_raw = read(config_path, 8 * 1024**2)
    cfg = json.loads(config_raw)
    if (
        not isinstance(cfg, dict)
        or set(cfg) != {"schema_version", "sources", "counts"}
        or not isinstance(cfg["sources"], list)
        or not 1 <= len(cfg["sources"]) <= 5
        or not isinstance(cfg["counts"], dict)
        or set(cfg["counts"]) != {"train", "validation"}
        or any(
            type(cfg["counts"][role]) is not int or not 1 <= cfg["counts"][role] <= maximum
            for role, maximum in (("train", 32), ("validation", 8))
        )
    ):
        raise ValueError("audit config bounds")
    manifest_raw = read(root / "manifest.json", 8 * 1024**2)
    corpus = json.loads(manifest_raw)
    if (
        cfg.get("schema_version") != "nonjpeg-preparation-config-v1"
        or corpus.get("schema_version") != "nonjpeg-controlled-data-v1"
        or corpus.get("status") != "prepared_not_audited"
        or corpus.get("config_sha256") != digest(config_raw)
        or corpus.get("source_sha256") != expected_sources
        or corpus.get("seed") != 20261012
        or corpus.get("model_trained") is not False
        or corpus.get("optimizer_updates") != 0
        or corpus.get("detector_scored") is not False
        or corpus.get("execution", {}).get("python") != sys.version.split()[0]
    ):
        raise ValueError("audit contract binding")
    speakers = {
        "lucas": "train",
        "nicolas": "train",
        "theo": "validation",
        "yweweler": "validation",
        "george": "test",
        "jackson": "test",
    }
    candidates: dict[tuple[str, str], list[Any]] = {}
    source_bindings: list[dict[str, Any]] = []
    groups: dict[tuple[str, ...], str] = {}
    identities: set[str] = set()
    source_rows = 0
    for binding in cfg["sources"]:
        path = Path(binding["manifest"])
        raw = read(path, 8 * 1024**2)
        source = json.loads(raw)
        if digest(raw) != binding["sha256"]:
            raise ValueError("audit source checksum")
        if not isinstance(source.get("samples"), list) or not source["samples"]:
            raise ValueError("audit original metadata")
        source_rows += len(source["samples"])
        if source_rows > 15000:
            raise ValueError("audit original count bound")
        source_bindings.append({"sha256": digest(raw), "license": source["license"]})
        for row in source["samples"]:
            role = (
                speakers[row["speaker"]]
                if source["schema_version"] == "fsdd-acquisition-v1"
                else row["split"]
            )
            origin, identity = row["source_group"], row["sha256"]
            expected_schema = {
                "DIV2K": "media-diversity-acquisition-v1",
                "BOWS2": "bows2-original-acquisition-v1",
                "ESC-50": "media-diversity-acquisition-v1",
                "FSDD-v1.0.10": "fsdd-acquisition-v1",
            }.get(origin)
            if (
                expected_schema is None
                or source["schema_version"] != expected_schema
                or role not in ("train", "validation", "test")
                or not re.fullmatch(r"[a-f0-9]{64}", identity)
                or row.get("label", "cover") != "cover"
                or row.get("method") is not None
                or (origin == "ESC-50" and not row.get("group_key"))
            ):
                raise ValueError("audit source role contract")
            if identity in identities or row["lineage"] != identity:
                raise ValueError("audit repeated original")
            identities.add(identity)
            keys: list[tuple[str, ...]] = [("sha", identity)]
            for field in ("decoded_sha256", "pixel_sha256"):
                if row.get(field):
                    keys.append(("decoded", row[field]))
            for field in ("speaker", "group_key", "camera", "device"):
                if row.get(field):
                    keys.append((field, origin, row[field]))
            for key in keys:
                if groups.setdefault(key, role) != role:
                    raise ValueError("audit grouping leakage")
            if role != "test":
                candidates.setdefault((origin, role), []).append(
                    (row, path.parent, source_bindings[-1])
                )
    if corpus["source_bindings"] != source_bindings:
        raise ValueError("audit license binding")
    selected: list[Any] = []
    for origin in sorted({key[0] for key in candidates}):
        for role in ("train", "validation"):
            rows = sorted(
                candidates[(origin, role)],
                key=lambda item: (
                    digest(f"20261012:{origin}:{item[0]['sha256']}".encode()),
                    item[0]["sha256"],
                ),
            )
            count = cfg["counts"][role]
            if len(rows) < count:
                raise ValueError("audit fixed selection count")
            selected.extend((row, parent, binding, role) for row, parent, binding in rows[:count])
    if len(corpus["originals"]) != len(selected) or len(corpus["samples"]) > 12000:
        raise ValueError("audit corpus counts")
    samples = iter(corpus["samples"])
    seen_carriers: set[str] = set()
    cells: Counter[str] = Counter()
    total, sample_index, positives = 0, 0, 0
    for original, (row, parent, binding, role) in zip(corpus["originals"], selected, strict=True):
        deadline()
        raw = read(parent / member(row["path"]))
        if digest(raw) != row["sha256"] or len(raw) != row.get("size", row.get("bytes")):
            raise ValueError("audit original integrity")
        base, geometry = decode(raw, row["source_group"])
        if digest(base) in seen_carriers:
            raise ValueError("audit duplicate carrier")
        seen_carriers.add(digest(base))
        metadata = {
            key: row.get(key)
            for key in (
                "sha256",
                "lineage",
                "source_group",
                "speaker",
                "group_key",
                "camera",
                "device",
            )
        }
        metadata.update(
            split=role, source_manifest_sha256=binding["sha256"], license=binding["license"]
        )
        if any(original.get(key) != value for key, value in metadata.items()) or original[
            "carrier_sha256"
        ] != digest(base):
            raise ValueError("audit ancestry metadata")
        image = row["source_group"] in ("DIV2K", "BOWS2")
        formats = ("PNG", "BMP") if image else ("WAV",)
        channels = (
            ("r", "g", "b", "all") if geometry[0] == "RGB" else ("gray" if image else "mono",)
        )
        if image:
            if (
                original.get("crop") != [geometry[1], geometry[2], 256, 256]
                or original.get("mode") != geometry[0]
            ):
                raise ValueError("audit crop metadata")
        elif original.get("sample_rate") != geometry[0] or original.get("frames") != geometry[1]:
            raise ValueError("audit audio metadata")
        recipes = [(fmt, None, 0, None, None) for fmt in formats] + [
            (fmt, method, rate, channel, plane)
            for fmt in formats
            for method in ("sequential", "scattered")
            for rate in (5, 40)
            for channel in channels
            for plane in (0, 1)
        ]
        for fmt, method, rate, channel, plane in recipes:
            deadline()
            sample = next(samples, None)
            if not isinstance(sample, dict):
                raise ValueError("audit missing cell")
            expected = {
                **metadata,
                "format": fmt,
                "method": method,
                "rate_percent": rate,
                "channel": channel,
                "plane": plane,
                "label": "cover" if method is None else "stego",
                "path": f"{sample_index:05d}.{fmt.lower()}",
            }
            expected.pop("sha256")
            if any(sample.get(key) != value for key, value in expected.items()):
                raise ValueError("audit cell metadata/order")
            encoded = read(root / member(sample["path"]))
            if digest(encoded) != sample["sha256"] or len(encoded) != sample["size"]:
                raise ValueError("audit artifact integrity")
            values, _ = decode(encoded, row["source_group"], fmt)
            if len(values) != len(base):
                raise ValueError("audit carrier extent")
            total += len(encoded)
            sample_index += 1
            if total > 2 * 1024**3:
                raise ValueError("audit output budget")
            if not image:
                # Whole original RIFF extent/metadata must remain intact; identify
                # PCM independently, not from the preparation's offset field.
                offset, regions = 12, []
                if raw[:4] != b"RIFF" or int.from_bytes(raw[4:8], "little") + 8 != len(raw):
                    raise ValueError("audit RIFF extent")
                while offset + 8 <= len(raw):
                    size = int.from_bytes(raw[offset + 4 : offset + 8], "little")
                    if raw[offset : offset + 4] == b"data":
                        regions.append((offset + 8, size))
                    offset += 8 + size + (size % 2)
                if offset != len(raw) or len(regions) != 1 or regions[0][1] != len(base):
                    raise ValueError("audit PCM region")
                begin = regions[0][0]
                if (
                    encoded[:begin] != raw[:begin]
                    or encoded[begin + len(base) :] != raw[begin + len(base) :]
                ):
                    raise ValueError("audit RIFF metadata changed")
            if method is None:
                if values != base:
                    raise ValueError("audit cover representation")
                continue
            if channel is None or plane is None:
                raise ValueError("audit missing recipe fields")
            context = f"20261012:{row['lineage']}:{method}:{rate}:{channel}:{plane}"
            unit_width = 1 if image else 2
            units = len(base) // unit_width
            eligible = (
                range(units)
                if channel in ("all", "gray", "mono")
                else range("rgb".index(channel), units, 3)
            )
            bits = len(eligible) * rate // 100 // 8 * 8
            indices = (
                eligible[:bits]
                if method == "sequential"
                else [
                    eligible[i]
                    for i in random.Random(context).sample(range(len(eligible)), bits)  # noqa: S311 - public research order
                ]
            )
            allowed = set(indices)
            recovered = bytearray(bits // 8)
            for i, position in enumerate(indices):
                value = int.from_bytes(
                    values[position * unit_width : (position + 1) * unit_width], "little"
                )
                recovered[i // 8] |= ((value >> plane) & 1) << (7 - i % 8)
            payload = hashlib.shake_256(context.encode()).digest(bits // 8)
            changed = 0
            for position in range(units):
                old = int.from_bytes(
                    base[position * unit_width : (position + 1) * unit_width], "little"
                )
                new = int.from_bytes(
                    values[position * unit_width : (position + 1) * unit_width], "little"
                )
                delta = old ^ new
                if delta and (position not in allowed or delta != (1 << plane)):
                    raise ValueError("audit nonselected bit changed")
                changed += bool(delta)
            if (
                bytes(recovered) != payload
                or sample.get("payload_sha256") != digest(payload)
                or sample.get("payload_bytes") != len(payload)
                or sample.get("embedded_bits") != bits
                or sample.get("eligible_units") != len(eligible)
                or not changed
                or sample.get("changed_units") != changed
            ):
                raise ValueError("audit scalar payload oracle")
            positives += 1
            cells[f"{row['source_group']}:{role}:{fmt}:{method}:{rate}:{channel}:{plane}"] += 1
    if (
        next(samples, None) is not None
        or corpus["artifact_count"] != sample_index
        or corpus["artifact_bytes"] != total
    ):
        raise ValueError("audit extra artifacts/counts")
    original_counts = dict(Counter(f"{row['source_group']}:{role}" for row, _, _, role in selected))
    if corpus["original_counts"] != original_counts:
        raise ValueError("audit original denominator")
    return {
        "schema_version": "nonjpeg-independent-audit-v1",
        "status": "completed",
        "manifest_sha256": digest(manifest_raw),
        "config_sha256": digest(config_raw),
        "source_sha256": expected_sources,
        "execution": corpus["execution"],
        "original_counts": original_counts,
        "artifact_count": sample_index,
        "artifact_bytes": total,
        "independent_scalar_recoveries": positives,
        "cells": dict(cells),
        "test_media_opened": False,
        "model_trained": False,
        "detector_scored": False,
        "accuracy_qualification": "unavailable",
        "blind": False,
        "deployed": False,
        "seconds": time.monotonic() - started,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--bindings", type=Path, required=True)
    args = parser.parse_args()
    resource.setrlimit(resource.RLIMIT_AS, (2 * 1024**3,) * 2)
    resource.setrlimit(resource.RLIMIT_CPU, (1800, 1801))
    resource.setrlimit(resource.RLIMIT_FSIZE, (32 * 1024**2,) * 2)
    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    result = audit(args.config, args.root, json.loads(read(args.bindings, 1024**2)))
    path = args.root / "independent-audit.json"
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("audit symlink output")
    with path.open("x") as stream:
        json.dump(result, stream, indent=2, allow_nan=False)
        stream.write("\n")


if __name__ == "__main__":
    main()

