"""Bounded, explicit non-JPEG controlled carriers; no inference or training."""

from __future__ import annotations

import hashlib
import io
import json
import os
import random
import re
import stat
import sys
import time
import wave
from collections import Counter
from pathlib import Path
from typing import Any

import numpy as np
from PIL import Image
from PIL import __version__ as pillow_version

SCHEMA = "nonjpeg-controlled-data-v1"
SEED = 20261012
MAX_FILE = 32 * 1024**2
MAX_DOCUMENT = 8 * 1024**2
MAX_OUTPUT = 2 * 1024**3
SPEAKERS = {
    "lucas": "train",
    "nicolas": "train",
    "theo": "validation",
    "yweweler": "validation",
    "george": "test",
    "jackson": "test",
}
SOURCE_SCHEMAS = {
    "media-diversity-acquisition-v1",
    "bows2-original-acquisition-v1",
    "fsdd-acquisition-v1",
}


def sha(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def regular_read(path: Path, limit: int) -> bytes:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("symlink input")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        os.close(fd)
        raise ValueError("nonregular input")
    with os.fdopen(fd, "rb") as stream:
        raw = stream.read(limit + 1)
    if not raw or len(raw) > limit:
        raise ValueError("input byte bound")
    return raw


def document(path: Path) -> tuple[dict[str, Any], str]:
    raw = regular_read(path, MAX_DOCUMENT)
    result = json.loads(raw)
    if not isinstance(result, dict):
        raise ValueError("document schema")
    return result, sha(raw)


def basename(name: Any) -> str:
    if (
        not isinstance(name, str)
        or not re.fullmatch(r"[A-Za-z0-9_.-]{1,180}", name)
        or name in (".", "..")
    ):
        raise ValueError("unsafe member name")
    return name


def write(path: Path, raw: bytes) -> None:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("symlink output")
    with path.open("xb") as stream:
        stream.write(raw)


def write_json(path: Path, data: dict[str, Any]) -> None:
    write(path, (json.dumps(data, indent=2, allow_nan=False) + "\n").encode())


def config(path: Path) -> tuple[dict[str, Any], str]:
    cfg, digest = document(path)
    if (
        set(cfg) != {"schema_version", "sources", "counts"}
        or cfg["schema_version"] != "nonjpeg-preparation-config-v1"
        or not isinstance(cfg["sources"], list)
        or not 1 <= len(cfg["sources"]) <= 5
        or not isinstance(cfg["counts"], dict)
        or set(cfg["counts"]) != {"train", "validation"}
    ):
        raise ValueError("config schema")
    for role, maximum in (("train", 32), ("validation", 8)):
        if type(cfg["counts"][role]) is not int or not 1 <= cfg["counts"][role] <= maximum:
            raise ValueError("selection count limit")
    for source in cfg["sources"]:
        if (
            not isinstance(source, dict)
            or set(source) != {"manifest", "sha256"}
            or not isinstance(source["manifest"], str)
            or not isinstance(source["sha256"], str)
            or not re.fullmatch(r"[a-f0-9]{64}", source["sha256"])
        ):
            raise ValueError("source binding schema")
    return cfg, digest


def selection(cfg: dict[str, Any]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    candidates: dict[tuple[str, str], list[dict[str, Any]]] = {}
    roles: dict[tuple[str, ...], str] = {}
    seen: set[str] = set()
    bindings = []
    total = 0
    for binding in cfg["sources"]:
        path = Path(binding["manifest"])
        source, digest = document(path)
        rows = source.get("samples")
        if (
            digest != binding["sha256"]
            or source.get("schema_version") not in SOURCE_SCHEMAS
            or not isinstance(source.get("license"), str)
            or not 1 <= len(source.get("license", "")) <= 256
            or (
                source.get("schema_version") != "fsdd-acquisition-v1"
                and source.get("status") != "completed"
            )
            or not isinstance(rows, list)
            or not rows
        ):
            raise ValueError("source schema or checksum")
        total += len(rows)
        if total > 15000:
            raise ValueError("original count bound")
        for row in rows:
            if not isinstance(row, dict):
                raise ValueError("source row schema")
            original = row.get("sha256")
            origin = row.get("source_group")
            role = row.get("split")
            if source["schema_version"] == "fsdd-acquisition-v1":
                role = SPEAKERS.get(str(row.get("speaker", "")))
                if row.get("split") not in (None, role):
                    raise ValueError("FSDD speaker role conflict")
            if (
                not isinstance(original, str)
                or not re.fullmatch(r"[a-f0-9]{64}", original)
                or row.get("lineage") != original
                or original in seen
                or origin not in ("DIV2K", "BOWS2", "FSDD-v1.0.10", "ESC-50")
                or role not in ("train", "validation", "test")
                or row.get("label", "cover") != "cover"
                or row.get("method") is not None
            ):
                raise ValueError("original identity or role")
            expected_schema = {
                "DIV2K": "media-diversity-acquisition-v1",
                "BOWS2": "bows2-original-acquisition-v1",
                "ESC-50": "media-diversity-acquisition-v1",
                "FSDD-v1.0.10": "fsdd-acquisition-v1",
            }[origin]
            if source["schema_version"] != expected_schema:
                raise ValueError("source format contract")
            for field in ("camera", "device", "speaker", "group_key"):
                value = row.get(field)
                if value is not None and (
                    not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", value)
                ):
                    raise ValueError("bounded grouping metadata")
            seen.add(original)
            keys: list[tuple[str, ...]] = [("sha", original)]
            for field in ("decoded_sha256", "pixel_sha256"):
                if row.get(field):
                    keys.append(("decoded", str(row[field])))
            for field in ("speaker", "group_key", "camera", "device"):
                if row.get(field):
                    keys.append((field, origin, str(row[field])))
            if origin == "ESC-50" and not row.get("group_key"):
                raise ValueError("missing audio recording group")
            if origin == "FSDD-v1.0.10" and row.get("speaker") not in SPEAKERS:
                raise ValueError("missing speaker group")
            for key in keys:
                if roles.setdefault(key, role) != role:
                    raise ValueError("original group crosses roles")
            basename(row.get("path"))
            size = row.get("size", row.get("bytes"))
            if type(size) is not int or not 0 < size <= MAX_FILE:
                raise ValueError("original size")
            if role != "test":
                candidates.setdefault((origin, role), []).append(
                    {
                        **row,
                        "split": role,
                        "size": size,
                        "root": path.parent,
                        "source_manifest_sha256": digest,
                        "license": source["license"],
                    }
                )
        bindings.append({"sha256": digest, "license": source["license"]})
    origins = {key[0] for key in candidates}
    if not 1 <= len(origins) <= 4:
        raise ValueError("origin count")
    chosen = []
    for origin in sorted(origins):
        for role in ("train", "validation"):
            rows = candidates.get((origin, role), [])
            count = cfg["counts"][role]
            if len(rows) < count:
                raise ValueError("insufficient fixed source role")
            chosen.extend(
                sorted(
                    rows,
                    key=lambda row: (
                        sha(f"{SEED}:{origin}:{row['sha256']}".encode()),
                        row["sha256"],
                    ),
                )[:count]
            )
    return chosen, bindings


def carrier(raw: bytes, origin: str) -> tuple[np.ndarray, dict[str, Any]]:
    if origin in ("DIV2K", "BOWS2"):
        with Image.open(io.BytesIO(raw)) as image:
            mode = "RGB" if origin == "DIV2K" else "L"
            if (
                image.mode != mode
                or image.format != ("PNG" if mode == "RGB" else "PPM")
                or getattr(image, "n_frames", 1) != 1
                or min(image.size) < 256
                or image.width * image.height > 8_000_000
            ):
                raise ValueError("native image contract")
            left, top = (image.width - 256) // 2, (image.height - 256) // 2
            pixels = np.array(image.crop((left, top, left + 256, top + 256)), dtype=np.uint8)
        return pixels, {"kind": "spatial", "mode": mode, "crop": [left, top, 256, 256]}
    if (
        len(raw) < 12
        or raw[:4] != b"RIFF"
        or raw[8:12] != b"WAVE"
        or int.from_bytes(raw[4:8], "little") + 8 != len(raw)
    ):
        raise ValueError("RIFF extent")
    with wave.open(io.BytesIO(raw)) as audio:
        frames = audio.getnframes()
        rate = 8000 if origin == "FSDD-v1.0.10" else 44100
        if (
            audio.getparams()[:3] != (1, 2, rate)
            or audio.getcomptype() != "NONE"
            or not 160 <= frames <= 220500
        ):
            raise ValueError("native PCM contract")
        pcm = audio.readframes(frames)
        if len(pcm) != frames * 2:
            raise ValueError("truncated PCM")
    offset, regions, chunks = 12, [], 0
    while offset + 8 <= len(raw):
        size = int.from_bytes(raw[offset + 4 : offset + 8], "little")
        end = offset + 8 + size + (size & 1)
        chunks += 1
        if end > len(raw) or chunks > 64:
            raise ValueError("RIFF chunk bound")
        if raw[offset : offset + 4] == b"data":
            regions.append((offset + 8, size))
        offset = end
    if (
        offset != len(raw)
        or len(regions) != 1
        or regions[0][1] != len(pcm)
        or raw[regions[0][0] : regions[0][0] + len(pcm)] != pcm
    ):
        raise ValueError("ambiguous PCM region")
    return np.frombuffer(pcm, dtype="<u2").copy(), {
        "kind": "audio",
        "mode": "PCM16",
        "sample_rate": rate,
        "frames": frames,
        "offset": regions[0][0],
    }


def variants(meta: dict[str, Any]) -> list[tuple[str, str | None, int, str | None, int | None]]:
    formats = ("PNG", "BMP") if meta["kind"] == "spatial" else ("WAV",)
    channels = (
        ("r", "g", "b", "all")
        if meta["mode"] == "RGB"
        else ("gray" if meta["mode"] == "L" else "mono",)
    )
    return [(fmt, None, 0, None, None) for fmt in formats] + [
        (fmt, method, rate, channel, plane)
        for fmt in formats
        for method in ("sequential", "scattered")
        for rate in (5, 40)
        for channel in channels
        for plane in (0, 1)
    ]


def replace(
    values: np.ndarray, lineage: str, method: str, rate: int, channel: str, plane: int
) -> tuple[np.ndarray, dict[str, Any]]:
    if (
        method not in ("sequential", "scattered")
        or rate not in (5, 40)
        or plane not in (0, 1)
        or channel not in ("r", "g", "b", "all", "gray", "mono")
        or values.dtype not in (np.dtype("uint8"), np.dtype("<u2"))
        or values.size > 220500
        or values.size < 160
        or (channel in ("r", "g", "b", "all") and values.shape != (256, 256, 3))
        or (channel == "gray" and values.shape != (256, 256))
        or (channel == "mono" and (values.ndim != 1 or values.dtype != np.dtype("<u2")))
    ):
        raise ValueError("replacement recipe contract")
    context = f"{SEED}:{lineage}:{method}:{rate}:{channel}:{plane}"
    flat = values.reshape(-1).copy()
    eligible = (
        np.arange(flat.size)
        if channel in ("all", "gray", "mono")
        else np.arange("rgb".index(channel), flat.size, 3)
    )
    bits = len(eligible) * rate // 100 // 8 * 8
    if not bits:
        raise ValueError("empty payload")
    payload = hashlib.shake_256(context.encode()).digest(bits // 8)
    selected = (
        eligible[:bits]
        if method == "sequential"
        else eligible[np.asarray(random.Random(context).sample(range(len(eligible)), bits))]  # noqa: S311 - public research order
    )
    mask = 1 << plane
    flat[selected] = (flat[selected] & (np.iinfo(flat.dtype).max ^ mask)) | (
        np.unpackbits(np.frombuffer(payload, dtype=np.uint8)).astype(flat.dtype) << plane
    )
    differences = np.bitwise_xor(flat, values.reshape(-1))
    if not np.any(differences) or np.any(differences & (np.iinfo(flat.dtype).max ^ mask)):
        raise ValueError("replacement bit contract")
    return flat.reshape(values.shape), {
        "payload_sha256": sha(payload),
        "payload_bytes": len(payload),
        "eligible_units": len(eligible),
        "embedded_bits": bits,
        "changed_units": int(np.count_nonzero(differences)),
    }


def prepare(
    cfg: dict[str, Any], out: Path, *, config_sha256: str, source_sha256: dict[str, str]
) -> dict[str, Any]:
    started = time.monotonic()
    chosen, bindings = selection(cfg)
    decoded = set()
    originals: list[dict[str, Any]] = []
    samples: list[dict[str, Any]] = []
    total = 0
    for original in chosen:
        if time.monotonic() - started > 1800:
            raise TimeoutError("preparation deadline")
        raw = regular_read(original["root"] / original["path"], MAX_FILE)
        if len(raw) != original["size"] or sha(raw) != original["sha256"]:
            raise ValueError("original integrity")
        pixels, meta = carrier(raw, original["source_group"])
        decoded_hash = sha(pixels.tobytes())
        if decoded_hash in decoded:
            raise ValueError("duplicate selected decoded carrier")
        decoded.add(decoded_hash)
        identity = {
            key: original.get(key)
            for key in (
                "sha256",
                "lineage",
                "source_group",
                "split",
                "source_manifest_sha256",
                "license",
                "speaker",
                "group_key",
                "camera",
                "device",
            )
        }
        originals.append({**identity, "carrier_sha256": decoded_hash, **meta})
        for fmt, method, rate, channel, plane in variants(meta):
            proof: dict[str, Any]
            if method is None:
                modified, proof = pixels, {}
            else:
                if channel is None or plane is None:
                    raise ValueError("missing recipe channel or plane")
                modified, proof = replace(pixels, original["lineage"], method, rate, channel, plane)
            if fmt == "WAV":
                offset = meta["offset"]
                data = (
                    raw[:offset] + modified.astype("<u2").tobytes() + raw[offset + pixels.nbytes :]
                )
            else:
                buffer = io.BytesIO()
                Image.fromarray(modified).save(buffer, format=fmt)
                data = buffer.getvalue()
            total += len(data)
            if total > MAX_OUTPUT - 32 * 1024**2 or len(samples) >= 12000:
                raise ValueError("artifact budget")
            name = f"{len(samples):05d}.{fmt.lower()}"
            write(out / name, data)
            samples.append(
                {
                    **identity,
                    "path": name,
                    "sha256": sha(data),
                    "size": len(data),
                    "format": fmt,
                    "method": method,
                    "rate_percent": rate,
                    "channel": channel,
                    "plane": plane,
                    "label": "cover" if method is None else "stego",
                    **proof,
                }
            )
    result = {
        "schema_version": SCHEMA,
        "status": "prepared_not_audited",
        "seed": SEED,
        "config_sha256": config_sha256,
        "source_sha256": source_sha256,
        "execution": {
            "python": sys.version.split()[0],
            "numpy": np.__version__,
            "pillow": pillow_version,
            "sample_byte_order": "little",
            "sample_rate_conversion": False,
            "image_resize": False,
        },
        "source_bindings": bindings,
        "originals": originals,
        "samples": samples,
        "original_counts": dict(Counter(f"{r['source_group']}:{r['split']}" for r in originals)),
        "artifact_count": len(samples),
        "artifact_bytes": total,
        "model_trained": False,
        "optimizer_updates": 0,
        "detector_scored": False,
        "accuracy_qualification": "unavailable",
        "deployed": False,
        "camera_independence_verified": False,
        "blind": False,
        "publication": "private controlled derivatives; preserve source licenses",
        "seconds": time.monotonic() - started,
    }
    write_json(out / "manifest.json", result)
    return result

core/nonjpeg_features.py.utf8:
"""Versioned native spatial/PCM descriptors for explicit development research."""

from __future__ import annotations

import io
import wave

import numpy as np
from PIL import Image

from core.features import MAX_IMAGE_BYTES
from core.spatial_parity import DIRECTIONS, parity_histogram, spatial_parity_features
from core.spatial_parity import FEATURE_NAMES as BASE_NAMES

LOCAL_VERSION = "spatial-local-parity-v2"
RGB_VERSION = "spatial-rgb-parity-v2"
AUDIO_VERSION = "audio-pcm16-parity-residual-v1"
QUARTERS = ("tl", "tr", "bl", "br")


def parity_names(prefix: str) -> tuple[str, ...]:
    return tuple(
        f"{prefix}_{direction}_bit{bit}_{parity}_{residual}"
        for direction in DIRECTIONS
        for bit in range(3)
        for parity in range(2)
        for residual in range(-4, 5)
    )


LOCAL_NAMES = (*BASE_NAMES, *(n for q in QUARTERS for n in parity_names(q)))
RGB_NAMES = (*BASE_NAMES, *(n for c in "rgb" for n in parity_names(c)))
AUDIO_NAMES = tuple(
    f"{region}_lag{lag}_bit{bit}_{kind}"
    for region in ("full", "q0", "q1", "q2", "q3")
    for lag in (1, 2)
    for bit in (0, 1)
    for kind in (
        *(f"parity{p}_delta{d}" for p in (0, 1) for d in range(-8, 9)),
        *(f"transition{a}{b}" for a in (0, 1) for b in (0, 1)),
    )
)


def spatial_pixels(data: bytes, *, rgb: bool = False) -> np.ndarray:
    if len(data) > MAX_IMAGE_BYTES:
        raise ValueError("feature image exceeds byte limit")
    with Image.open(io.BytesIO(data)) as image:
        if image.format not in {"PNG", "BMP"}:
            raise ValueError("native PNG/BMP required")
        if image.size != (256, 256) or getattr(image, "n_frames", 1) != 1:
            raise ValueError("prepared 256x256 single image required; no resize")
        if image.mode not in (("RGB",) if rgb else ("L", "RGB")):
            raise ValueError("native RGB required" if rgb else "native L/RGB required")
        pixels = np.asarray(image, dtype=np.int16)
    return pixels[..., None] if pixels.ndim == 2 else pixels


def spatial_features(data: bytes, *, rgb: bool = False) -> list[float]:
    pixels = spatial_pixels(data, rgb=rgb)
    regions = (
        [pixels[..., c : c + 1] for c in range(3)]
        if rgb
        else [pixels[y : y + 128, x : x + 128] for y in (0, 128) for x in (0, 128)]
    )
    values = spatial_parity_features(data)
    for region in regions:
        for direction in DIRECTIONS:
            for bit in range(3):
                values.extend(parity_histogram(region, direction, bit))
    return [round(v, 8) for v in values]


def rgb_features(data: bytes) -> list[float]:
    return spatial_features(data, rgb=True)


def pcm16_samples(data: bytes) -> np.ndarray:
    """Reject truncated/ambiguous RIFF before decoding native mono PCM16."""
    if len(data) > MAX_IMAGE_BYTES:
        raise ValueError("audio exceeds byte limit")
    if (
        data[:4] != b"RIFF"
        or data[8:12] != b"WAVE"
        or int.from_bytes(data[4:8], "little") + 8 != len(data)
    ):
        raise ValueError("invalid RIFF extent")
    offset = 12
    chunks: list[tuple[bytes, int]] = []
    while offset + 8 <= len(data) and len(chunks) < 128:
        size = int.from_bytes(data[offset + 4 : offset + 8], "little")
        end = offset + 8 + size
        if end + size % 2 > len(data):
            raise ValueError("truncated RIFF chunk")
        chunks.append((data[offset : offset + 4], size))
        offset = end + size % 2
    if (
        offset != len(data)
        or sum(k == b"data" for k, _ in chunks) != 1
        or sum(k == b"fmt " for k, _ in chunks) != 1
    ):
        raise ValueError("ambiguous RIFF chunks")
    with wave.open(io.BytesIO(data)) as audio:
        if (
            audio.getnchannels() != 1
            or audio.getsampwidth() != 2
            or audio.getcomptype() != "NONE"
            or not 160 <= audio.getnframes() <= 220_500
            or not 8_000 <= audio.getframerate() <= 192_000
            or audio.getnframes() / audio.getframerate() > 30
        ):
            raise ValueError("native mono PCM16 frame/rate/duration contract")
        frames = audio.readframes(audio.getnframes())
        if len(frames) != audio.getnframes() * 2 or dict(chunks)[b"data"] != len(frames):
            raise ValueError("truncated PCM extent")
    return np.frombuffer(frames, dtype="<i2").astype(np.int32)


def audio_histogram(samples: np.ndarray, lag: int, bit: int) -> list[float]:
    if lag not in (1, 2) or bit not in (0, 1):
        raise ValueError("unsupported PCM lag/bit")
    # Conversion precedes subtraction, including -32768 -> 32767 transitions.
    values = samples.astype(np.int32)
    center, neighbor = values[:-lag], values[lag:]
    parity, following = (center >> bit) & 1, (neighbor >> bit) & 1
    bins = parity * 17 + np.clip(neighbor - center, -8, 8) + 8
    residuals = np.bincount(bins, minlength=34) / len(center)
    transitions = np.bincount(parity * 2 + following, minlength=4) / len(center)
    return [*residuals.tolist(), *transitions.tolist()]


def audio_features(data: bytes) -> list[float]:
    samples = pcm16_samples(data)
    regions = [samples, *np.split(samples[: len(samples) // 4 * 4], 4)]
    # Remainder belongs to the final quarter, never discard native samples.
    regions[-1] = samples[3 * (len(samples) // 4) :]
    return [
        round(value, 8)
        for region in regions
        for lag in (1, 2)
        for bit in (0, 1)
        for value in audio_histogram(region, lag, bit)
    ]


CONTRACTS = {
    LOCAL_VERSION: (LOCAL_NAMES, spatial_features),
    RGB_VERSION: (RGB_NAMES, rgb_features),
    AUDIO_VERSION: (AUDIO_NAMES, audio_features),
}

core/nonjpeg_linear.py.utf8:
"""Bounded train-only grouped linear research, independent of production models."""

from __future__ import annotations

import hashlib
import json
from collections import Counter

import numpy as np

EPOCHS = 20
SEEDS = (20261016, 20261017)
LEARNING_RATE = 0.01
L2 = 1e-4
BATCH = 64
SCALE_FLOOR = 1e-6


def row_identity(rows):
    keys = ("sha256", "lineage", "source_group", "split", "label", "format", "method",
            "rate_percent", "channel", "plane")
    return hashlib.sha256(json.dumps(
        [[r.get(k) for k in keys] for r in rows], separators=(",", ":"), allow_nan=False
    ).encode()).hexdigest()


def group_key(row):
    source = row["source_group"]
    key = row.get("speaker") if source == "FSDD-v1.0.10" else (
        row.get("group_key") if source == "ESC-50" else row.get("lineage"))
    if not isinstance(key, str) or not key or len(key) > 256:
        raise ValueError("missing bounded independent group")
    return key


def training_weights(rows):
    if not 2 <= len(rows) <= 4096:
        raise ValueError("linear row limit")
    counts = Counter((r["lineage"], r["label"]) for r in rows)
    lineages = {r["lineage"] for r in rows}
    if any(r["label"] not in {"cover", "stego"} for r in rows) or any(
        not counts[(key, label)] for key in lineages for label in ("cover", "stego")
    ):
        raise ValueError("complete original class families required")
    return np.array([1 / (2 * len(lineages) * counts[(r["lineage"], r["label"])])
                     for r in rows], dtype=np.float64)


def validate(x, y, rows):
    if (
        not isinstance(x, np.ndarray) or x.ndim != 2 or not 1 <= x.shape[1] <= 4096
        or x.shape[0] != len(rows) or not isinstance(y, np.ndarray) or y.shape != (len(rows),)
        or not np.isfinite(x).all() or np.any((x < 0) | (x > 1))
        or not np.array_equal(y, [r["label"] == "stego" for r in rows])
    ):
        raise ValueError("linear feature/label contract mismatch")
    return training_weights(rows)


def group_folds(rows):
    if {r["split"] for r in rows} != {"train"}:
        raise ValueError("cross-validation must be train-only")
    groups = [group_key(r) for r in rows]
    ordered = sorted(set(groups), key=lambda g: hashlib.sha256(
        ("nonjpeg-group-folds-20261018:" + g).encode()).digest())
    if not 2 <= len(ordered) <= 32:
        raise ValueError("insufficient or excessive independent training groups")
    assignment = {key: index % min(4, len(ordered)) for index, key in enumerate(ordered)}
    lineage_groups: dict[str, str] = {}
    for row, group in zip(rows, groups, strict=True):
        if lineage_groups.setdefault(row["lineage"], group) != group:
            raise ValueError("one lineage cannot cross independent groups")
    return np.asarray([assignment[g] for g in groups], dtype=np.int64)


def sigmoid(values):
    return 1 / (1 + np.exp(-np.clip(values, -40, 40)))


def fit(x, y, rows, seed, *, epochs=EPOCHS, deadline=lambda: None, on_update=lambda: None):
    weights = validate(x, y, rows)
    if seed not in SEEDS or type(epochs) is not int or not 1 <= epochs <= EPOCHS:
        raise ValueError("linear initialization/exposure contract mismatch")
    x = x.astype(np.float64)
    mean = weights @ x
    scale = np.maximum(np.sqrt(weights @ ((x - mean) ** 2)), SCALE_FLOOR)
    z = (x - mean) / scale
    # Separate streams ensure feature dimension cannot change presentation order.
    parameters = np.random.default_rng(seed).normal(0, 0.01 / np.sqrt(x.shape[1]), x.shape[1])
    order = np.random.default_rng(seed ^ 0x4E4A5047)
    bias = 0.0
    exposure = hashlib.sha256(bytes.fromhex(row_identity(rows)))
    losses = []
    updates = 0
    for _ in range(epochs):
        deadline()
        shuffled = order.permutation(len(rows))
        exposure.update(shuffled.astype("<i4").tobytes())
        for start in range(0, len(rows), BATCH):
            deadline()
            indices = shuffled[start : start + BATCH]
            probabilities = sigmoid(z[indices] @ parameters + bias)
            error = weights[indices] * (probabilities - y[indices]) * len(rows) / len(indices)
            gradient = z[indices].T @ error + L2 * parameters
            parameters -= LEARNING_RATE * gradient
            bias -= LEARNING_RATE * float(error.sum())
            updates += 1
            on_update()
            if not np.isfinite(parameters).all() or not np.isfinite(bias):
                raise ValueError("linear nonfinite state")
        logits = z @ parameters + bias
        losses.append(float(weights @ (np.logaddexp(0, logits) - y * logits)))
    return {
        "mean": mean, "scale": scale, "weights": parameters, "bias": bias,
        "epochs": epochs, "optimizer_updates": updates, "losses": losses,
        "exposure_sha256": exposure.hexdigest(), "row_presentations": epochs * len(rows),
        "original_presentations": epochs * len({r["lineage"] for r in rows}),
    }


def predict(model, x):
    d = len(model["weights"])
    if (
        not isinstance(x, np.ndarray) or x.ndim != 2 or x.shape[1] != d
        or not 1 <= len(x) <= 4096 or not np.isfinite(x).all() or np.any((x < 0) | (x > 1))
        or any(np.shape(model[k]) != (d,) or not np.isfinite(model[k]).all()
               for k in ("mean", "scale", "weights"))
        or np.any(model["scale"] < SCALE_FLOOR) or not np.isfinite(model["bias"])
    ):
        raise ValueError("linear inference contract mismatch")
    return sigmoid(((x.astype(np.float64) - model["mean"]) / model["scale"])
                   @ model["weights"] + model["bias"])


def select_threshold(scores, y, rows):
    weights = training_weights(rows)
    if {r["split"] for r in rows} != {"train"} or scores.shape != y.shape or (
        not np.isfinite(scores).all() or np.any((scores < 0) | (scores > 1))
    ):
        raise ValueError("threshold selection requires complete train-only OOF scores")
    grid = np.arange(101) / 100
    accuracy = np.array([weights @ ((scores >= t) == y) for t in grid])
    # Fixed higher-threshold tie rule, without inspecting validation values.
    return float(grid[np.flatnonzero(np.round(accuracy, 12) == np.round(accuracy.max(), 12))[-1]])


def grouped_fit(x, y, rows, seed, *, deadline=lambda: None, on_update=lambda: None):
    validate(x, y, rows)
    folds = group_folds(rows)
    oof = np.full(len(rows), np.nan)
    receipts = []
    for fold in sorted(set(folds.tolist())):
        train, held = np.flatnonzero(folds != fold), np.flatnonzero(folds == fold)
        model = fit(x[train], y[train], [rows[i] for i in train], seed,
                    deadline=deadline, on_update=on_update)
        oof[held] = predict(model, x[held])
        receipts.append({"fold": fold, "training_rows": len(train), "held_rows": len(held),
                         "exposure_sha256": model["exposure_sha256"],
                         "optimizer_updates": model["optimizer_updates"],
                         "row_presentations": model["row_presentations"]})
    threshold = select_threshold(oof, y, rows)
    model = fit(x, y, rows, seed, deadline=deadline, on_update=on_update)
    return model, {"threshold": threshold, "folds": receipts,
                   "oof_sha256": hashlib.sha256(oof.astype("<f8").tobytes()).hexdigest(),
                   "oof_scores": oof, "fold_assignments": folds,
                   "all_optimizer_updates": model["optimizer_updates"] + sum(
                       r["optimizer_updates"] for r in receipts)}

core/nonjpeg_models.py.utf8:
"""Optional FP32 research skeletons; no optimizer, downloads or checkpoints."""

from __future__ import annotations

import numpy as np

from core.nonjpeg_features import pcm16_samples, spatial_pixels

GRAY_DOMAIN = "spatial-native-gray-srnet-v1"
RGB_DOMAIN = "spatial-native-rgb-srnet-v1"
AUDIO_DOMAIN = "audio-native-pcm16-resnet1d-v1"
DOMAINS = (GRAY_DOMAIN, RGB_DOMAIN, AUDIO_DOMAIN)


def inputs(data: bytes, domain: str) -> np.ndarray:
    if domain == AUDIO_DOMAIN:
        raw = pcm16_samples(data)
        # Signed arithmetic before FP32 scaling; zero left boundary for deltas.
        first = np.diff(raw, prepend=raw[0])
        second = np.diff(first, prepend=first[0])
        return np.stack((raw, first, second)).astype(np.float32)[None] / 32768
    if domain not in (GRAY_DOMAIN, RGB_DOMAIN):
        raise ValueError("unknown native model domain")
    pixels = spatial_pixels(data, rgb=domain == RGB_DOMAIN)
    if domain == GRAY_DOMAIN and pixels.shape[2] != 1:
        raise ValueError("gray model requires native grayscale")
    return pixels.transpose(2, 0, 1).astype(np.float32)[None]


def network(domain: str):
    if domain not in DOMAINS:
        raise ValueError("unknown native model domain")
    try:
        import torch
    except ImportError as exc:
        raise RuntimeError("native model skeleton unavailable: optional Torch missing") from exc

    if domain in (GRAY_DOMAIN, RGB_DOMAIN):
        from core.srnet import network as srnet_network

        model = srnet_network()
        if domain == RGB_DOMAIN:
            conv = torch.nn.Conv2d(3, 64, 3, padding=1, dtype=torch.float32, device="cpu")
            torch.nn.init.kaiming_normal_(conv.weight, mode="fan_in", nonlinearity="relu")
            if conv.bias is not None:
                torch.nn.init.constant_(conv.bias, 0.2)
            model.front[0][0] = conv
        model.architecture = domain
        return model

    class Conv(torch.nn.Sequential):
        def __init__(self, before, after, stride=1):
            super().__init__(
                torch.nn.Conv1d(before, after, 5, stride=stride, padding=2, dtype=torch.float32),
                torch.nn.BatchNorm1d(after, dtype=torch.float32),
                torch.nn.ReLU(),
            )

    class Residual(torch.nn.Module):
        def __init__(self, before, after, stride=1):
            super().__init__()
            self.branch = torch.nn.Sequential(
                Conv(before, after, stride),
                torch.nn.Conv1d(after, after, 5, padding=2, dtype=torch.float32),
                torch.nn.BatchNorm1d(after, dtype=torch.float32),
            )
            self.skip = (
                torch.nn.Identity()
                if before == after and stride == 1
                else torch.nn.Conv1d(before, after, 1, stride=stride, dtype=torch.float32)
            )

        def forward(self, values):
            return torch.relu(self.branch(values) + self.skip(values))

    class PCMNet(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.architecture = AUDIO_DOMAIN
            self.body = torch.nn.Sequential(
                Conv(3, 32),
                Residual(32, 32),
                Residual(32, 32),
                Residual(32, 64, 2),
                Residual(64, 128, 2),
                torch.nn.AdaptiveAvgPool1d(1),
                torch.nn.Flatten(),
            )
            self.classifier = torch.nn.Linear(128, 2, dtype=torch.float32)

        def forward(self, values):
            return self.classifier(self.body(values))

    return PCMNet()


def generated_smoke() -> dict:
    """Generated-only forward/backward; preserve RNG, parameters and thread policy."""
    try:
        import torch
    except ImportError:
        return {"status": "unavailable", "reason": "optional_torch_missing", "optimizer_updates": 0}
    previous_threads = torch.get_num_threads()
    results = {}
    try:
        torch.set_num_threads(2)
        with torch.random.fork_rng(devices=[]):
            torch.manual_seed(20261015)
            for domain in DOMAINS:
                model = network(domain).train()
                shape = (
                    (2, 3, 640)
                    if domain == AUDIO_DOMAIN
                    else (1, 3 if domain == RGB_DOMAIN else 1, 256, 256)
                )
                values = torch.randn(shape, dtype=torch.float32, requires_grad=True)
                before = [p.detach().clone() for p in model.parameters()]
                output = model(values)
                loss = torch.nn.functional.cross_entropy(
                    output, torch.arange(shape[0], dtype=torch.long) % 2
                )
                loss.backward()
                if (
                    output.shape != (shape[0], 2)
                    or not bool(torch.isfinite(output).all())
                    or values.grad is None
                    or not bool(torch.isfinite(values.grad).all())
                    or not bool((values.grad != 0).any())
                    or any(
                        p.grad is None or not bool(torch.isfinite(p.grad).all())
                        for p in model.parameters()
                    )
                    or any(
                        not torch.equal(p, old)
                        for p, old in zip(model.parameters(), before, strict=True)
                    )
                ):
                    raise ValueError("native generated forward/backward contract failed")
                results[domain] = {
                    "status": "ready",
                    "input_shape": list(shape),
                    "dtype": "float32",
                    "finite_gradients": True,
                    "parameters_unchanged": True,
                    "parameters": sum(p.numel() for p in model.parameters()),
                }
                del model, values, output, loss, before
    finally:
        torch.set_num_threads(previous_threads)
    return {
        "status": "ready",
        "models": results,
        "optimizer_updates": 0,
        "checkpoint_written": False,
        "weights_downloaded": False,
        "gpu_used": False,
    }

core/nonjpeg_unicode.py.utf8:
"""Pinned Unicode conformance controls; not a natural-language benchmark."""

from __future__ import annotations

from collections import Counter
from pathlib import Path

from core.nonjpeg_data import regular_read
from core.research_acquisition import UNICODE_FILES, digest, write_json


def controls(root: Path, acquisition: dict, out: Path) -> dict:
    if out.exists() or any(p.is_symlink() for p in (out, *out.parents)):
        raise FileExistsError("fresh nonsymlink Unicode output required")
    rows = []
    counts: Counter[str] = Counter()
    bindings = {}
    for name in UNICODE_FILES:
        binding = acquisition.get("unicode", {}).get(name, {})
        if binding.get("status") != "ready" or binding.get("version") != "17.0.0":
            continue
        raw = regular_read(root / name, 16 * 1024**2)
        if digest(raw) != binding.get("sha256"):
            raise ValueError("Unicode source checksum mismatch")
        bindings[name] = digest(raw)
        for number, line in enumerate(raw.decode("utf-8-sig").splitlines(), 1):
            content = line.split("#", 1)[0].strip()
            if not content or content.startswith("@"):
                continue
            fields = content.split(";")
            tokens = fields[0].replace("÷", " ").replace("×", " ").split()
            points = [int(token, 16) for token in tokens]
            if (
                not points
                or len(points) > 128
                or any(p > 0x10FFFF or 0xD800 <= p <= 0xDFFF for p in points)
            ):
                continue
            categories = []
            if 0x200D in points:
                categories.append("zwj")
            if 0x200C in points:
                categories.append("zwnj")
            if any(p in (9, 10, 13, 32, 0xA0, 0x2000, 0x2028, 0x2029) for p in points):
                categories.append("whitespace")
            if name == "NormalizationTest.txt":
                categories.append("normalization")
            if name == "BidiCharacterTest.txt":
                categories.append("bidi")
            if name == "emoji-test.txt":
                categories.append("emoji")
            categories = [c for c in categories if counts[c] < 32]
            if not categories:
                continue
            row = {
                "source": name,
                "line": number,
                "source_sha256": digest(raw),
                "codepoints": points,
                "text": "".join(map(chr, points)),
                "categories": categories,
                "role": "algorithm_conformance_negative",
            }
            if name == "NormalizationTest.txt":
                row["normalization_columns"] = [
                    [int(token, 16) for token in field.split()] for field in fields[:5]
                ]
            rows.append(row)
            counts.update(categories)
    required = {"zwj", "zwnj", "whitespace", "normalization", "bidi", "emoji"}
    result = {
        "schema_version": "unicode-normal-controls-v1",
        "version": "17.0.0",
        "status": "ready" if required <= counts.keys() else "incomplete",
        "source_sha256": bindings,
        "counts": dict(counts),
        "missing": sorted(required - counts.keys()),
        "rows": rows,
        "natural_document_coverage": "unavailable",
        "detector_scored": False,
    }
    write_json(out, result)
    return result

core/research_acquisition.py.utf8:
"""Explicit, bounded Commons/Unicode development acquisition; never training."""

from __future__ import annotations

import hashlib
import html
import io
import json
import re
import time
import urllib.error
import urllib.parse
import urllib.request
import wave
from collections import Counter
from pathlib import Path

from PIL import Image

MAX_DOWNLOAD = 1024**3
MAX_FILE = 32 * 1024**2
MAX_SECONDS = 1800
TARGETS = {"png": 40, "gif": 20, "wav": 20, "mp3": 20}
MIMES = {"png": "image/png", "gif": "image/gif", "wav": "audio/wav", "mp3": "audio/mpeg"}
UNICODE_ROOT = "https://www.unicode.org/Public/17.0.0/ucd/"
UNICODE_FILES = {
    "GraphemeBreakTest.txt": UNICODE_ROOT + "auxiliary/GraphemeBreakTest.txt",
    "WordBreakTest.txt": UNICODE_ROOT + "auxiliary/WordBreakTest.txt",
    "SentenceBreakTest.txt": UNICODE_ROOT + "auxiliary/SentenceBreakTest.txt",
    "NormalizationTest.txt": UNICODE_ROOT + "NormalizationTest.txt",
    "BidiCharacterTest.txt": UNICODE_ROOT + "BidiCharacterTest.txt",
    "emoji-test.txt": "https://www.unicode.org/Public/17.0.0/emoji/emoji-test.txt",
}


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def write_json(path: Path, value: dict) -> None:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("symlink output")
    with path.open("x") as stream:
        json.dump(value, stream, indent=2, ensure_ascii=True, allow_nan=False)
        stream.write("\n")


def check_url(url: str) -> None:
    parsed = urllib.parse.urlsplit(url)
    if (
        parsed.scheme != "https"
        or parsed.hostname
        not in {"commons.wikimedia.org", "upload.wikimedia.org", "www.unicode.org"}
        or parsed.username is not None
        or parsed.password is not None
        or parsed.port not in {None, 443}
    ):
        raise ValueError("acquisition requires fixed HTTPS hosts")


class SafeRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        check_url(newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


class Budget:
    def __init__(self, journal: Path | None = None):
        self.bytes = 0
        self.started = time.monotonic()
        self.journal = journal
        if journal is not None:
            if any(p.is_symlink() for p in (journal, *journal.parents)):
                raise ValueError("symlink budget journal")
            journal.open("x").close()

    def checkpoint(self):
        if self.journal is not None:
            with self.journal.open("a") as stream:
                stream.write(
                    json.dumps(
                        {"downloaded_bytes": self.bytes, "seconds": time.monotonic() - self.started}
                    )
                    + "\n"
                )

    def deadline(self):
        if time.monotonic() - self.started >= MAX_SECONDS:
            raise TimeoutError("acquisition deadline")

    def fetch(self, url: str, limit: int = MAX_FILE) -> bytes:
        self.checkpoint()
        try:
            return self._fetch(url, limit)
        finally:
            self.checkpoint()

    def _fetch(self, url: str, limit: int) -> bytes:
        check_url(url)
        self.deadline()
        limit = min(limit, MAX_DOWNLOAD - self.bytes - 1)
        if limit <= 0:
            raise ValueError("acquisition byte budget exhausted")
        request = urllib.request.Request(  # noqa: S310 - validated fixed HTTPS hosts
            url, headers={"User-Agent": "SteganographyResearch/0.6"}
        )
        opener = urllib.request.build_opener(SafeRedirect)
        result = bytearray()
        with opener.open(request, timeout=15) as response:  # noqa: S310 - fixed HTTPS allowlist
            check_url(response.url)
            size = response.headers.get("Content-Length")
            if response.status != 200 or (size is not None and not 0 <= int(size) <= limit):
                raise ValueError("acquisition response/size bound")
            while True:
                self.deadline()
                chunk = response.read(min(65536, limit - len(result) + 1))
                if not chunk:
                    break
                self.bytes += len(chunk)
                result.extend(chunk)
                if len(result) > limit:
                    raise ValueError("acquisition byte bound")
            if not result or (size is not None and len(result) != int(size)):
                raise ValueError("empty/truncated acquisition")
        return bytes(result)


def inspect(data: bytes, family: str) -> dict:
    if family in {"png", "gif"}:
        with Image.open(io.BytesIO(data)) as image:
            if image.format != family.upper() or image.width * image.height > 8_000_000:
                raise ValueError("pilot image format/extent")
            frames = getattr(image, "n_frames", 1)
            if family == "png" and (image.mode != "RGB" or min(image.size) < 256 or frames != 1):
                raise ValueError("pilot requires native single RGB PNG >=256")
            if frames > 256 or frames * image.width * image.height > 32_000_000:
                raise ValueError("pilot GIF frame/pixel budget")
            decoded = hashlib.sha256()
            duration = 0
            for index in range(frames):
                image.seek(index)
                decoded.update(image.convert("RGB").tobytes())
                duration += image.info.get("duration", 0)
            return {
                "mode": image.mode,
                "width": image.width,
                "height": image.height,
                "frames": frames,
                "decoded_sha256": decoded.hexdigest(),
                "duration_ms": duration,
                "benign_comment": bool(image.info.get("comment")),
                "loop": image.info.get("loop"),
                "application_extension": bool(image.info.get("extension")),
            }
    if family == "wav":
        with wave.open(io.BytesIO(data)) as audio:
            if (
                audio.getnchannels() != 2
                or audio.getsampwidth() != 2
                or audio.getcomptype() != "NONE"
                or not 160 <= audio.getnframes() <= 4_410_000
                or not 8000 <= audio.getframerate() <= 192000
            ):
                raise ValueError("pilot requires native stereo PCM16")
            frames = audio.readframes(audio.getnframes())
            if len(frames) != audio.getnframes() * 4:
                raise ValueError("pilot truncated stereo")
            if frames[0::4] == frames[2::4] and frames[1::4] == frames[3::4]:
                raise ValueError("pilot duplicated mono")
            return {
                "channels": 2,
                "frames": audio.getnframes(),
                "sample_rate": audio.getframerate(),
                "decoded_sha256": digest(frames),
                "left_bytes_sha256": digest(
                    b"".join(frames[i : i + 2] for i in range(0, len(frames), 4))
                ),
                "right_bytes_sha256": digest(
                    b"".join(frames[i : i + 2] for i in range(2, len(frames), 4))
                ),
            }
    if family != "mp3":
        raise ValueError("unknown pilot family")
    # Inventory validation only: two native MPEG Layer III frame headers.
    offset = 0
    if data[:3] == b"ID3":
        if len(data) < 10 or any(v & 128 for v in data[6:10]):
            raise ValueError("invalid ID3 extent")
        offset = 10 + sum(v << shift for v, shift in zip(data[6:10], (21, 14, 7, 0), strict=True))
        offset += 10 if data[5] & 16 else 0
    begin = offset
    for _ in range(2):
        header = data[offset : offset + 4]
        if len(header) != 4 or header[0] != 255 or header[1] & 224 != 224:
            raise ValueError("native MPEG frame required")
        version, layer = (header[1] >> 3) & 3, (header[1] >> 1) & 3
        bitrate, rate = header[2] >> 4, (header[2] >> 2) & 3
        if version == 1 or layer != 1 or bitrate in (0, 15) or rate == 3:
            raise ValueError("native MP3 Layer III required")
        table = (
            (0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320)
            if version == 3
            else (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160)
        )
        hz = (44100, 48000, 32000)[rate] // (1 if version == 3 else 2 if version == 2 else 4)
        length = (144 if version == 3 else 72) * table[bitrate] * 1000 // hz
        offset += length + ((header[2] >> 1) & 1)
        if offset > len(data):
            raise ValueError("truncated native MP3")
    return {
        "decoded_sha256": None,
        "audio_bytes_sha256": digest(data[begin:]),
        "native_layer3_headers": 2,
        "decoder_validation": "unavailable",
    }


def metadata(page: dict, family: str) -> dict:
    info = page["imageinfo"][0]
    ext = info.get("extmetadata", {})

    def value(key):
        return html.unescape(re.sub("<[^>]+>", "", str(ext.get(key, {}).get("value", ""))))[:4096]

    license_name, license_url = value("LicenseShortName"), value("LicenseUrl")
    if not license_name or not (
        license_url.startswith("https://creativecommons.org/")
        or "public domain" in license_name.lower()
    ):
        raise ValueError("missing file-level license evidence")
    if info["size"] > MAX_FILE or info["size"] < 32:
        raise ValueError("pilot source byte bound")
    title = page["title"]
    if not title.lower().endswith("." + family):
        raise ValueError("pilot extension mismatch")
    author = value("Artist")
    return {
        "source_id": f"commons:{page['pageid']}",
        "title": title,
        "source_url": info["descriptionurl"],
        "original_url": info["url"],
        "license": license_name,
        "license_url": license_url,
        "author": author or None,
        "credit": value("Credit"),
        "object_name": value("ObjectName"),
        "known_group": author or None,
        "recording_group": None,
        "ancestry_independence": "unavailable",
        "declared_size": info["size"],
        "metadata_sha256": digest(json.dumps(page, sort_keys=True).encode()),
    }


def acquire(out: Path, *, unicode_only: bool = False) -> dict:
    if out.exists() or any(p.is_symlink() for p in (out, *out.parents)):
        raise FileExistsError("fresh nonsymlink pilot output required")
    out.mkdir(parents=True, mode=0o700)
    budget = Budget(out / "download-budget.jsonl")
    result: dict = {
        "schema_version": "nonjpeg-native-pilot-v1",
        "targets": TARGETS,
        "families": {},
        "unicode": {},
        "model_trained": False,
        "test_media_opened": False,
        "jpeg_data_added": False,
    }
    identities: set[str] = set()
    commons_available = not unicode_only
    for family, target in TARGETS.items():
        rows: list[dict] = []
        failures: Counter[str] = Counter()
        authors: Counter[str] = Counter()
        for page_index in range(8):
            if len(rows) >= target or not commons_available:
                break
            params = {
                "action": "query",
                "format": "json",
                "generator": "search",
                "gsrsearch": f"filemime:{MIMES[family]}",
                "gsrnamespace": 6,
                "gsrlimit": 50,
                "gsroffset": page_index * 50,
                "prop": "imageinfo",
                "iiprop": "url|size|mime|extmetadata",
                "iilimit": 1,
            }
            try:
                raw = budget.fetch(
                    "https://commons.wikimedia.org/w/api.php?" + urllib.parse.urlencode(params),
                    4 * 1024**2,
                )
                document = json.loads(raw)
                write_json(out / f"{family}-metadata-{page_index}.json", document)
                pages = sorted(
                    document.get("query", {}).get("pages", {}).values(),
                    key=lambda p: (p.get("index", 0), p.get("pageid", 0)),
                )
                if not pages:
                    failures["metadata_empty"] += 1
                    break
            except urllib.error.HTTPError as exc:
                failures[f"http_{exc.code}"] += 1
                commons_available = False
                break
            except (OSError, ValueError, TimeoutError):
                failures["metadata_access_unavailable"] += 1
                break
            for page in pages:
                if len(rows) >= target:
                    break
                try:
                    row = metadata(page, family)
                    if authors[row["author"] or "unknown"] >= 2:
                        failures["author_diversity_limit"] += 1
                        continue
                    data = budget.fetch(row["original_url"])
                    if len(data) != row["declared_size"]:
                        raise ValueError("original size mismatch")
                    representation = inspect(data, family)
                    identity = representation.get("decoded_sha256") or representation.get(
                        "audio_bytes_sha256"
                    )
                    if not isinstance(identity, str):
                        raise ValueError("missing carrier identity")
                    if identity in identities:
                        failures["duplicate_carrier"] += 1
                        continue
                    identities.add(identity)
                    filename = f"{family}-{len(rows):03d}.{family}"
                    (out / filename).open("xb").write(data)
                    row.update(
                        path=filename,
                        original_sha256=digest(data),
                        size=len(data),
                        representation=representation,
                        split="development_unassigned",
                    )
                    rows.append(row)
                    write_json(out / f"{filename}.source.json", row)
                    authors[row["author"] or "unknown"] += 1
                    time.sleep(1)  # respect the public service, including small pilots
                except urllib.error.HTTPError as exc:
                    failures[f"http_{exc.code}"] += 1
                    if exc.code in {403, 429, 503}:
                        commons_available = False
                        break
                except (OSError, ValueError, KeyError, EOFError, wave.Error):
                    failures["source_rejected_or_unavailable"] += 1
        result["families"][family] = {
            "status": "ready"
            if len(rows) == target
            else ("incomplete" if commons_available else "unavailable"),
            "count": len(rows),
            "missing": target - len(rows),
            "samples": rows,
            "failed_checks": dict(failures),
            "statistical_detection": "unavailable",
        }
        write_json(out / f"{family}-source.json", result["families"][family])
    for name, url in UNICODE_FILES.items():
        try:
            data = budget.fetch(url, 16 * 1024**2)
            text = data.decode("utf-8-sig")
            if "17.0" not in text[:4096]:
                raise ValueError("Unicode version mismatch")
            (out / name).open("xb").write(data)
            result["unicode"][name] = {
                "status": "ready",
                "version": "17.0.0",
                "url": url,
                "sha256": digest(data),
                "bytes": len(data),
            }
        except (OSError, ValueError):
            result["unicode"][name] = {"status": "unavailable", "url": url}
    result.update(
        downloaded_bytes=budget.bytes,
        raw_download_limit_bytes=MAX_DOWNLOAD,
        seconds=time.monotonic() - budget.started,
    )
    write_json(out / "report.json", result)
    return result

