"""Application services shared by the CLI and REST API."""

from __future__ import annotations

import hashlib
import json
import math
import os
import tempfile
import zlib
from collections.abc import Iterable
from pathlib import Path
from typing import Any

from core.context import AnalysisContext
from core.crypto import (
    KDF_SALT_LEN,
    DecryptionError,
    decrypt,
    decrypt_v3,
    encrypt,
    encrypt_v3,
)
from core.filetype import detect_type, extension_mismatch
from core.payload import VERSION_3, InvalidPayloadError, ParsedPayload, pack, pack_v3, unpack
from core.result import AnalysisResult, EmbedResult, FileAnalysis, FileInfo
from registry import Registry


class SteganographyError(Exception):
    """Base class for user-facing service failures."""


class ExtractionError(SteganographyError):
    """No unambiguous, valid payload could be extracted."""


class AmbiguousPayloadError(ExtractionError):
    """More than one carrier produced a valid payload."""


class OutputExistsError(SteganographyError):
    """Raised by the optional no-clobber policy."""


_PROFILE_MINIMUMS = {"sensitive": 10, "balanced": 25, "strict": 50}


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _severity(score: int) -> str:
    if score >= 70:
        return "high"
    if score >= 30:
        return "medium"
    return "low"


def aggregate_score(results: Iterable[AnalysisResult], profile: str) -> int:
    """Combine independent signal categories without double-counting a detector."""
    if profile not in _PROFILE_MINIMUMS:
        raise ValueError(f"unknown analysis profile: {profile}")
    threshold = _PROFILE_MINIMUMS[profile]
    categories: dict[str, int] = {}
    verified = False
    for result in results:
        if result.status != "ok":
            continue
        if result.analyzer == "ai_triage":
            # Triage is explanation only, even if a provider claims certainty.
            continue
        for signal in result.signals:
            if signal.evidence == "informational":
                continue
            if signal.evidence == "verified":
                verified = True
            if signal.score < threshold and signal.evidence != "verified":
                continue
            category = signal.category
            if category == "general":
                category = result.analyzer
            categories[category] = max(categories.get(category, 0), signal.score)

    if categories:
        clean_probability = math.prod(1.0 - score / 100.0 for score in categories.values())
        deterministic = round(100 * (1.0 - clean_probability))
    else:
        deterministic = 0
    if verified:
        deterministic = max(95, deterministic)
    return min(100, deterministic)


class AnalysisService:
    """Run every applicable detector and return a single resilient verdict."""

    def __init__(
        self,
        registry: Registry | None = None,
        *,
        profile: str = "sensitive",
        max_file_size: int | None = None,
        ai_provider: Any = None,
    ) -> None:
        if profile not in _PROFILE_MINIMUMS:
            raise ValueError(f"unknown analysis profile: {profile}")
        # Preserve ai_provider=None for existing local/benchmark callers, but
        # never accept a cloud provider or silently claim to have used one.
        if ai_provider is not None:
            raise ValueError("Cloud AI triage has been removed; use local analyzers")
        self.registry = registry or _discovered_registry()
        self.profile = profile
        self.max_file_size = max_file_size

    def analyze(self, path: Path) -> FileAnalysis:
        path = Path(path)
        if not path.is_file():
            raise FileNotFoundError(path)
        size = path.stat().st_size
        if self.max_file_size is not None and size > self.max_file_size:
            raise ValueError(f"file is {size} bytes; configured maximum is {self.max_file_size}")

        detected = detect_type(path)
        context = AnalysisContext(
            path,
            detected=detected,
            max_bytes=self.max_file_size or 512 * 1024 * 1024,
        )
        info = FileInfo(
            path=str(path),
            name=path.name,
            size=size,
            sha256=_sha256(path),
            detected_type=detected.name,
            mime_type=detected.mime_type,
            extension=path.suffix.lower(),
            extension_mismatch=extension_mismatch(path, detected),
        )
        results: list[AnalysisResult] = []
        for carrier in self.registry.select_carriers(path, detected_extension=detected.extension):
            results.append(_safe_context_analyze(carrier.identifier, carrier, context))

        for analyzer in self.registry.all_analyzers():
            if analyzer.name == "ai_triage":
                # Retired third-party adapters must not regain network access.
                continue
            results.append(_safe_context_analyze(analyzer.name, analyzer, context))

        score = aggregate_score(results, self.profile)
        return FileAnalysis(
            file=info,
            overall_score=score,
            severity=_severity(score),
            profile=self.profile,
            results=tuple(results),
        )

    def analyze_safe(self, path: Path) -> FileAnalysis:
        """Analyze a path, converting file-level failures into report evidence."""
        path = Path(path)
        try:
            return self.analyze(path)
        except Exception as exc:
            try:
                size = path.stat().st_size
            except OSError:
                size = 0
            info = FileInfo(
                path=str(path),
                name=path.name,
                size=size,
                sha256="",
                detected_type="unknown",
                mime_type="application/octet-stream",
                extension=path.suffix.lower(),
                extension_mismatch=False,
            )
            error = AnalysisResult(
                analyzer="scan",
                suspicion=0,
                signals=(),
                explanation=None,
                status="error",
                error=f"{type(exc).__name__}: {exc}",
            )
            return FileAnalysis(
                file=info,
                overall_score=0,
                severity="low",
                profile=self.profile,
                results=(error,),
            )


def _safe_analyze(name: str, analyze: Any, source: Any) -> AnalysisResult:
    try:
        return analyze(source)
    except Exception as exc:  # plug-ins must not terminate a directory scan
        return AnalysisResult(
            analyzer=name,
            suspicion=0,
            signals=(),
            explanation=None,
            status="error",
            error=f"{type(exc).__name__}: {exc}",
        )


def _safe_context_analyze(name: str, analyzer: Any, context: AnalysisContext) -> AnalysisResult:
    """Use the optional context contract while preserving legacy plug-ins."""
    contextual = getattr(analyzer, "analyze_context", None)
    if contextual is not None:
        return _safe_analyze(name, contextual, context)
    return _safe_analyze(name, analyzer.analyze, context.path)


class StegoService:
    """High-level embed/extract operations with crypto and payload validation."""

    def __init__(self, registry: Registry | None = None) -> None:
        self.registry = registry or _discovered_registry()

    def embed(
        self,
        input_path: Path,
        carrier_path: Path,
        out_path: Path,
        *,
        password: str | None = None,
        method: str | None = None,
        steg_key: str | None = None,
        options: dict[str, Any] | None = None,
        no_clobber: bool = False,
        payload_version: int = 2,
        compress: bool = False,
        ecc_symbols: int = 0,
    ) -> EmbedResult:
        input_path = Path(input_path)
        carrier_path = Path(carrier_path)
        out_path = Path(out_path)
        if not input_path.is_file():
            raise FileNotFoundError(input_path)
        if not carrier_path.is_file():
            raise FileNotFoundError(carrier_path)
        if no_clobber and out_path.exists():
            raise OutputExistsError(f"output already exists: {out_path}")

        carrier = self.registry.select_carrier_for_embed(carrier_path, method=method)
        raw = input_path.read_bytes()
        if payload_version == VERSION_3:
            payload_metadata: dict[str, object] = {
                "original_name": input_path.name,
                "original_size": len(raw),
            }
            stored = zlib.compress(raw) if compress else raw
            salt = os.urandom(KDF_SALT_LEN) if password else b"\x00" * 16
            if password:
                nonce, stored = encrypt_v3(
                    stored,
                    password,
                    salt,
                    associated_data=_v3_aad(payload_metadata),
                )
            else:
                nonce = b"\x00" * 12
            if ecc_symbols:
                stored = _ecc_encode(stored, ecc_symbols)
            blob = pack_v3(
                payload=stored,
                encrypted=bool(password),
                salt=salt,
                nonce=nonce,
                compressed=compress,
                ecc_symbols=ecc_symbols,
                metadata=payload_metadata,
            )
        elif payload_version != 2:
            raise ValueError("payload_version must be 2 or 3")
        elif password:
            salt = os.urandom(KDF_SALT_LEN)
            nonce, ciphertext = encrypt(raw, password, salt)
            blob = pack(payload=ciphertext, encrypted=True, salt=salt, nonce=nonce)
        else:
            blob = pack(
                payload=raw,
                encrypted=False,
                salt=b"\x00" * 16,
                nonce=b"\x00" * 12,
            )

        out_path.parent.mkdir(parents=True, exist_ok=True)
        temporary = _temporary_sibling(out_path)
        try:
            result = carrier.embed_with_options(
                carrier_path,
                blob,
                temporary,
                steg_key=steg_key or password,
                options=options,
            )
            os.replace(temporary, out_path)
        except Exception:
            temporary.unlink(missing_ok=True)
            raise
        return EmbedResult(
            carrier=result.carrier,
            out_path=out_path,
            bytes_written=result.bytes_written,
            encrypted=bool(password),
        )

    def extract(
        self,
        input_path: Path,
        *,
        password: str | None = None,
        method: str | None = None,
        steg_key: str | None = None,
        options: dict[str, Any] | None = None,
    ) -> tuple[bytes, str, int]:
        input_path = Path(input_path)
        if not input_path.is_file():
            raise FileNotFoundError(input_path)
        detected = detect_type(input_path)
        if method:
            candidates = [self.registry.get_carrier(method)]
        else:
            candidates = self.registry.select_carriers(
                input_path, detected_extension=detected.extension
            )
        candidates = [carrier for carrier in candidates if carrier.can_extract]
        if not candidates:
            raise ExtractionError(f"no extractable carrier for {input_path}")

        successes: list[tuple[str, ParsedPayload]] = []
        failures: list[str] = []
        for carrier in candidates:
            try:
                blob = carrier.extract_with_options(
                    input_path,
                    steg_key=steg_key or password,
                    options=options,
                )
                successes.append((carrier.identifier, unpack(blob)))
            except (Exception, InvalidPayloadError) as exc:
                failures.append(f"{carrier.identifier}: {type(exc).__name__}: {exc}")

        if not successes:
            detail = "; ".join(failures) if failures else "no candidates"
            raise ExtractionError(f"no valid payload found ({detail})")
        if len(successes) > 1 and method is None:
            names = ", ".join(name for name, _ in successes)
            raise AmbiguousPayloadError(
                f"multiple valid payloads found ({names}); select one with --method"
            )
        carrier_name, parsed = successes[0]
        stored = parsed.payload
        if parsed.version == VERSION_3 and parsed.ecc_symbols:
            stored = _ecc_decode(stored, parsed.ecc_symbols)
        if parsed.encrypted:
            if not password:
                raise ExtractionError(
                    "payload encrypted; set --password, --password-file, or STEGANO_PASSWORD"
                )
            try:
                if parsed.version == VERSION_3:
                    data = decrypt_v3(
                        stored,
                        password,
                        parsed.salt,
                        parsed.nonce,
                        associated_data=_v3_aad(parsed.metadata or {}),
                    )
                else:
                    data = decrypt(stored, password, parsed.salt, parsed.nonce)
            except DecryptionError as exc:
                raise ExtractionError("payload authentication failed") from exc
        else:
            data = stored
        if parsed.version == VERSION_3 and parsed.compressed:
            try:
                data = zlib.decompress(data)
            except zlib.error as exc:
                raise ExtractionError("payload decompression failed") from exc
        return data, carrier_name, parsed.version

    def extract_to(
        self,
        input_path: Path,
        out_path: Path,
        **kwargs: Any,
    ) -> tuple[int, str, int]:
        out_path = Path(out_path)
        no_clobber = bool(kwargs.pop("no_clobber", False))
        if no_clobber and out_path.exists():
            raise OutputExistsError(f"output already exists: {out_path}")
        data, carrier, version = self.extract(input_path, **kwargs)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        temporary = _temporary_sibling(out_path)
        try:
            temporary.write_bytes(data)
            os.replace(temporary, out_path)
        except Exception:
            temporary.unlink(missing_ok=True)
            raise
        return len(data), carrier, version


def _temporary_sibling(path: Path) -> Path:
    descriptor, value = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=path.suffix, dir=path.parent
    )
    os.close(descriptor)
    temporary = Path(value)
    temporary.unlink(missing_ok=True)
    return temporary


def _discovered_registry() -> Registry:
    registry = Registry()
    registry.autodiscover()
    return registry


def _ecc_encode(payload: bytes, symbols: int) -> bytes:
    try:
        from reedsolo import RSCodec
    except ImportError as exc:
        raise SteganographyError(
            "reedsolo is required when Reed-Solomon protection is enabled"
        ) from exc
    return bytes(RSCodec(symbols).encode(payload))


def _v3_aad(metadata: dict[str, object]) -> bytes:
    canonical = json.dumps(
        metadata, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    return b"STEG-payload-v3\x00" + canonical


def _ecc_decode(payload: bytes, symbols: int) -> bytes:
    try:
        from reedsolo import ReedSolomonError, RSCodec
    except ImportError as exc:
        raise ExtractionError("reedsolo is required to decode this protected payload") from exc
    try:
        return bytes(RSCodec(symbols).decode(payload)[0])
    except ReedSolomonError as exc:
        raise ExtractionError("Reed-Solomon recovery failed") from exc

core/spatial_colab_readiness.py.utf8:
"""Read-only Colab readiness; hardware visibility never establishes resource control."""

from __future__ import annotations

import importlib.metadata
import os
import platform
import re
import resource
import shutil
import subprocess
import tempfile
import time
from dataclasses import asdict, dataclass
from pathlib import Path, PurePosixPath

from core import colab_artifacts as a

MAX_SECONDS = 60
MAX_OUTPUT_BYTES = 65536
PACKAGES = ("numpy", "Pillow", "torch", "onnx", "onnxruntime")
EXPECTED = {"python": "3.12.13", "numpy": "2.0.2", "Pillow": "11.3.0"}
COUNTERS = {
    "v2": ("memory.max", "memory.swap.max", "memory.peak", "memory.current"),
    "v1": (
        "memory.limit_in_bytes", "memory.memsw.limit_in_bytes",
        "memory.max_usage_in_bytes", "memory.usage_in_bytes",
    ),
}


@dataclass(frozen=True)
class ResourceMetadata:
    status: str
    reason: str
    version: str | None = None
    counters: tuple[tuple[str, int | None], ...] = ()


@dataclass(frozen=True)
class GpuMetadata:
    status: str
    reason: str
    name: str | None = None
    vram_mib: int | None = None
    driver: str | None = None


def resources(
    *, proc_root: Path = Path("/proc"), cgroup_root: Path = Path("/sys/fs/cgroup"),
    pid: int | None = None,
) -> ResourceMetadata:
    """Refuse inaccessible namespace identities; never normalize parent segments."""
    process = os.getpid() if pid is None else pid
    if type(process) is not int or not 0 < process < 2**31:
        raise ValueError("positive bounded process identity required")
    try:
        raw = a.read(proc_root / str(process) / "cgroup", 4096).decode()
        candidates = []
        for line in raw.splitlines():
            fields = line.split(":", 2)
            if len(fields) != 3 or not fields[0].isascii() or not fields[0].isdecimal():
                return ResourceMetadata("unavailable", "malformed_identity")
            hierarchy, controllers, relative = fields
            version = "v1" if "memory" in controllers.split(",") else "v2"
            if version == "v2" and (hierarchy != "0" or controllers):
                continue
            path = PurePosixPath(relative)
            if ".." in path.parts:
                return ResourceMetadata("unavailable", "parent_identity", version)
            if not path.is_absolute() or len(path.parts) > 32 or "\x00" in relative:
                return ResourceMetadata("unavailable", "malformed_identity", version)
            folder = cgroup_root / "memory" if version == "v1" else cgroup_root
            candidates.append((version, folder.joinpath(*path.parts[1:])))
        if len(candidates) != 1:
            return ResourceMetadata("unavailable", "ambiguous_or_missing_controller")
        version, folder = candidates[0]
        counters = []
        for name in COUNTERS[version]:
            value = a.read(folder / name, 32).decode().strip()
            if value == "max":
                number = None
            elif value.isascii() and value.isdecimal() and len(value) <= 20:
                number = int(value)
                number = number if number < 2**60 else None
            else:
                return ResourceMetadata("unavailable", "malformed_counter", version)
            counters.append((name, number))
        return ResourceMetadata(
            "observed_metadata_only", "not_enforcement", version, tuple(counters)
        )
    except (OSError, UnicodeError, ValueError):
        return ResourceMetadata("unavailable", "inaccessible_or_unsafe_metadata")


def gpu(*, workdir: Path | None = None) -> GpuMetadata:
    """One fixed, bounded NVIDIA query; no Torch import or tensor operation."""
    if workdir is not None:
        a.safe(workdir)
    limiter, binary = shutil.which("prlimit"), shutil.which("nvidia-smi")
    if limiter is None or binary is None:
        return GpuMetadata("unavailable", "missing_query_tool")
    arguments = [
        limiter, "--fsize=8192:8192", "--cpu=5:5", "--", binary,
        "--query-gpu=name,memory.total,driver_version", "--format=csv,noheader,nounits",
    ]
    try:
        with tempfile.TemporaryFile(dir=workdir) as capture:
            process = subprocess.run(  # noqa: S603 -- fixed system query and kernel limits
                arguments, stdout=capture, stderr=subprocess.STDOUT, timeout=10, check=False,
            )
            capture.seek(0)
            raw = capture.read(8193)
        if process.returncode or len(raw) > 8192:
            return GpuMetadata("unavailable", "query_failed_or_oversized")
        lines = raw.decode("ascii").strip().splitlines()
        if len(lines) != 1:
            return GpuMetadata("unavailable", "single_gpu_required")
        fields = [text.strip() for text in lines[0].split(",")]
        if (
            len(fields) != 3 or not 0 < len(fields[0]) <= 128
            or not all(32 <= ord(c) < 127 for c in fields[0])
            or not fields[1].isdigit() or len(fields[1]) > 6
            or not 0 < int(fields[1]) <= 524288
            or re.fullmatch(r"[0-9]{1,4}(?:\.[0-9]{1,4}){1,3}", fields[2]) is None
        ):
            return GpuMetadata("unavailable", "invalid_query_format")
        return GpuMetadata("visible_metadata_only", "not_kernel_execution", fields[0],
                           int(fields[1]), fields[2])
    except subprocess.TimeoutExpired:
        return GpuMetadata("unavailable", "query_timeout")
    except (OSError, UnicodeError):
        return GpuMetadata("unavailable", "query_unavailable")


def inventory(*, check_gpu: bool = False, workdir: Path | None = None) -> dict:
    """Observe independent components; resource failure does not skip the GPU query."""
    if type(check_gpu) is not bool:
        raise ValueError("explicit boolean GPU query choice required")
    packages = {}
    for name in PACKAGES:
        try:
            packages[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            packages[name] = "unavailable"
    observed = {"python": platform.python_version(), **packages}
    expected = {**EXPECTED, "torch": "2.11.0+cu128" if check_gpu else "2.11.0+cpu"}
    matches = all(observed.get(k) == v for k, v in expected.items())
    host = resources()
    card = gpu(workdir=workdir) if check_gpu else GpuMetadata("not_requested", "cpu_default")
    if not matches:
        status = "unavailable_environment"
    elif check_gpu and card.status != "visible_metadata_only":
        status = "unavailable_gpu"
    elif host.status != "observed_metadata_only":
        status = "partial_resources_unavailable"
    else:
        status = "metadata_ready_only"
    return {
        "schema": "spatial-colab-readiness-v3", "status": status,
        "python": observed["python"], "packages": packages, "package_metadata_matches": matches,
        "resources": asdict(host), "gpu": asdict(card), "resource_enforcement": "unverified",
        "process_limits": {
            name: list(resource.getrlimit(key))
            for name, key in (("address_space", resource.RLIMIT_AS),
                              ("cpu_seconds", resource.RLIMIT_CPU),
                              ("file_bytes", resource.RLIMIT_FSIZE))
        },
        "models_created": 0, "optimizer_updates": 0, "tensor_operations": 0,
        "torch_imported_by_service": False, "profile_attempt_started": False,
    }


def record(out: Path, *, check_gpu: bool = False) -> dict:
    """Exclusive metadata evidence, without allocating a runtime or authorizing fitting."""
    if type(check_gpu) is not bool:
        raise ValueError("explicit boolean GPU query choice required")
    started = time.monotonic()
    a.directory(out)
    a.put(out / "attempt.json", a.encode({
        "schema": "spatial-colab-readiness-attempt-v3", "check_gpu": check_gpu,
        "max_seconds": MAX_SECONDS, "retry": False,
    }))
    result = inventory(check_gpu=check_gpu, workdir=out)
    result["seconds"] = time.monotonic() - started
    if result["seconds"] > MAX_SECONDS:
        result["status"] = "unavailable_deadline"
    result["receipt_sha256"] = a.put(out / "result.json", a.encode(result), MAX_OUTPUT_BYTES)
    return result

core/spatial_colab_state.py.utf8:
"""Numeric AdamW resume format; exercised only with generated states here."""

from __future__ import annotations

import json
import math
import platform
import random
import struct
from pathlib import Path

import numpy as np

from core import colab_artifacts as artifacts
from core import spatial_colab as profile
from core import srnet_model

MAGIC = b"SPCOLAB1"
MAX_BYTES = 128 * artifacts.MIB
MAX_META = 65536


def specs(meta: dict) -> dict:
    if not isinstance(meta, dict) or set(meta) != {
        "schema",
        "domain",
        "environment",
        "source_sha256",
        "data_sha256",
        "order_sha256",
        "optimizer",
        "initialized",
        "rng_bytes",
        "numpy_rng",
        "python_gauss",
        "consumption",
        "rows",
        "training",
    }:
        raise ValueError("checkpoint metadata fields")
    if meta["schema"] != "spatial-colab-state-v1" or meta["domain"] not in profile.DOMAINS:
        raise ValueError("checkpoint domain")
    if type(meta["training"]) is not bool:
        raise ValueError("checkpoint model mode")
    for key in ("source_sha256", "data_sha256", "order_sha256"):
        artifacts.identity(meta[key])
    env = meta["environment"]
    if not isinstance(env, dict) or set(env) != {
        "python",
        "numpy",
        "pillow",
        "torch",
        "cuda",
        "cudnn",
        "gpu",
    }:
        raise ValueError("checkpoint environment")
    if any(
        v is not None and (not isinstance(v, (str, int)) or len(str(v)) > 128) for v in env.values()
    ):
        raise ValueError("checkpoint environment values")
    count = meta["consumption"]
    if not isinstance(count, dict) or set(count) != {
        "epoch",
        "cursor",
        "optimizer_updates",
        "presentations",
        "elapsed_seconds",
        "output_bytes",
    }:
        raise ValueError("checkpoint consumption fields")
    if any(
        type(count[k]) is not int or not 0 <= count[k] <= 10**12
        for k in count
        if k != "elapsed_seconds"
    ):
        raise ValueError("checkpoint consumption bounds")
    if (
        type(count["elapsed_seconds"]) not in (int, float)
        or not math.isfinite(count["elapsed_seconds"])
        or count["elapsed_seconds"] < 0
    ):
        raise ValueError("checkpoint time debit")
    rows = meta["rows"]
    if type(rows) is not int or not 1 <= rows <= 100_000 or count["cursor"] > rows:
        raise ValueError("checkpoint order bounds")
    if not isinstance(meta["rng_bytes"], dict) or set(meta["rng_bytes"]) != {"cpu", "cuda"}:
        raise ValueError("checkpoint RNG fields")
    for key, size in meta["rng_bytes"].items():
        if type(size) is not int or not (16 <= size <= 16384 or key == "cuda" and size == 0):
            raise ValueError("checkpoint RNG size")
    if (env["gpu"] is None) != (meta["rng_bytes"]["cuda"] == 0):
        raise ValueError("checkpoint device/RNG mismatch")
    nrng = meta["numpy_rng"]
    if (
        not isinstance(nrng, list)
        or len(nrng) != 3
        or type(nrng[0]) is not int
        or not 0 <= nrng[0] <= 624
        or nrng[1] not in (0, 1)
        or not isinstance(nrng[2], (int, float))
        or not math.isfinite(nrng[2])
    ):
        raise ValueError("checkpoint NumPy RNG metadata")
    if meta["python_gauss"] is not None and (
        type(meta["python_gauss"]) not in (int, float) or not math.isfinite(meta["python_gauss"])
    ):
        raise ValueError("checkpoint Python RNG metadata")
    optimizer: dict = meta["optimizer"]
    if not isinstance(optimizer, dict) or set(optimizer) != {
        "lr",
        "betas",
        "eps",
        "weight_decay",
        "amsgrad",
        "maximize",
        "foreach",
        "capturable",
        "differentiable",
        "fused",
    }:
        raise ValueError("checkpoint AdamW options")
    if (
        optimizer["amsgrad"] is not False
        or optimizer["maximize"] is not False
        or optimizer["capturable"] is not False
        or optimizer["differentiable"] is not False
        or optimizer["foreach"] is not False
        or optimizer["fused"] is not False
    ):
        raise ValueError("checkpoint requires explicit scalar FP32 AdamW")
    for key in ("lr", "eps", "weight_decay"):
        if (
            type(optimizer[key]) not in (int, float)
            or not math.isfinite(optimizer[key])
            or optimizer[key] < 0
        ):
            raise ValueError("checkpoint optimizer finite bounds")
    if (
        not isinstance(optimizer["betas"], list)
        or len(optimizer["betas"]) != 2
        or any(
            type(v) not in (int, float) or not math.isfinite(v) or not 0 <= v < 1
            for v in optimizer["betas"]
        )
    ):
        raise ValueError("checkpoint optimizer betas")
    shapes = dict(srnet_model.SHAPES)
    if meta["domain"] == profile.DOMAINS[1]:
        shapes["front.0.0.weight"] = (64, 3, 3, 3)
    params = [k for k in shapes if k.endswith(("weight", "bias"))]
    if meta["initialized"] not in ([], params) or (
        count["optimizer_updates"] > 0 and not meta["initialized"]
    ):
        raise ValueError("checkpoint initialized optimizer states")
    result = {"model/" + k: (shape, srnet_model.dtype(k)) for k, shape in shapes.items()}
    for key in meta["initialized"]:
        for slot in ("step", "exp_avg", "exp_avg_sq"):
            result[f"optimizer/{key}/{slot}"] = (
                () if slot == "step" else shapes[key],
                np.dtype("<f4"),
            )
    result.update(
        {
            "rng/cpu": ((meta["rng_bytes"]["cpu"],), np.dtype("u1")),
            "rng/python": ((625,), np.dtype("<u4")),
            "rng/numpy": ((624,), np.dtype("<u4")),
            "data/order": ((rows,), np.dtype("<i8")),
        }
    )
    if meta["rng_bytes"]["cuda"]:
        result["rng/cuda"] = ((meta["rng_bytes"]["cuda"],), np.dtype("u1"))
    return result


def validate(meta: dict, arrays: dict) -> None:
    expected = specs(meta)
    if set(arrays) != set(expected):
        raise ValueError("checkpoint array keys")
    for key, (shape, dtype) in expected.items():
        value = arrays[key]
        if (
            not isinstance(value, np.ndarray)
            or value.shape != shape
            or value.dtype != dtype
            or not np.isfinite(value).all()
        ):
            raise ValueError("checkpoint numeric shape/dtype/finite")
        if key.endswith(("exp_avg_sq", "running_var")) and np.any(value < 0):
            raise ValueError("checkpoint negative variance")
        if key.endswith("/step") and float(value) != meta["consumption"]["optimizer_updates"]:
            raise ValueError("checkpoint optimizer debit mismatch")
    order = arrays["data/order"]
    if (
        not np.array_equal(np.sort(order), np.arange(meta["rows"]))
        or artifacts.digest(order.tobytes()) != meta["order_sha256"]
    ):
        raise ValueError("checkpoint data order mismatch")
    if int(arrays["rng/python"][-1]) > 624:
        raise ValueError("checkpoint Python RNG index")


def optimizer_options(model, optimizer) -> dict:
    import torch

    if type(optimizer) is not torch.optim.AdamW or len(optimizer.param_groups) != 1:
        raise ValueError("checkpoint supports one AdamW group")
    group = optimizer.param_groups[0]
    if [id(p) for p in group["params"]] != [id(p) for p in model.parameters()]:
        raise ValueError("checkpoint optimizer parameter order")
    keys = (
        "lr",
        "betas",
        "eps",
        "weight_decay",
        "amsgrad",
        "maximize",
        "foreach",
        "capturable",
        "differentiable",
        "fused",
    )
    return {k: list(group[k]) if k == "betas" else group[k] for k in keys}


def capture(
    model, optimizer, *, source_sha256: str, data_sha256: str, order: np.ndarray, consumption: dict
) -> tuple[dict, dict]:
    import torch

    if any(module.training != model.training for module in model.modules()):
        raise ValueError("checkpoint requires uniform train/eval mode")
    cpu = torch.get_rng_state().numpy().copy()
    cuda = (
        torch.cuda.get_rng_state(0).cpu().numpy().copy()
        if torch.cuda.is_available()
        else np.empty(0, dtype="u1")
    )
    python = random.getstate()
    numpy = np.random.get_state()
    if not isinstance(numpy, tuple) or numpy[0] != "MT19937":
        raise ValueError("checkpoint requires NumPy MT19937 state")
    arrays = {"model/" + k: v.detach().cpu().numpy().copy() for k, v in model.state_dict().items()}
    arrays.update(
        {
            "rng/cpu": cpu,
            "rng/python": np.array(python[1], dtype="<u4"),
            "rng/numpy": numpy[1].astype("<u4"),
            "data/order": order.copy(),
        }
    )
    if len(cuda):
        arrays["rng/cuda"] = cuda
    initialized = []
    for name, parameter in model.named_parameters():
        state = optimizer.state.get(parameter, {})
        if state:
            if set(state) != {"step", "exp_avg", "exp_avg_sq"}:
                raise ValueError("checkpoint optimizer slot keys")
            initialized.append(name)
            for slot, value in state.items():
                arrays[f"optimizer/{name}/{slot}"] = value.detach().cpu().numpy().copy()
    meta = {
        "schema": "spatial-colab-state-v1",
        "domain": model.architecture,
        "environment": profile.environment(),
        "source_sha256": source_sha256,
        "data_sha256": data_sha256,
        "order_sha256": artifacts.digest(order.tobytes()),
        "optimizer": optimizer_options(model, optimizer),
        "initialized": initialized,
        "rng_bytes": {"cpu": len(cpu), "cuda": len(cuda)},
        "python_gauss": python[2],
        "numpy_rng": [numpy[2], numpy[3], numpy[4]],
        "consumption": dict(consumption),
        "rows": len(order),
        "training": model.training,
    }
    validate(meta, arrays)
    return meta, arrays


def save(path: Path, meta: dict, arrays: dict) -> str:
    validate(meta, arrays)
    header = artifacts.encode(meta)
    if len(header) > MAX_META:
        raise ValueError("checkpoint header size")
    parts = [MAGIC, struct.pack("<I", len(header)), header]
    for key in sorted(arrays):
        parts.append(arrays[key].tobytes(order="C"))
    return artifacts.put(path, b"".join(parts), MAX_BYTES)


def load(
    path: Path, *, checksum: str, environment: dict, source_sha256: str, data_sha256: str
) -> tuple[dict, dict]:
    raw = artifacts.read(path, MAX_BYTES)
    if artifacts.digest(raw) != artifacts.identity(checksum) or raw[:8] != MAGIC or len(raw) < 12:
        raise ValueError("checkpoint checksum/header")
    size = struct.unpack("<I", raw[8:12])[0]
    if not 1 <= size <= MAX_META or len(raw) < 12 + size:
        raise ValueError("checkpoint metadata extent")
    meta = json.loads(raw[12 : 12 + size])
    expected = specs(meta)
    if (
        meta["environment"] != environment
        or meta["source_sha256"] != source_sha256
        or meta["data_sha256"] != data_sha256
    ):
        raise ValueError("checkpoint incompatible environment/source/data")
    offset = 12 + size
    total = offset + sum(math.prod(shape) * dtype.itemsize for shape, dtype in expected.values())
    if len(raw) != total:
        raise ValueError("checkpoint truncated/extra numeric extent")
    arrays = {}
    for key in sorted(expected):
        shape, dtype = expected[key]
        count = math.prod(shape)
        arrays[key] = (
            np.frombuffer(raw, dtype=dtype, count=count, offset=offset).reshape(shape).copy()
        )
        offset += count * dtype.itemsize
    validate(meta, arrays)
    return meta, arrays


def restore(model, optimizer, meta: dict, arrays: dict) -> dict:
    import torch

    validate(meta, arrays)
    if (
        meta["environment"] != profile.environment()
        or meta["domain"] != model.architecture
        or meta["optimizer"] != optimizer_options(model, optimizer)
    ):
        raise ValueError("checkpoint incompatible restore target")
    if len(arrays["rng/cpu"]) != len(torch.get_rng_state()) or (
        "rng/cuda" in arrays and len(arrays["rng/cuda"]) != len(torch.cuda.get_rng_state(0))
    ):
        raise ValueError("checkpoint incompatible RNG size")
    model_arrays = {
        k.removeprefix("model/"): value for k, value in arrays.items() if k.startswith("model/")
    }
    target = model.state_dict()
    if set(target) != set(model_arrays) or any(
        tuple(target[k].shape) != value.shape or target[k].dtype != torch.from_numpy(value).dtype
        for k, value in model_arrays.items()
    ):
        raise ValueError("checkpoint incompatible model tensors")
    # Validate RNG encodings before touching the target or global generators.
    torch.Generator().set_state(torch.from_numpy(arrays["rng/cpu"].copy()))
    if "rng/cuda" in arrays:
        torch.Generator(device="cuda:0").set_state(torch.from_numpy(arrays["rng/cuda"].copy()))
    state = {
        k.removeprefix("model/"): torch.from_numpy(v.copy())
        for k, v in arrays.items()
        if k.startswith("model/")
    }
    model.load_state_dict(state, strict=True)
    model.train(meta["training"])
    model.zero_grad(set_to_none=True)
    optimizer.state.clear()
    for name, parameter in model.named_parameters():
        if name in meta["initialized"]:
            optimizer.state[parameter] = {
                slot: torch.from_numpy(arrays[f"optimizer/{name}/{slot}"].copy()).to(
                    "cpu" if slot == "step" else parameter.device
                )
                for slot in ("step", "exp_avg", "exp_avg_sq")
            }
    random.setstate((3, tuple(int(v) for v in arrays["rng/python"]), meta["python_gauss"]))
    np.random.set_state(("MT19937", arrays["rng/numpy"], *meta["numpy_rng"]))
    torch.set_rng_state(torch.from_numpy(arrays["rng/cpu"].copy()))
    if "rng/cuda" in arrays:
        torch.cuda.set_rng_state(torch.from_numpy(arrays["rng/cuda"].copy()), 0)
    return {"consumption": dict(meta["consumption"]), "order": arrays["data/order"].copy()}


def generated_probe(out: Path) -> dict:
    """One generated numeric round trip per domain; zero optimizer calls."""
    import torch

    artifacts.directory(out)
    records = []
    for domain in profile.DOMAINS:
        with torch.random.fork_rng(devices=[]):
            model = profile.models.network(domain)
            optimizer = torch.optim.AdamW(model.parameters(), foreach=False, fused=False)
            meta, arrays = capture(
                model,
                optimizer,
                source_sha256="0" * 64,
                data_sha256="1" * 64,
                order=np.array([2, 0, 1], dtype="<i8"),
                consumption={
                    "epoch": 0,
                    "cursor": 0,
                    "optimizer_updates": 0,
                    "presentations": 0,
                    "elapsed_seconds": 0,
                    "output_bytes": 0,
                },
            )
            path = out / ("gray.numeric" if domain == profile.DOMAINS[0] else "rgb.numeric")
            checksum = save(path, meta, arrays)
            restored_meta, restored_arrays = load(
                path,
                checksum=checksum,
                environment=meta["environment"],
                source_sha256="0" * 64,
                data_sha256="1" * 64,
            )
            restore(model, optimizer, restored_meta, restored_arrays)
            if any(
                not np.array_equal(value, restored_arrays[key]) for key, value in arrays.items()
            ):
                raise ValueError("generated roundtrip mismatch")
            records.append({"domain": domain, "sha256": checksum, "bytes": path.stat().st_size})
    return {
        "status": "ready",
        "generated_only": True,
        "optimizer_updates": 0,
        "states": records,
        "python": platform.python_version(),
    }

