"""Training-only BN context/refresh controls; source weights remain immutable."""

import numpy as np

from core import srnet, srnet_model, srnet_multibatch, srnet_reference, srnet_sanity


def checked(model, pixels, samples):
    if (
        getattr(model, "architecture", None) != srnet.ARCHITECTURE
        or any(m.training for m in model.modules())
        or not isinstance(pixels, np.ndarray)
        or pixels.dtype != np.dtype("<f4")
        or pixels.shape != (24, 1, 256, 256)
        or len(samples) != 24
        or not np.isfinite(pixels).all()
        or np.any(np.abs(pixels) > 2**36)
    ):
        raise ValueError("BN refresh requires 24 bounded train tensors and an eval model")
    import torch

    state = model.state_dict()
    if any(v.device.type != "cpu" for v in state.values()):
        raise ValueError("BN refresh requires CPU numeric state")
    srnet_model.validate({k: v.detach().numpy() for k, v in state.items()})
    layers = [m for m in model.modules() if isinstance(m, torch.nn.BatchNorm2d)]
    if len(layers) != 26 or any(not m.track_running_stats for m in layers):
        raise ValueError("BN refresh requires 26 tracked BN layers")
    batches, schedule = srnet_multibatch.epoch_batches(samples, seed=20261012, epoch=19)
    if batches.shape != (8, 4):
        raise ValueError("BN refresh requires eight complete final-epoch batches")
    return layers, batches, schedule


def context(model, pixels, samples):
    layers, batches, schedule = checked(model, pixels, samples)
    import torch

    saved = {k: v.detach().clone() for k, v in model.state_dict().items()}
    flags = [(m, m.training) for m in model.modules()]
    tracking = [(m, m.track_running_stats) for m in layers]
    previous, results = torch.get_num_threads(), {}
    try:
        torch.set_num_threads(2)
        with torch.random.fork_rng(devices=[]), torch.no_grad():
            for mode in ("stored_bn", "batch_statistics_diagnostic_only"):
                if mode != "stored_bn":
                    for m in layers:
                        m.training, m.track_running_stats = True, False
                outputs, metrics = [], []
                for batch in batches:
                    logits = model(torch.from_numpy(pixels[batch].copy())).detach().numpy()
                    final = srnet_sanity.metrics(logits, [samples[i] for i in batch])
                    outputs.append({"indices": batch.tolist(), "logits": logits.tolist()})
                    metrics.append(final)
                results[mode] = {
                    "batches": outputs,
                    "presented_rows": 32,
                    "metrics": {
                        k: float(np.mean([m[k] for m in metrics]))
                        for k in (
                            "cross_entropy",
                            "balanced_accuracy",
                            "recall",
                            "false_positive_rate",
                        )
                    },
                }
    finally:
        changed = any(not torch.equal(v, saved[k]) for k, v in model.state_dict().items())
        model.load_state_dict(saved, strict=True)
        for m, flag in flags:
            m.training = flag
        for m, flag in tracking:
            m.track_running_stats = flag
        torch.set_num_threads(previous)
    if changed:
        raise ValueError("BN context attempted source-state mutation")
    return {"state_unchanged": True, "epoch_batch_schedule": schedule, **results}


def refresh(model, pixels, samples):
    _, batches, schedule = checked(model, pixels, samples)
    import torch

    source = {k: v.detach().clone() for k, v in model.state_dict().items()}
    source_flags = [(m, m.training) for m in model.modules()]
    source_bn = [
        (m, m.track_running_stats, m.momentum)
        for m in model.modules()
        if isinstance(m, torch.nn.BatchNorm2d)
    ]
    previous = torch.get_num_threads()
    with torch.random.fork_rng(devices=[]):
        clone = srnet.network().eval()
    clone.load_state_dict(source, strict=True)
    layers = [m for m in clone.modules() if isinstance(m, torch.nn.BatchNorm2d)]
    momentum = [(m, m.momentum) for m in layers]
    try:
        torch.set_num_threads(2)
        for m in layers:
            m.reset_running_stats()
            m.momentum, m.training = None, True
        with torch.random.fork_rng(devices=[]), torch.no_grad():
            for batch in batches:
                logits = clone(torch.from_numpy(pixels[batch].copy())).detach().numpy()
                srnet_sanity.metrics(logits, [samples[i] for i in batch])
    finally:
        source_changed = any(not torch.equal(v, source[k]) for k, v in model.state_dict().items())
        model.load_state_dict(source, strict=True)
        for m, flag in source_flags:
            m.training = flag
        for m, tracking, value in source_bn:
            m.track_running_stats, m.momentum = tracking, value
        for m, value in momentum:
            m.momentum = value
        clone.eval()
        torch.set_num_threads(previous)
    arrays = {k: v.detach().numpy() for k, v in clone.state_dict().items()}
    srnet_model.validate(arrays)
    if any(int(v) != 8 for k, v in arrays.items() if k.endswith("num_batches_tracked")):
        raise ValueError("BN refresh clone counter mismatch")
    allowed = ("running_mean", "running_var", "num_batches_tracked")
    changed = [k for k, v in clone.state_dict().items() if not torch.equal(v, source[k])]
    if any(not k.endswith(allowed) for k in changed) or source_changed:
        raise ValueError("BN refresh changed learned parameters or source state")
    return clone, {
        "changed_buffers": changed,
        "source_state_unchanged": True,
        "learned_parameters_bit_identical": True,
        "bn_refresh_batches": 8,
        "optimizer_steps": 0,
        "epoch_batch_schedule": schedule,
        "exact_population_variance": False,
    }


def objectives(own, baseline):
    if any(
        type(d.get(k)) not in (int, float) or not np.isfinite(d[k]) or d[k] < 0
        for d in (own, baseline)
        for k in ("balanced_accuracy", "cross_entropy")
    ) or any(d["balanced_accuracy"] > 1 for d in (own, baseline)):
        raise ValueError("BN refresh requires finite training-only metrics")
    return {
        "own_train_balanced_accuracy_at_least_0_90": own["balanced_accuracy"] >= 0.90,
        "own_train_cross_entropy_below_baseline": own["cross_entropy"] < baseline["cross_entropy"],
    }


def oracles(model, pixels, samples, logits):
    checked(model, pixels, samples)
    selected, seen = [], set()
    for i, s in enumerate(samples):
        key = (s["source_group"], s["quality_factor"], s["label"], s["method"])
        if key not in seen:
            selected.append(i)
            seen.add(key)
    if len(selected) != 9:
        raise ValueError("BN refresh oracle coverage incomplete")
    arrays = {k: v.detach().numpy() for k, v in model.state_dict().items()}
    result = [
        {
            "row": i,
            "source_sha256": samples[i]["sha256"],
            **srnet_reference.compare(
                logits[i : i + 1], srnet_reference.reference_logits(arrays, pixels[i : i + 1])
            ),
        }
        for i in selected
    ]
    return {
        "independent_oracles": result,
        "numerical_gates_passed": all(r["passed"] for r in result),
    }

core/srnet_checkpoint.py.utf8:
"""Bounded numeric epoch checkpoints: no pickle, code, downloads or deployment."""

from __future__ import annotations

import hashlib
import io
import json
import math
import stat
import zipfile

import numpy as np

from core import srnet, srnet_model
from core.jpeg_scale import identity
from core.srnet_stream import regular_open

MAX_BYTES = 96 * 1024**2
MAX_META = 65536
PARAMETERS = {k: v for k, v in srnet_model.SHAPES.items() if k.endswith(("weight", "bias"))}


def schedule(batches, epochs, *, deadline=None):
    if type(epochs) is not int or not 1 <= epochs <= 50:
        raise ValueError("checkpoint epoch count outside bounds")
    counts, digest = [], hashlib.sha256()
    for epoch in range(epochs):
        if deadline is not None:
            deadline()
        values = batches(epoch)
        if (
            not isinstance(values, np.ndarray)
            or values.dtype.kind not in "iu"
            or values.ndim != 2
            or values.shape[1] != 4
            or not 1 <= len(values) <= 100000
            or np.any(values < 0)
            or np.any(values >= 12000)
        ):
            raise ValueError("checkpoint requires bounded deterministic four-row schedules")
        counts.append(len(values))
        digest.update(np.asarray(values, dtype="<i8").tobytes())
    return counts, digest.hexdigest()


def metadata(meta):
    from core.srnet_training import settings

    keys = {
        "schema_version",
        "architecture",
        "binding",
        "seed",
        "settings",
        "device",
        "torch_version",
        "epochs",
        "next_epoch",
        "epoch_training",
        "scheduled_updates",
        "schedule_sha256",
        "cpu_rng_bytes",
        "cuda_rng_bytes",
        "accuracy_qualification",
    }
    if not isinstance(meta, dict) or set(meta) != keys:
        raise ValueError("checkpoint metadata contract mismatch")
    identity(meta["binding"])
    identity(meta["schedule_sha256"])
    if (
        meta["schema_version"] != "srnet-epoch-checkpoint-v1"
        or meta["architecture"] != srnet.ARCHITECTURE
        or not isinstance(meta["device"], str)
        or meta["device"] not in {"cpu", "cuda:0"}
        or type(meta["seed"]) is not int
        or not 0 <= meta["seed"] < 2**32
        or type(meta["epochs"]) is not int
        or not 1 <= meta["epochs"] <= 50
        or type(meta["next_epoch"]) is not int
        or not 1 <= meta["next_epoch"] <= meta["epochs"]
        or not isinstance(meta["torch_version"], str)
        or not 1 <= len(meta["torch_version"]) <= 128
        or any(
            c not in "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ.+_-"
            for c in meta["torch_version"]
        )
        or meta["accuracy_qualification"] != "unavailable"
        or not isinstance(meta["settings"], dict)
        or set(meta["settings"]) != {"threads", "max_seconds", "learning_rate", "weight_decay"}
        or settings(meta["settings"]) != meta["settings"]
        or type(meta["cpu_rng_bytes"]) is not int
        or not 16 <= meta["cpu_rng_bytes"] <= 16384
        or type(meta["cuda_rng_bytes"]) is not int
        or (
            meta["cuda_rng_bytes"] != 0
            if meta["device"] == "cpu"
            else not 16 <= meta["cuda_rng_bytes"] <= 16384
        )
        or not isinstance(meta["scheduled_updates"], list)
        or len(meta["scheduled_updates"]) != meta["epochs"]
        or any(type(v) is not int or not 1 <= v <= 100000 for v in meta["scheduled_updates"])
        or not isinstance(meta["epoch_training"], list)
        or len(meta["epoch_training"]) != meta["next_epoch"]
    ):
        raise ValueError("checkpoint metadata values invalid")
    for epoch, record in enumerate(meta["epoch_training"]):
        if (
            not isinstance(record, dict)
            or set(record) != {"epoch", "updates", "mean_pair_loss"}
            or type(record["epoch"]) is not int
            or record["epoch"] != epoch
            or type(record["updates"]) is not int
            or record["updates"] != meta["scheduled_updates"][epoch]
            or type(record["mean_pair_loss"]) not in (int, float)
            or not math.isfinite(record["mean_pair_loss"])
            or record["mean_pair_loss"] < 0
        ):
            raise ValueError("checkpoint complete-epoch accounting invalid")


def specs(meta):
    result = {"model/" + k: (s, srnet_model.dtype(k)) for k, s in srnet_model.SHAPES.items()}
    for name, shape in PARAMETERS.items():
        for slot in ("exp_avg", "exp_inf", "step"):
            result[f"optimizer/{name}/{slot}"] = (() if slot == "step" else shape, np.dtype("<f4"))
    result["rng/cpu"] = ((meta["cpu_rng_bytes"],), np.dtype("u1"))
    if meta["device"] == "cuda:0":
        result["rng/cuda"] = ((meta["cuda_rng_bytes"],), np.dtype("u1"))
    return result


def validate(snapshot):
    if not isinstance(snapshot, dict) or set(snapshot) != {"metadata", "arrays"}:
        raise ValueError("checkpoint container contract mismatch")
    meta, arrays = snapshot["metadata"], snapshot["arrays"]
    metadata(meta)
    expected = specs(meta)
    if not isinstance(arrays, dict) or set(arrays) != set(expected):
        raise ValueError("checkpoint numeric keys mismatch")
    updates = sum(meta["scheduled_updates"][: meta["next_epoch"]])
    for name, (shape, dtype) in expected.items():
        value = arrays[name]
        if (
            not isinstance(value, np.ndarray)
            or value.shape != shape
            or value.dtype != dtype
            or not np.isfinite(value).all()
        ):
            raise ValueError("checkpoint numeric shape/dtype/finite mismatch")
        if name.endswith("/exp_inf") and np.any(value < 0):
            raise ValueError("checkpoint negative Adamax infinity norm")
        if (name.endswith("/step") or name.endswith("num_batches_tracked")) and float(
            value
        ) != updates:
            raise ValueError("checkpoint optimizer/BN update count mismatch")
    srnet_model.validate({k: arrays["model/" + k] for k in srnet_model.SHAPES})


def capture(model, optimizer, records, context):
    import torch

    arrays = {"model/" + k: v.detach().cpu().numpy().copy() for k, v in model.state_dict().items()}
    for name, parameter in model.named_parameters():
        for slot in ("exp_avg", "exp_inf", "step"):
            arrays[f"optimizer/{name}/{slot}"] = (
                optimizer.state[parameter][slot].detach().cpu().numpy().copy()
            )
    arrays["rng/cpu"] = torch.get_rng_state().numpy().copy()
    if context["device"] == "cuda:0":
        arrays["rng/cuda"] = torch.cuda.get_rng_state(0).numpy().copy()
    meta = {
        **json.loads(json.dumps(context, allow_nan=False)),
        "schema_version": "srnet-epoch-checkpoint-v1",
        "architecture": srnet.ARCHITECTURE,
        "next_epoch": len(records),
        "epoch_training": [dict(r) for r in records],
        "torch_version": str(torch.__version__),
        "cpu_rng_bytes": len(arrays["rng/cpu"]),
        "cuda_rng_bytes": len(arrays.get("rng/cuda", [])),
        "accuracy_qualification": "unavailable",
    }
    result = {"metadata": meta, "arrays": arrays}
    validate(result)
    return result


def restore(snapshot, model, optimizer, context):
    import torch

    validate(snapshot)
    meta, arrays = snapshot["metadata"], snapshot["arrays"]
    if any(meta[k] != v for k, v in context.items()) or meta["torch_version"] != str(
        torch.__version__
    ):
        raise ValueError("checkpoint binding/settings/schedule/backend mismatch")
    if meta["cpu_rng_bytes"] != len(torch.get_rng_state()) or (
        meta["device"] == "cuda:0" and meta["cuda_rng_bytes"] != len(torch.cuda.get_rng_state(0))
    ):
        raise ValueError("checkpoint RNG implementation mismatch")
    model.load_state_dict(
        {k: torch.from_numpy(arrays["model/" + k].copy()) for k in srnet_model.SHAPES}, strict=True
    )
    for name, parameter in model.named_parameters():
        optimizer.state[parameter] = {
            slot: torch.from_numpy(arrays[f"optimizer/{name}/{slot}"].copy()).to(
                "cpu" if slot == "step" else context["device"]
            )
            for slot in ("exp_avg", "exp_inf", "step")
        }
    torch.set_rng_state(torch.from_numpy(arrays["rng/cpu"].copy()))
    if context["device"] == "cuda:0":
        torch.cuda.set_rng_state(torch.from_numpy(arrays["rng/cuda"].copy()), 0)
    return [dict(r) for r in meta["epoch_training"]]


def save(snapshot, path):
    validate(snapshot)
    if path.exists() or any(p.is_symlink() for p in (path, *path.parents)):
        raise FileExistsError("checkpoint output exists or uses a symlink")
    raw_meta = json.dumps(snapshot["metadata"], sort_keys=True, allow_nan=False).encode()
    if len(raw_meta) > MAX_META:
        raise ValueError("checkpoint metadata size exceeded")
    buffer = io.BytesIO()
    np.savez(buffer, **snapshot["arrays"], __metadata__=np.frombuffer(raw_meta, dtype="u1"))
    raw = buffer.getvalue()
    if len(raw) > MAX_BYTES:
        raise ValueError("checkpoint size exceeded")
    with path.open("xb") as stream:
        stream.write(raw)
    return hashlib.sha256(raw).hexdigest()


def header(stream):
    version = np.lib.format.read_magic(stream)
    if version == (1, 0):
        return np.lib.format.read_array_header_1_0(stream, max_header_size=4096)
    if version == (2, 0):
        return np.lib.format.read_array_header_2_0(stream, max_header_size=4096)
    raise ValueError("checkpoint array header version invalid")


def load(path, *, checksum):
    identity(checksum)
    with regular_open(path) as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES or hashlib.sha256(raw).hexdigest() != checksum:
        raise ValueError("checkpoint checksum/size mismatch")
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        members = archive.infolist()
        if (
            not 1 <= len(members) <= 512
            or len({m.filename for m in members}) != len(members)
            or "__metadata__.npy" not in {m.filename for m in members}
            or sum(m.file_size for m in members) > MAX_BYTES
            or any(
                m.compress_type != zipfile.ZIP_STORED
                or m.flag_bits & 1
                or stat.S_ISLNK(m.external_attr >> 16)
                for m in members
            )
        ):
            raise ValueError("checkpoint archive limits/encoding invalid")
        with archive.open("__metadata__.npy") as stream:
            shape, _, dtype = header(stream)
            if len(shape) != 1 or not 1 <= shape[0] <= MAX_META or dtype != np.dtype("u1"):
                raise ValueError("checkpoint metadata header invalid")
            info = archive.getinfo("__metadata__.npy")
            if stream.tell() + shape[0] != info.file_size:
                raise ValueError("checkpoint metadata length invalid")
            meta = json.loads(stream.read(shape[0]))
        metadata(meta)
        expected = {**specs(meta), "__metadata__": (shape, np.dtype("u1"))}
        if {m.filename for m in members} != {k + ".npy" for k in expected}:
            raise ValueError("checkpoint archive members invalid")
        for member in members:
            with archive.open(member) as stream:
                actual_shape, _, dtype = header(stream)
                wanted_shape, wanted_dtype = expected[member.filename[:-4]]
                if (
                    actual_shape != wanted_shape
                    or dtype != wanted_dtype
                    or stream.tell() + math.prod(actual_shape) * dtype.itemsize != member.file_size
                ):
                    raise ValueError("checkpoint array shape/dtype/length invalid")
    with np.load(io.BytesIO(raw), allow_pickle=False, max_header_size=4096) as archive:
        result = {"metadata": meta, "arrays": {k: archive[k].copy() for k in specs(meta)}}
    validate(result)
    return result

core/srnet_diagnostics.py.utf8:
"""Read-only paired BN-mode contrast; never a detector or calibration mode."""

from __future__ import annotations

import numpy as np

from core import srnet, srnet_model


def paired_probe(model, pixels):
    if (
        getattr(model, "architecture", None) != srnet.ARCHITECTURE
        or any(m.training for m in model.modules())
        or not isinstance(pixels, np.ndarray)
        or pixels.dtype != np.dtype("<f4")
        or pixels.shape != (2, 1, 256, 256)
        or not np.isfinite(pixels).all()
        or np.any(np.abs(pixels) > 2**36)
    ):
        raise ValueError("BN diagnosis requires an eval model and one bounded float256 pair")
    import torch

    arrays = {k: v.detach().cpu().numpy() for k, v in model.state_dict().items()}
    srnet_model.validate(arrays)
    saved = {k: v.detach().clone() for k, v in model.state_dict().items()}
    flags = [(m, m.training) for m in model.modules()]
    layers = [(name, m) for name, m in model.named_modules() if isinstance(m, torch.nn.BatchNorm2d)]
    if len(layers) != 26:
        raise ValueError("BN diagnosis requires the exact architecture")
    tracking = [(m, m.track_running_stats) for _, m in layers]
    hooks = []
    summaries: dict[str, list[dict]] = {}
    mode = "native"

    def capture(name, module, args):
        values = args[0].detach().to(torch.float64)
        mean = values.mean(dim=(0, 2, 3))
        variance = values.var(dim=(0, 2, 3), unbiased=True)
        shift = torch.abs(mean - saved[name + ".running_mean"]) / torch.sqrt(
            saved[name + ".running_var"] + module.eps
        )
        ratio = (variance + module.eps) / (saved[name + ".running_var"] + module.eps)
        if not bool(torch.isfinite(shift).all() and torch.isfinite(ratio).all()):
            raise ValueError("BN diagnosis produced nonfinite layer statistics")
        summaries[mode].append(
            {
                "layer": name,
                "median_standardized_mean_shift": float(np.median(shift.cpu().numpy())),
                "maximum_standardized_mean_shift": float(shift.max()),
                "median_variance_ratio": float(np.median(ratio.cpu().numpy())),
                "maximum_variance_ratio": float(ratio.max()),
            }
        )

    results = {}
    try:
        for name, module in layers:
            hooks.append(
                module.register_forward_pre_hook(
                    lambda module, args, name=name: capture(name, module, args)
                )
            )
        with torch.no_grad():
            for mode in ("native", "batch_statistics"):
                summaries[mode] = []
                if mode == "batch_statistics":
                    for _, module in layers:
                        module.training, module.track_running_stats = True, False
                logits = model(torch.from_numpy(pixels.copy())).detach().cpu().numpy()
                if logits.shape != (2, 2) or not np.isfinite(logits).all():
                    raise ValueError("BN diagnosis produced invalid logits")
                if len(summaries[mode]) != 26:
                    raise ValueError("BN diagnosis incomplete layer coverage")
                scores = np.exp(-np.logaddexp(0, logits[:, 0].astype(np.float64) - logits[:, 1]))
                margins = logits[:, 1].astype(np.float64) - logits[:, 0]
                loss = (np.logaddexp(0, margins[0]) + np.logaddexp(0, -margins[1])) / 2
                results[mode] = {
                    "logits": logits.tolist(),
                    "scores": scores.tolist(),
                    "stego_decisions": (logits[:, 1] >= logits[:, 0]).tolist(),
                    "paired_cross_entropy": float(loss),
                    "layers": summaries[mode],
                }
    finally:
        for hook in hooks:
            hook.remove()
        for module, training in flags:
            module.training = training
        for module, tracked in tracking:
            module.track_running_stats = tracked
        with torch.no_grad():
            changed = any(
                not torch.equal(value, saved[k]) for k, value in model.state_dict().items()
            )
            model.load_state_dict(saved, strict=True)
    if changed:
        raise ValueError("BN diagnosis attempted to mutate model state")
    return {"state_unchanged": True, **results}

core/srnet_groupnorm.py.utf8:
"""Explicit experimental eight-group SRNet variant; legacy BN stays unchanged."""

from __future__ import annotations

import hashlib
import io

import numpy as np

from core import srnet, srnet_model

ARCHITECTURE = "srnet-gray12-groupnorm8-research-v1"
SHAPES = {
    k: v
    for k, v in srnet_model.SHAPES.items()
    if not k.endswith(("running_mean", "running_var", "num_batches_tracked"))
}


def network():
    import torch

    model = srnet.network()
    count = 0
    for parent in list(model.modules()):
        for name, child in list(parent.named_children()):
            if isinstance(child, torch.nn.BatchNorm2d):
                if child.num_features % 8 or child.weight is None or child.bias is None:
                    raise ValueError("GN requires tracked affine divisible channel layers")
                norm = torch.nn.GroupNorm(
                    8,
                    child.num_features,
                    eps=child.eps,
                    affine=True,
                    dtype=torch.float32,
                    device="cpu",
                )
                norm.load_state_dict({"weight": child.weight.detach(), "bias": child.bias.detach()})
                setattr(parent, name, norm)
                count += 1
    if count != 26:
        raise ValueError("GN requires the exact 26-layer architecture")
    model.architecture = ARCHITECTURE
    validate(model.state_dict())
    return model


def validate(state):
    import torch

    if set(state) != set(SHAPES):
        raise ValueError("GN numeric keys mismatch")
    floats, device = [], None
    for name, shape in SHAPES.items():
        value = state[name]
        if (
            not isinstance(value, torch.Tensor)
            or tuple(value.shape) != shape
            or value.dtype != torch.float32
            or value.layout != torch.strided
            or value.device.type not in {"cpu", "cuda"}
            or value.device.index not in {None, 0}
            or (device is not None and device != value.device)
        ):
            raise ValueError("GN numeric shape/dtype/device mismatch")
        device = value.device
        floats.append(value.detach().reshape(-1))
    with torch.no_grad():
        if not bool(torch.isfinite(torch.cat(floats)).all()):
            raise ValueError("GN numeric state nonfinite")


def parameter_sha(model):
    """Bind the common learned tensors, excluding architecture-specific buffers."""
    digest = hashlib.sha256()
    for name, value in sorted(model.named_parameters()):
        digest.update(name.encode() + b"\0")
        digest.update(value.detach().cpu().numpy().astype("<f4", copy=False).tobytes())
    return digest.hexdigest()


def save_model(model, path):
    if path.exists() or any(p.is_symlink() for p in (path, *path.parents)):
        raise FileExistsError("GN snapshot exists or uses symlink")
    if getattr(model, "architecture", None) != ARCHITECTURE or any(
        m.training for m in model.modules()
    ):
        raise ValueError("GN snapshot requires the distinct eval architecture")
    validate(model.state_dict())
    arrays = {k: v.detach().cpu().numpy() for k, v in model.state_dict().items()}
    buffer = io.BytesIO()
    np.savez(buffer, **arrays)
    raw = buffer.getvalue()
    if len(raw) > srnet_model.MAX_BYTES:
        raise ValueError("GN snapshot exceeds bound")
    # Round-trip only these just-produced, bounded bytes, never an untrusted archive.
    with np.load(io.BytesIO(raw), allow_pickle=False) as archive:
        if any(not np.array_equal(arrays[k], archive[k]) for k in SHAPES):
            raise ValueError("GN snapshot round-trip mismatch")
    with path.open("xb") as stream:
        stream.write(raw)
    return hashlib.sha256(raw).hexdigest()

core/srnet_model.py.utf8:
"""Exact bounded numeric SRNet weights/BN state; never pickle or code."""

from __future__ import annotations

import hashlib
import io
import math
import zipfile
from pathlib import Path

import numpy as np

from core import srnet

MAX_BYTES = 32 * 1024**2


def shapes():
    result: dict[str, tuple[int, ...]] = {}

    def block(prefix, before, after, kernel=3):
        result[prefix + ".0.weight"] = (after, before, kernel, kernel)
        result[prefix + ".0.bias"] = (after,)
        for suffix in ("weight", "bias", "running_mean", "running_var"):
            result[prefix + ".1." + suffix] = (after,)
        result[prefix + ".1.num_batches_tracked"] = ()

    block("front.0", 1, 64)
    block("front.1", 64, 16)
    for i in range(2, 7):
        for branch in (0, 1):
            block(f"front.{i}.branch.{branch}", 16, 16)
    for i, (before, after) in enumerate(((16, 16), (16, 64), (64, 128), (128, 256))):
        block(f"middle.{i}.branch.0", before, after)
        block(f"middle.{i}.branch.1", after, after)
        block(f"middle.{i}.skip", before, after, kernel=1)
    block("tail.0", 256, 512)
    block("tail.1", 512, 512)
    result["classifier.weight"] = (2, 512)
    return result


SHAPES = shapes()


def dtype(name):
    return np.dtype("<i8" if name.endswith("num_batches_tracked") else "<f4")


def validate(arrays):
    if set(arrays) != set(SHAPES):
        raise ValueError("SRNet numeric state keys mismatch")
    for name, shape in SHAPES.items():
        value = arrays[name]
        if value.shape != shape or value.dtype != dtype(name) or not np.isfinite(value).all():
            raise ValueError("SRNet numeric state shape/dtype/finite mismatch")
        if name.endswith("running_var") and np.any(value < 0):
            raise ValueError("SRNet BN running variance is negative")
        if name.endswith("num_batches_tracked") and not 0 <= int(value) <= 10_000_000:
            raise ValueError("SRNet BN counter outside limits")


def validate_tensors(state):
    """Same numeric-state contract, with one host decision and no CPU copies."""
    import torch

    if not isinstance(state, dict) or set(state) != set(SHAPES):
        raise ValueError("SRNet numeric state keys mismatch")
    floats, variances, counters = [], [], []
    device = None
    for name, shape in SHAPES.items():
        value = state[name]
        counter = name.endswith("num_batches_tracked")
        if (
            not isinstance(value, torch.Tensor)
            or tuple(value.shape) != shape
            or value.dtype != (torch.int64 if counter else torch.float32)
            or value.layout != torch.strided
            or value.device.type not in {"cpu", "cuda"}
            or value.device.index not in {None, 0}
            or (device is not None and value.device != device)
        ):
            raise ValueError("SRNet numeric state shape/dtype/device mismatch")
        device = value.device
        value = value.detach().reshape(-1)
        if counter:
            counters.append(value)
        else:
            floats.append(value)
            if name.endswith("running_var"):
                variances.append(value)
    # Shapes bind total concatenation size to the fixed architecture. Only
    # comparisons/reductions are added; no model or optimizer state is changed.
    with torch.no_grad():
        count = torch.cat(counters)
        checks = torch.stack(
            [
                torch.isfinite(torch.cat(floats)).all(),
                (torch.cat(variances) >= 0).all(),
                ((count >= 0) & (count <= 10_000_000)).all(),
            ]
        )
        if not bool(checks.all()):
            raise ValueError("SRNet numeric state finite/variance/counter mismatch")


def save_model(model, path: Path):
    if path.exists() or any(p.is_symlink() for p in (path, *path.parents)):
        raise FileExistsError("SRNet output exists or uses a symlink")
    if getattr(model, "architecture", None) != srnet.ARCHITECTURE or any(
        m.training for m in model.modules()
    ):
        raise ValueError("SRNet snapshot requires correct architecture and all-stage eval")
    arrays = {k: v.detach().cpu().numpy() for k, v in model.state_dict().items()}
    validate(arrays)
    buffer = io.BytesIO()
    np.savez(buffer, **arrays)
    data = buffer.getvalue()
    if len(data) > MAX_BYTES:
        raise ValueError("SRNet numeric state exceeds byte limits")
    with path.open("xb") as stream:
        stream.write(data)
    return hashlib.sha256(data).hexdigest()


def load_model(path: Path, *, checksum: str):
    if (
        not path.is_file()
        or any(p.is_symlink() for p in (path, *path.parents))
        or path.stat().st_size > MAX_BYTES
    ):
        raise ValueError("SRNet model must be bounded regular non-symlink")
    with path.open("rb") as stream:
        data = stream.read(MAX_BYTES + 1)
    if len(data) > MAX_BYTES or hashlib.sha256(data).hexdigest() != checksum:
        raise ValueError("SRNet model checksum/byte limit failure")
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        members = archive.infolist()
        if (
            len(members) != len(SHAPES)
            or {m.filename for m in members} != {k + ".npy" for k in SHAPES}
            or sum(m.file_size for m in members) > MAX_BYTES
        ):
            raise ValueError("SRNet archive contract mismatch")
        for member in members:
            name = member.filename[:-4]
            with archive.open(member) as stream:
                version = np.lib.format.read_magic(stream)
                if version == (1, 0):
                    shape, _, kind = np.lib.format.read_array_header_1_0(
                        stream, max_header_size=4096
                    )
                elif version == (2, 0):
                    shape, _, kind = np.lib.format.read_array_header_2_0(
                        stream, max_header_size=4096
                    )
                else:
                    raise ValueError("unsupported SRNet array header")
                if (
                    shape != SHAPES[name]
                    or kind != dtype(name)
                    or stream.tell() + math.prod(shape) * kind.itemsize != member.file_size
                ):
                    raise ValueError("SRNet array header/size mismatch")
    with np.load(io.BytesIO(data), allow_pickle=False, max_header_size=4096) as archive:
        arrays = {k: archive[k] for k in SHAPES}
    validate(arrays)
    import torch

    with torch.random.fork_rng(devices=[]):
        model = srnet.network()
    model.load_state_dict({k: torch.from_numpy(v.copy()) for k, v in arrays.items()}, strict=True)
    return model.eval()

core/srnet_multibatch.py.utf8:
"""Complete four-row batches from two distinct declared source/lineage pairs."""

from __future__ import annotations

import hashlib
import json

from core.srnet_sampling import epoch_pairs

RECIPE = "two-source-two-lineage-pairs-v1"


def recipe(config):
    value = config.get("batch_recipe")
    if "batch_recipe" in config and value != RECIPE:
        raise ValueError("unsupported SRNet batch recipe")
    return value


def epoch_batches(samples, *, seed, epoch):
    pairs, _ = epoch_pairs(samples, seed=seed, epoch=epoch)
    return _group_pairs(samples, pairs, epoch=epoch)


def _group_pairs(samples, pairs, *, epoch):
    if len({s["source_group"] for s in samples}) != 2 or len(pairs) % 2:
        raise ValueError("SRNet multipair batches require exactly two complete sources")
    batches = pairs.reshape(-1, 4).copy()
    for c0, _s0, c1, _s1 in batches:
        first, second = samples[c0], samples[c1]
        if (
            first["source_group"] == second["source_group"]
            or first["sha256"] == second["sha256"]
            or (first["source_group"], first["lineage"])
            == (second["source_group"], second["lineage"])
        ):
            raise ValueError("SRNet multipair batches require distinct declared source lineages")
    identities = [[samples[i]["sha256"] for i in batch] for batch in batches]
    batches.flags.writeable = False
    return batches, {
        "recipe": RECIPE,
        "epoch": epoch,
        "batch_size": 4,
        "pairs": len(pairs),
        "optimizer_updates": len(batches),
        "rows": 4 * len(batches),
        "ordered_batch_sha256": hashlib.sha256(
            json.dumps(identities, separators=(",", ":")).encode()
        ).hexdigest(),
        "independence": (
            "distinct declared source/lineage; camera/perceptual independence unverified"
        ),
    }


def updates(plan):
    if recipe(plan.get("settings", {})) is None:
        return [e["pairs"] for e in plan["epochs"]]
    return [e["optimizer_updates"] for e in plan["epoch_batch_schedule"]]

core/srnet_population_bn.py.utf8:
"""Layerwise train-only population statistics, not detector qualification."""

from __future__ import annotations

import copy

import numpy as np

from core import srnet, srnet_model


def partition(samples):
    if not isinstance(samples, list) or len(samples) != 480:
        raise ValueError("population control requires the complete real kit")
    groups: dict[str, set[str]] = {}
    for row in samples:
        if row.get("split") != "train":
            raise ValueError("population control forbids validation/test rows")
        groups.setdefault(row["source_group"], set()).add(row["lineage"])
    if len(groups) != 3 or any(len(v) != 32 for v in groups.values()):
        raise ValueError("population original accounting mismatch")
    if len(set.union(*groups.values())) != 96:
        raise ValueError("population cross-source original leakage")
    selected = {s: set(sorted(v)[:24]) for s, v in groups.items()}
    calibration: list[int] = []
    probe: list[int] = []
    for i, row in enumerate(samples):
        target = calibration if row["lineage"] in selected[row["source_group"]] else probe
        target.append(i)
    if len(calibration) != 360 or len(probe) != 120:
        raise ValueError("population row accounting mismatch")
    return np.array(calibration, dtype=np.int64).reshape(-1, 4), np.array(
        probe, dtype=np.int64
    ).reshape(-1, 4)


def merge(previous, count, mean, m2):
    """Chan's central-moment merge, with count weighting (never mean of variances)."""
    if type(count) is not int or count < 1:
        raise ValueError("population count must be positive")
    if previous is None:
        return count, mean, m2
    old_count, old_mean, old_m2 = previous
    total = old_count + count
    delta = mean - old_mean
    return (
        total,
        old_mean + delta * (count / total),
        old_m2 + m2 + delta * delta * (old_count * count / total),
    )


class _Captured(Exception):
    pass


def refresh(model, fetch, batches, deadline):
    import torch

    if getattr(model, "architecture", None) != srnet.ARCHITECTURE or any(
        m.training for m in model.modules()
    ):
        raise ValueError("population refresh requires the immutable eval architecture")
    srnet_model.validate_tensors(dict(model.state_dict()))
    if (
        not isinstance(batches, np.ndarray)
        or batches.dtype != np.int64
        or batches.shape != (90, 4)
        or len(set(batches.reshape(-1).tolist())) != 360
        or np.any(batches < 0)
        or np.any(batches >= 480)
    ):
        raise ValueError("population calibration must contain 360 distinct bounded rows")
    clone = copy.deepcopy(model).eval()
    layers = [(n, m) for n, m in clone.named_modules() if isinstance(m, torch.nn.BatchNorm2d)]
    if len(layers) != 26 or any(
        not m.track_running_stats
        or m.running_mean is None
        or m.running_var is None
        or m.num_batches_tracked is None
        for _, m in layers
    ):
        raise ValueError("population refresh requires exactly 26 tracked layers")
    summaries = []
    device = next(clone.parameters()).device
    with torch.no_grad():
        for name, layer in layers:
            deadline()
            moments = None

            def capture(module, args):
                nonlocal moments
                deadline()
                values = args[0].detach().to(torch.float64)
                if values.ndim != 4 or values.shape[0] != 4:
                    raise ValueError("population activation shape mismatch")
                if not bool(torch.isfinite(values).all()):
                    raise ValueError("population activation nonfinite")
                variance, mean = torch.var_mean(values, dim=(0, 2, 3), correction=0)
                count = values.shape[0] * values.shape[2] * values.shape[3]
                moments = merge(moments, count, mean, variance * count)
                raise _Captured

            hook = layer.register_forward_pre_hook(capture)
            try:
                for batch in batches:
                    deadline()
                    pixels = fetch(batch)
                    if (
                        pixels.shape != (4, 1, 256, 256)
                        or pixels.dtype != np.dtype("<f4")
                        or not np.isfinite(pixels).all()
                        or np.any(np.abs(pixels) > 2**36)
                    ):
                        raise ValueError("population pixels outside bounds")
                    try:
                        clone(torch.from_numpy(pixels).to(device))
                    except _Captured:
                        pass
                    else:
                        raise ValueError("population target layer not reached")
            finally:
                hook.remove()
            if moments is None:
                raise ValueError("population moments absent")
            count, mean, m2 = moments
            if (
                layer.running_mean is None
                or layer.running_var is None
                or layer.num_batches_tracked is None
            ):
                raise ValueError("population running buffers disappeared")
            layer.running_mean.copy_(mean.to(torch.float32))
            layer.running_var.copy_((m2 / count).to(torch.float32))
            layer.num_batches_tracked.fill_(len(batches))
            srnet_model.validate_tensors(dict(clone.state_dict()))
            summaries.append({"layer": name, "activation_count_per_channel": count})
    allowed = ("running_mean", "running_var", "num_batches_tracked")
    if any(
        not torch.equal(value, model.state_dict()[name])
        for name, value in clone.state_dict().items()
        if not name.endswith(allowed)
    ):
        raise ValueError("population refresh changed learned weights")
    deadline()
    return clone, summaries

core/srnet_sampling.py.utf8:
"""Deterministic train-only cover/stego pairs, balanced by declared context."""

from __future__ import annotations

import hashlib
import json
import math
from collections import Counter
from typing import Any

import numpy as np

RECIPE = "srnet-source-quality-method-pairs-v1"
MAX_ROWS = 4000
MAX_PAIRS = 40_000
METHODS = {"JUNIWARD", "UERD"}


def source_id(source: str) -> str:
    return "source-" + hashlib.sha256(source.encode()).hexdigest()[:16]


def buckets(samples):
    return _buckets(samples, row_limit=MAX_ROWS)


def _buckets(samples, *, row_limit):
    if not isinstance(samples, list) or not 1 <= len(samples) <= row_limit:
        raise ValueError("SRNet sampling row limit")
    groups: dict[tuple[str, str, int | None], list[tuple[int, dict[str, Any]]]] = {}
    hashes = set()
    for i, sample in enumerate(samples):
        if not isinstance(sample, dict):
            raise ValueError("SRNet sampling requires training JPEG rows")
        source, lineage = sample.get("source_group"), sample.get("lineage")
        quality, digest = sample.get("quality_factor"), sample.get("sha256")
        if (
            sample.get("split") != "train"
            or sample.get("format") != "JPEG"
            or not isinstance(sample.get("label"), str)
            or sample["label"] not in {"cover", "stego"}
            or not isinstance(source, str)
            or not source.strip()
            or not isinstance(lineage, str)
            or not lineage.strip()
            or (quality is not None and (type(quality) is not int or not 1 <= quality <= 100))
            or not isinstance(digest, str)
            or len(digest) != 64
            or any(c not in "0123456789abcdef" for c in digest)
            or digest in hashes
        ):
            raise ValueError("SRNet sampling requires unique bound training JPEG rows")
        hashes.add(digest)
        groups.setdefault((source, lineage, quality), []).append((i, sample))
    result: dict[tuple[str, int | None, str], list[tuple[int, int]]] = {}
    for (source, _, quality), members in groups.items():
        covers = [(i, s) for i, s in members if s["label"] == "cover"]
        stegos = [(i, s) for i, s in members if s["label"] == "stego"]
        if (
            len(covers) != 1
            or covers[0][1].get("method") is not None
            or len(stegos) != 2
            or any(not isinstance(s.get("method"), str) for _, s in stegos)
            or {s["method"] for _, s in stegos} != METHODS
        ):
            raise ValueError("SRNet sampling requires complete matched-family pairs")
        for i, sample in stegos:
            result.setdefault((source_id(source), quality, sample["method"]), []).append(
                (covers[0][0], i)
            )
    return result


def epoch_pairs(samples, *, seed: int, epoch: int):
    """Equal sources, then equal quality/method cells; no discarded train pairs."""
    return _epoch_pairs(samples, seed=seed, epoch=epoch, row_limit=MAX_ROWS)


def _epoch_pairs(samples, *, seed, epoch, row_limit):
    if (
        type(seed) is not int
        or not 0 <= seed < 2**32
        or type(epoch) is not int
        or not 0 <= epoch < 50
    ):
        raise ValueError("SRNet sampling seed/epoch outside limits")
    cells = _buckets(samples, row_limit=row_limit)
    sources = sorted({key[0] for key in cells})
    if len(sources) > 8:
        raise ValueError("SRNet sampling source limit")
    keys = {s: sorted((k for k in cells if k[0] == s), key=repr) for s in sources}
    multiple = math.lcm(*(len(keys[s]) for s in sources))
    # Each bucket must exhaust every original pair at least once. Balance can
    # oversample small contexts, never silently truncate a large context.
    required = max(max(len(cells[k]) for k in keys[s]) * len(keys[s]) for s in sources)
    quota = ((required + multiple - 1) // multiple) * multiple
    if quota * len(sources) > MAX_PAIRS:
        raise ValueError("SRNet balanced sampling exceeds pair limit")
    rng = np.random.default_rng(np.random.SeedSequence([seed, epoch]))
    streams: dict[str, list[tuple[int, int]]] = {}
    for s in sources:
        streams[s] = []
        ordered_cells = [keys[s][i] for i in rng.permutation(len(keys[s]))]
        draws = quota // len(ordered_cells)
        sequences = {}
        for key in ordered_cells:
            original = cells[key]
            sequence: list[tuple[int, int]] = []
            while len(sequence) < draws:
                sequence.extend(original[i] for i in rng.permutation(len(original)))
            sequences[key] = sequence[:draws]
        for j in range(draws):
            streams[s].extend(sequences[key][j] for key in ordered_cells)
    order = [sources[i] for i in rng.permutation(len(sources))]
    pairs = np.asarray([streams[s][j] for j in range(quota) for s in order], dtype="<i8")
    pairs.flags.writeable = False
    counts = Counter(
        (
            source_id(samples[j]["source_group"]),
            samples[j].get("quality_factor"),
            samples[j]["method"],
        )
        for _, j in pairs
    )
    identity = [[samples[i]["sha256"], samples[j]["sha256"]] for i, j in pairs]
    record = {
        "recipe": RECIPE,
        "epoch": epoch,
        "pairs": len(pairs),
        "rows": 2 * len(pairs),
        "pairs_per_source": quota,
        "ordered_pair_sha256": hashlib.sha256(
            json.dumps(identity, separators=(",", ":")).encode()
        ).hexdigest(),
        "cells": [
            {
                "source_id": k[0],
                "quality_factor": k[1],
                "method": k[2],
                "original_pairs": len(cells[k]),
                "sampled_pairs": counts[k],
            }
            for k in sorted(cells, key=repr)
        ],
    }
    return pairs, record

core/srnet_sanity.py.utf8:
"""Train-only tiny-subset selection and in-sample learning objectives."""

import math

import numpy as np

from core.srnet_sampling import epoch_pairs


def select(samples):
    epoch_pairs(samples, seed=20261012, epoch=0)  # Validate all rows, including exclusions.
    if {s["source_group"] for s in samples} != {"ALASKA2", "BOSSbase-1.01"}:
        raise ValueError("tiny sanity requires both frozen declared sources")
    groups: dict[tuple[str, str], set[int | None]] = {}
    for row in samples:
        groups.setdefault((row["source_group"], row["lineage"]), set()).add(row["quality_factor"])
    alaska = sorted(
        k for k, qualities in groups.items() if k[0] == "ALASKA2" and qualities == {None}
    )[:4]
    boss = sorted(
        k for k, qualities in groups.items() if k[0] == "BOSSbase-1.01" and qualities == {75, 95}
    )[:2]
    if len(alaska) != 4 or len(boss) != 2:
        raise ValueError("tiny sanity requires four unknown-Q and two complete Q75/Q95 lineages")
    wanted = set(alaska + boss)
    indices = np.array(
        [i for i, s in enumerate(samples) if (s["source_group"], s["lineage"]) in wanted],
        dtype="<i8",
    )
    if len(indices) != 24:
        raise ValueError("tiny sanity requires exactly 24 complete train rows")
    indices.flags.writeable = False
    return indices


def metrics(logits, samples):
    if (
        not isinstance(logits, np.ndarray)
        or logits.dtype.kind != "f"
        or logits.shape != (len(samples), 2)
        or not 1 <= len(samples) <= 24
        or not np.isfinite(logits).all()
        or any(s["split"] != "train" or s["label"] not in {"cover", "stego"} for s in samples)
        or {s["label"] for s in samples} != {"cover", "stego"}
    ):
        raise ValueError("tiny sanity metrics require finite train-only logits")
    margins = logits[:, 1].astype(np.float64) - logits[:, 0]
    if not np.isfinite(margins).all():
        raise ValueError("tiny sanity metrics produced nonfinite margins")
    labels = np.array([s["label"] == "stego" for s in samples])
    losses = np.logaddexp(0, np.where(labels, -margins, margins))
    scores = np.exp(-np.logaddexp(0, -margins))
    decisions = margins >= 0
    return {
        "cross_entropy": float(losses.mean()),
        "balanced_accuracy": float(((decisions[labels]).mean() + (~decisions[~labels]).mean()) / 2),
        "recall": float(decisions[labels].mean()),
        "false_positive_rate": float(decisions[~labels].mean()),
        "scores": scores.tolist(),
    }


def objectives(records, final):
    if (
        type(final.get("balanced_accuracy")) not in (int, float)
        or not 0 <= final["balanced_accuracy"] <= 1
    ):
        raise ValueError("tiny sanity requires finite balanced accuracy")
    if len(records) != 50 or any(
        type(r.get("epoch")) is not int
        or type(r.get("updates")) is not int
        or r.get("epoch") != i
        or r.get("updates") != 8
        or type(r.get("mean_pair_loss")) not in (int, float)
        or not math.isfinite(r["mean_pair_loss"])
        or r["mean_pair_loss"] < 0
        for i, r in enumerate(records)
    ):
        raise ValueError("tiny sanity requires 50 complete finite epochs")
    first, last = records[0]["mean_pair_loss"], records[-1]["mean_pair_loss"]
    reduction = (first - last) / first if first else 0.0
    return {
        "final_batch_loss_at_most_0_35": last <= 0.35,
        "relative_loss_reduction_at_least_0_25": reduction >= 0.25,
        "stored_bn_train_balanced_accuracy_at_least_0_90": final["balanced_accuracy"] >= 0.90,
        "relative_loss_reduction": reduction,
    }

core/srnet_signal.py.utf8:
"""Artificial real-delta amplification learning controls, never detector accuracy."""

import hashlib
import time

import numpy as np

from core import (
    srnet,
    srnet_multibatch,
    srnet_positive,
    srnet_reference,
    srnet_sanity,
    srnet_training,
)
from core.srnet_sampling import epoch_pairs


def prepare(pixels, samples, *, factor):
    if (
        type(factor) is not int
        or factor not in (1, 32)
        or not isinstance(pixels, np.ndarray)
        or pixels.dtype != np.dtype("<f4")
        or pixels.shape != (24, 1, 256, 256)
        or not np.isfinite(pixels).all()
        or np.any(np.abs(pixels) > 2**36)
    ):
        raise ValueError("signal control requires 24 bounded float256 tensors and frozen factor")
    epoch_pairs(samples, seed=20261012, epoch=0)
    if len(samples) != 24:
        raise ValueError("signal control metadata/tensor cardinality mismatch")
    covers = {
        (s["source_group"], s["lineage"], s["quality_factor"]): i
        for i, s in enumerate(samples)
        if s["label"] == "cover"
    }
    result = pixels.copy()
    for i, s in enumerate(samples):
        if s["label"] == "stego":
            cover = pixels[covers[(s["source_group"], s["lineage"], s["quality_factor"])]].astype(
                np.float64
            )
            result[i] = cover + factor * (pixels[i].astype(np.float64) - cover)
    if not np.isfinite(result).all() or np.any(np.abs(result) > 2**36):
        raise ValueError("amplified signal tensor outside finite bounds")
    result.flags.writeable = False
    return result, [hashlib.sha256(p.tobytes()).hexdigest() for p in result]


def evaluate(model, pixels, samples):
    import torch

    previous = torch.get_num_threads()
    try:
        torch.set_num_threads(2)
        logits = np.array([srnet.float_logits(model, p[None])[0] for p in pixels])
    finally:
        torch.set_num_threads(previous)
    return logits, srnet_sanity.metrics(logits, samples)


def learn(original, samples, *, factor):
    pixels, hashes = prepare(original, samples, factor=factor)
    paired = [epoch_pairs(samples, seed=20261012, epoch=e)[1] for e in range(20)]
    batched = [
        srnet_multibatch.epoch_batches(samples, seed=20261012, epoch=e)[1] for e in range(20)
    ]
    started = time.monotonic()
    model, records = srnet_training.fit(
        pixels,
        samples,
        np.arange(24, dtype="<i8"),
        seed=20261012,
        schedule=paired,
        config={**srnet_positive.PARAMS, "batch_recipe": srnet_multibatch.RECIPE},
    )
    if any(int(v) != 160 for k, v in model.named_buffers() if k.endswith("num_batches_tracked")):
        raise ValueError("signal-control BN accounting mismatch")
    logits, metrics = evaluate(model, pixels, samples)
    original_logits, original_metrics = evaluate(model, original, samples)
    gates = srnet_positive.objectives(records, metrics)
    return model, {
        "factor": factor,
        "optimizer": srnet_positive.PARAMS.copy(),
        "seed": 20261012,
        "optimizer_updates": 160,
        "derived_tensor_sha256": hashes,
        "epoch_pair_schedule": paired,
        "epoch_batch_schedule": batched,
        "epoch_training": records,
        "own_input_singleton_logits": logits.tolist(),
        "own_input_train_metrics": metrics,
        "original_input_singleton_logits": original_logits.tolist(),
        "original_input_train_metrics": original_metrics,
        "learning_objectives": gates,
        "learning_objectives_passed": all(
            v for k, v in gates.items() if k != "relative_loss_reduction"
        ),
        "seconds": time.monotonic() - started,
    }


def audit(model, original, samples, report):
    pixels, hashes = prepare(original, samples, factor=report["factor"])
    if (
        hashes != report["derived_tensor_sha256"]
        or report["epoch_pair_schedule"]
        != [epoch_pairs(samples, seed=20261012, epoch=e)[1] for e in range(20)]
        or report["epoch_batch_schedule"]
        != [srnet_multibatch.epoch_batches(samples, seed=20261012, epoch=e)[1] for e in range(20)]
        or report["optimizer"] != srnet_positive.PARAMS
        or report["seed"] != 20261012
        or report["optimizer_updates"] != 160
    ):
        raise ValueError("signal-control content/schedule/optimizer mismatch")
    if any(int(v) != 160 for k, v in model.named_buffers() if k.endswith("num_batches_tracked")):
        raise ValueError("signal-control reloaded BN accounting mismatch")
    own_logits, own = evaluate(model, pixels, samples)
    original_logits, original_metrics = evaluate(model, original, samples)
    for logits, metrics, prefix in (
        (own_logits, own, "own_input"),
        (original_logits, original_metrics, "original_input"),
    ):
        stored = np.asarray(report[prefix + "_singleton_logits"], dtype=np.float64)
        if stored.shape != (24, 2) or not np.allclose(logits, stored, atol=1e-6, rtol=0):
            raise ValueError("signal-control singleton logits replay mismatch")
        if set(metrics) != set(report[prefix + "_train_metrics"]) or any(
            not np.allclose(v, report[prefix + "_train_metrics"][k], atol=1e-6, rtol=0)
            for k, v in metrics.items()
        ):
            raise ValueError("signal-control singleton metric replay mismatch")
    gates = srnet_positive.objectives(report["epoch_training"], own)
    if gates != report["learning_objectives"] or report["learning_objectives_passed"] is not all(
        v for k, v in gates.items() if k != "relative_loss_reduction"
    ):
        raise ValueError("signal-control objective replay mismatch")
    selected, seen = [], set()
    for i, s in enumerate(samples):
        key = (s["source_group"], s["quality_factor"], s["label"], s["method"])
        if key not in seen:
            selected.append(i)
            seen.add(key)
    if len(selected) != 9:
        raise ValueError("signal-control independent oracle coverage incomplete")
    arrays = {k: v.detach().numpy() for k, v in model.state_dict().items()}
    oracles = [
        {
            "row": i,
            "source_sha256": samples[i]["sha256"],
            "derived_tensor_sha256": hashes[i],
            **srnet_reference.compare(
                own_logits[i : i + 1], srnet_reference.reference_logits(arrays, pixels[i : i + 1])
            ),
        }
        for i in selected
    ]
    return {
        "all_own_and_original_singletons_replayed": True,
        "independent_oracles": oracles,
        "numerical_gates_passed": all(r["passed"] for r in oracles),
    }

core/studio.py.utf8:
"""High-level, API-safe Studio operations."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from core.filetype import detect_type
from core.payload import unpack
from core.service import StegoService


class StudioService:
    """Expose capacity/embed/extract without retaining passwords or steg keys."""

    def __init__(self, stego: StegoService | None = None) -> None:
        self.stego = stego or StegoService()

    def capacity(self, carrier_path: Path, *, method: str | None = None) -> dict[str, Any]:
        carrier_path = Path(carrier_path)
        detected = detect_type(carrier_path)
        if method:
            candidates = [self.stego.registry.get_carrier(method)]
        else:
            candidates = self.stego.registry.select_carriers(
                carrier_path, detected_extension=detected.extension
            )
        values = []
        for carrier in candidates:
            if not carrier.can_embed:
                continue
            try:
                raw_capacity = carrier.capacity(carrier_path)
                status = "available"
                error = None
            except Exception as exc:
                raw_capacity = 0
                status = "unavailable"
                error = f"{type(exc).__name__}: {exc}"
            values.append(
                {
                    "method": carrier.identifier,
                    "carrier_capacity_bytes": max(0, raw_capacity),
                    "payload_v3_capacity_bytes": max(0, raw_capacity - 128),
                    "status": status,
                    "error": error,
                    "detectability": "increases with payload density",
                    "recompression_resilience": (
                        "low" if detected.extension in {".png", ".bmp"} else "format-dependent"
                    ),
                }
            )
        return {"carrier_type": detected.name, "methods": values}

    def embed(self, *args: Any, **kwargs: Any):
        kwargs.setdefault("payload_version", 3)
        return self.stego.embed(*args, **kwargs)

    def preview(
        self,
        carrier_path: Path,
        *,
        method: str | None = None,
        steg_key: str | None = None,
    ) -> dict[str, Any]:
        """Read authenticated payload framing metadata without extracting data.

        Encrypted payload bytes remain encrypted.  The returned metadata is the
        small v3 envelope (original name and size), never payload contents.
        """
        carrier_path = Path(carrier_path)
        detected = detect_type(carrier_path)
        if method:
            candidates = [self.stego.registry.get_carrier(method)]
        else:
            candidates = self.stego.registry.select_carriers(
                carrier_path, detected_extension=detected.extension
            )
        failures: list[str] = []
        for carrier in candidates:
            if not carrier.can_extract:
                continue
            try:
                parsed = unpack(
                    carrier.extract_with_options(
                        carrier_path,
                        steg_key=steg_key,
                        options=None,
                    )
                )
                return {
                    "method": carrier.identifier,
                    "payload_version": parsed.version,
                    "encrypted": parsed.encrypted,
                    "compressed": parsed.compressed,
                    "ecc_symbols": parsed.ecc_symbols,
                    "metadata": parsed.metadata or {},
                }
            except Exception as exc:
                failures.append(f"{carrier.identifier}: {type(exc).__name__}")
        detail = ", ".join(failures) or "no extractable carrier"
        raise ValueError(f"payload metadata unavailable ({detail})")

    def extract(self, *args: Any, **kwargs: Any):
        return self.stego.extract(*args, **kwargs)

core/tool_inventory.py.utf8:
"""Explicit full-image inventory verification; no downloads or execution of evidence."""

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
from pathlib import Path
from typing import Any

from core.tools import ToolRunner

MAX_FILE_BYTES = 64 * 1024 * 1024


def digest_file(path: Path) -> str:
    if not path.is_file() or path.stat().st_size > MAX_FILE_BYTES:
        raise ValueError("inventory file must be bounded and regular")
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        total = 0
        while chunk := stream.read(65536):
            total += len(chunk)
            if total > MAX_FILE_BYTES:
                raise ValueError("inventory file exceeds byte limit")
            digest.update(chunk)
    return digest.hexdigest()


def read_lock(path: Path) -> dict[str, Any]:
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 65536:
        raise ValueError("invalid bounded inventory lock")
    with path.open("rb") as stream:
        raw = stream.read(65537)
    if len(raw) > 65536:
        raise ValueError("inventory lock exceeds byte limit")
    lock = json.loads(raw)
    if not isinstance(lock, dict) or lock.get("schema_version") != "full-image-tools-v1":
        raise ValueError("invalid inventory schema")
    names: set[str] = set()
    for key in ("tools", "gems"):
        rows = lock.get(key)
        if not isinstance(rows, list) or not 1 <= len(rows) <= 32:
            raise ValueError("invalid inventory rows")
        for row in rows:
            if not isinstance(row, dict):
                raise ValueError("invalid inventory row")
            for field in ("name", "version"):
                if not isinstance(row.get(field), str) or not re.fullmatch(
                    r"[A-Za-z0-9][A-Za-z0-9_.:+-]{0,99}", row[field]
                ):
                    raise ValueError("invalid inventory identity")
            if row["name"] in names:
                raise ValueError("duplicate inventory identity")
            names.add(row["name"])
            if not isinstance(row.get("license"), str) or not re.fullmatch(
                r"[A-Za-z0-9 .()+-]{1,150}", row["license"]
            ):
                raise ValueError("invalid license identity")
            if "sha256" in row and (
                not isinstance(row["sha256"], str)
                or not re.fullmatch(r"[0-9a-f]{64}", row["sha256"])
            ):
                raise ValueError("invalid inventory checksum")
            if "package" in row and (
                not isinstance(row["package"], str)
                or not re.fullmatch(r"[a-z0-9][a-z0-9+.-]{0,99}", row["package"])
            ):
                raise ValueError("invalid package identity")
            if "gem" in row and row["gem"] != row["name"]:
                raise ValueError("invalid gem identity")
    return lock


def digest_tree(root: Path) -> str:
    if root.is_symlink() or not root.is_dir():
        raise ValueError("invalid gem tree")
    digest = hashlib.sha256()
    paths: list[Path] = []
    directories = [root]
    count = total = 0
    while directories:
        with os.scandir(directories.pop()) as entries:
            for entry in entries:
                count += 1
                if count > 2048 or entry.is_symlink():
                    raise ValueError("gem tree exceeds limits or contains symlink")
                if entry.is_dir(follow_symlinks=False):
                    directories.append(Path(entry.path))
                elif entry.is_file(follow_symlinks=False):
                    paths.append(Path(entry.path))
                else:
                    raise ValueError("gem tree contains non-regular file")
    for path in sorted(paths):
        total += path.stat().st_size
        if total > MAX_FILE_BYTES:
            raise ValueError("gem tree exceeds byte limit")
        digest.update(path.relative_to(root).as_posix().encode())
        digest.update(b"\0")
        digest.update(digest_file(path).encode())
    return digest.hexdigest()


def verify_inventory(lock: dict[str, Any], *, cwd: Path) -> dict[str, Any]:
    runner = ToolRunner(timeout=10, max_output=16384)
    rows = []
    for spec in [*lock["tools"], *lock["gems"]]:
        name = spec["name"]
        is_tool = spec in lock["tools"]
        executable = shutil.which(name) if is_tool else None
        row: dict[str, Any] = {"name": name, "expected_version": spec["version"]}
        try:
            if is_tool and executable is None:
                raise ValueError("executable unavailable")
            if "package" in spec:
                result = runner.run(
                    "dpkg-query", ["-W", "-f=${Version}", spec["package"]],
                    cwd=cwd, _include_version=False,
                )
                license_path = Path("/usr/share/doc") / spec["package"] / "copyright"
                row["license_sha256"] = digest_file(license_path)
            elif "gem" in spec or not is_tool:
                # Names are validated by read_lock, never arbitrary Ruby input.
                code = (
                    's=Gem::Specification.find_by_name(ARGV.fetch(0)); '
                    'puts s.version; puts s.licenses.join(" OR "); puts s.full_gem_path'
                )
                result = runner.run("ruby", ["-e", code, name], cwd=cwd, _include_version=False)
                declaration = result.output.splitlines()[1]
                if declaration != spec["license"]:
                    raise ValueError("gem license declaration mismatch")
                row["license_declaration"] = declaration
                row["installed_tree_sha256"] = digest_tree(Path(result.output.splitlines()[2]))
            else:
                result = runner.run(name, ["--version"], cwd=cwd, _include_version=False)
                row["license_sha256"] = digest_file(Path("/usr/share/doc/stegseek/COPYING"))
            if result.status != "completed":
                raise ValueError("version probe unavailable or failed")
            observed = result.output.strip().splitlines()[0]
            if name == "stegseek":
                if not re.search(r"\bStegSeek " + re.escape(spec["version"]) + r"\b", observed):
                    raise ValueError("version mismatch")
                observed = spec["version"]
            if observed != spec["version"]:
                raise ValueError("version mismatch")
            row.update(version=observed, status="verified")
            if executable:
                row["executable_sha256"] = digest_file(Path(executable))
            if name == "openstego":
                row["jar_sha256"] = digest_file(Path("/usr/share/openstego/lib/openstego.jar"))
            if "license" in spec:
                row["license"] = spec["license"]
            if "sha256" in spec:
                row["distribution_sha256"] = spec["sha256"]
        except (OSError, ValueError, IndexError):
            row.update(status="unavailable", reason="version/license/identity verification failed")
        rows.append(row)
    return {
        "schema_version": "full-image-inventory-v1",
        "status": "verified" if all(row["status"] == "verified" for row in rows) else "unavailable",
        "entries": rows,
        "transitive_dependencies_fully_locked": False,
    }

core/wav_control_gate.py.utf8:
"""Read-only acceptance of source-bound, full-exposure generated WAV controls."""

from __future__ import annotations

import hashlib
import json
import math
import os
import stat
from pathlib import Path
from typing import Any

from core.nonjpeg_data import regular_read

PROTOCOL_ID = "wav-generated-full-control-20261021-v1"
SOURCES = (
    "core/__init__.py", "core/features.py", "core/nonjpeg_compare_metrics.py",
    "core/nonjpeg_data.py", "core/nonjpeg_features.py", "core/nonjpeg_linear.py",
    "core/nonjpeg_models.py", "core/spatial_cooccurrence.py", "core/spatial_parity.py",
    "core/wav_pilot.py", "core/wav_pilot_training.py", "core/wav_pilot_v3.py",
    "core/wav_control_gate.py", "steganography/research_wav_control.py",
    "tests/test_wav_control_gate.py", "tests/test_wav_pilot_v3.py",
    "docs/WAV_FULL_CONTROL_PROTOCOL_20261021.md", "pyproject.toml",
    "requirements-research-ci.txt", "benchmarks/wav-audiomnist-preparation-20261017.json",
    "scripts/audit-wav-positive-control.py",
)
SPEC: dict[str, Any] = {
    "recipe": "audio-pcm16-tlu-parity-gn1d-v3",
    "seeds": [20261016, 20261017],
    "train_files": 400, "development_files": 200,
    "epochs": 20, "updates_per_seed": 1140, "presentations_per_seed": 72000,
    "virtual_batch": 64, "final_batch_rows": 16,
    "train_auc_min": 0.60, "development_auc_min": 0.70,
    "wall_seconds_max": 3600,
    "host_bytes_max": 8 * 1024**3, "cuda_bytes_max": 4 * 1024**3,
    "swap_bytes_max": 0,
}
CELLS = {(method, rate, plane) for method in ("sequential", "scattered")
         for rate in (5, 40) for plane in (0, 1)}
CORPUS_EVIDENCE = {
    "train_files": 400, "development_files": 200,
    "train_groups": 20, "development_groups": 10, "files_per_group": 20,
    "group_overlap": 0, "decoded_pcm_overlap": 0,
    "payload_oracles_passed": 4800,
    "length_schedule": "exact_metadata_order",
}


def read_document(path: Path) -> tuple[dict[str, Any], str]:
    raw = regular_read(path, 1024**2)
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError("control document must be an object")
    return value, hashlib.sha256(raw).hexdigest()


def source_hash(path: Path) -> str:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("control source symlink")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, "rb") as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
            raise ValueError("control source must be regular")
        raw = stream.read(1024**2 + 1)
    if len(raw) > 1024**2:
        raise ValueError("control source size limit")
    return hashlib.sha256(raw).hexdigest()


def read_protocol(root: Path, path: Path) -> tuple[dict[str, Any], str]:
    protocol, digest = read_document(path)
    if (
        protocol.get("schema_version") != "wav-full-control-protocol-v1"
        or protocol.get("protocol_id") != PROTOCOL_ID
        or protocol.get("spec") != SPEC
        or protocol.get("real_fit_authorized") is not False
        or not isinstance(protocol.get("source_closure_sha256"), dict)
        or set(protocol["source_closure_sha256"]) != set(SOURCES)
    ):
        raise ValueError("full-control protocol contract mismatch")
    for name, expected in protocol["source_closure_sha256"].items():
        if source_hash(root / name) != expected:
            raise ValueError("full-control source binding mismatch")
    return protocol, digest


def _number(value: Any, low: float, high: float) -> bool:
    return (type(value) in (int, float) and low <= value <= high and math.isfinite(value))


def evaluate(protocol: dict[str, Any], digest: str, receipt: dict[str, Any]) -> dict[str, Any]:
    """Reject incomplete exposure/provenance; preserve a completed failed learning gate."""
    base = {
        "schema_version": "wav-full-control-decision-v1", "protocol_id": PROTOCOL_ID,
        "protocol_sha256": digest, "real_fit_authorized": False,
        "production_qualified": False,
    }

    def unavailable(reason: str) -> dict[str, Any]:
        return {**base, "status": "unavailable", "reason": reason}

    if (
        receipt.get("schema_version") != "wav-full-control-result-v1"
        or receipt.get("protocol_sha256") != digest
        or receipt.get("source_closure_sha256") != protocol["source_closure_sha256"]
        or receipt.get("recipe") != SPEC["recipe"]
        or receipt.get("generated_only") is not True
        or receipt.get("real_media_opened") is not False
        or receipt.get("reserved_media_opened") is not False
        or receipt.get("checkpoint_written") is not False
        or type(receipt.get("real_optimizer_updates")) is not int
        or receipt["real_optimizer_updates"] != 0
        or receipt.get("device") != "NVIDIA GeForce RTX 5060 Laptop GPU"
    ):
        return unavailable("provenance_or_recipe_mismatch")
    corpus = receipt.get("corpus")
    if not isinstance(corpus, dict) or set(corpus) != set(CORPUS_EVIDENCE) or any(
        type(corpus[k]) is not type(v) or corpus[k] != v for k, v in CORPUS_EVIDENCE.items()
    ):
        return unavailable("complete_disjoint_corpus_required")
    limits = {
        "wall_seconds": (0.000001, SPEC["wall_seconds_max"]),
        "host_peak_bytes": (1, SPEC["host_bytes_max"]),
        "cuda_peak_bytes": (1, SPEC["cuda_bytes_max"]),
        "swap_peak_bytes": (0, 0),
    }
    if any(not _number(receipt.get(key), low, high) for key, (low, high) in limits.items()):
        return unavailable("resource_evidence_missing_or_exceeded")
    runs = receipt.get("seeds")
    if not isinstance(runs, list) or len(runs) != 2 or any(not isinstance(r, dict) for r in runs):
        return unavailable("two_complete_seeds_required")
    if any(type(r.get("seed")) is not int for r in runs) or {
        r["seed"] for r in runs
    } != set(SPEC["seeds"]):
        return unavailable("two_complete_seeds_required")
    learning = []
    for run in runs:
        counts = {
            "epochs": SPEC["epochs"], "optimizer_updates": SPEC["updates_per_seed"],
            "row_presentations": SPEC["presentations_per_seed"],
            "train_files": SPEC["train_files"], "development_files": SPEC["development_files"],
            "virtual_batch": SPEC["virtual_batch"], "final_batch_rows": SPEC["final_batch_rows"],
        }
        if any(type(run.get(k)) is not int or run[k] != v for k, v in counts.items()):
            return unavailable("full_exposure_required")
        cells = run.get("development_cells")
        if not isinstance(cells, list) or len(cells) != 8:
            return unavailable("eight_complete_cells_required")
        found = {}
        for cell in cells:
            if (
                not isinstance(cell, dict) or type(cell.get("rate_percent")) is not int
                or type(cell.get("plane")) is not int or not isinstance(cell.get("method"), str)
                or not _number(cell.get("roc_auc"), 0, 1)
            ):
                return unavailable("invalid_metric_evidence")
            key = (cell["method"], cell["rate_percent"], cell["plane"])
            if key not in CELLS or key in found:
                return unavailable("eight_complete_cells_required")
            found[key] = cell["roc_auc"]
        if not _number(run.get("train_auc_all"), 0, 1):
            return unavailable("invalid_metric_evidence")
        learning.append({
            "seed": run["seed"],
            "passed": run["train_auc_all"] >= SPEC["train_auc_min"] and all(
                found[(method, 40, 0)] >= SPEC["development_auc_min"]
                for method in ("sequential", "scattered")
            ),
        })
    return {**base, "status": "passed_generated_only" if all(r["passed"] for r in learning)
            else "failed_learning_gate", "seeds": learning}

core/wav_pilot_v3.py.utf8:
"""AudioMNIST v3 PCM residual CNN recipe (never invoked by imports).

The v1 network scaled PCM by 1/32768, so a one-LSB change reached the model as
~3e-5, and BatchNorm saw single-waveform microbatches. A generated positive
control showed no learning even on training rows. v3 keeps the data, rows,
seeds, exposure and metrics; it changes only the CNN inputs, normalization and
optimizer.
"""

from __future__ import annotations

from typing import Any

import numpy as np

from core.nonjpeg_features import pcm16_samples
from core.wav_pilot_training import CNNRecipe

AUDIO_V3_DOMAIN = "audio-pcm16-tlu-parity-gn1d-v3"
# Residual truncation in integer sample units (truncated linear unit).
TLU = 8
CHANNELS = 4
GROUPS = 8
LEARNING_RATE = 0.001
WEIGHT_DECAY = 0.0001


def inputs(data: bytes) -> np.ndarray:
    """Truncated first/second differences plus centered bit planes 0 and 1."""
    raw = pcm16_samples(data).astype(np.int64)
    first = np.diff(raw, prepend=raw[0])
    second = np.diff(first, prepend=first[0])
    residual = np.clip(np.stack((first, second)), -TLU, TLU) / TLU
    # Two's-complement planes match the embedder's unsigned 16-bit view.
    planes = np.stack((raw & 1, (raw >> 1) & 1)) * 2 - 1
    return np.concatenate((residual, planes)).astype(np.float32)[None]


def network():
    try:
        import torch
    except ImportError as exc:
        raise RuntimeError("AudioMNIST v3 CNN unavailable: optional Torch missing") from exc

    def norm(channels):
        # Batch-independent: identical statistics in training and scoring.
        return torch.nn.GroupNorm(GROUPS, channels, dtype=torch.float32)

    class Conv(torch.nn.Sequential):
        def __init__(self, before, after, stride=1):
            super().__init__(
                torch.nn.Conv1d(before, after, 5, stride=stride, padding=2, dtype=torch.float32),
                norm(after),
                torch.nn.ReLU(),
            )

    class Residual(torch.nn.Module):
        def __init__(self, before, after, stride=1):
            super().__init__()
            self.branch = torch.nn.Sequential(
                Conv(before, after, stride),
                torch.nn.Conv1d(after, after, 5, padding=2, dtype=torch.float32),
                norm(after),
            )
            self.skip = (
                torch.nn.Identity()
                if before == after and stride == 1
                else torch.nn.Conv1d(before, after, 1, stride=stride, dtype=torch.float32)
            )

        def forward(self, values):
            return torch.relu(self.branch(values) + self.skip(values))

    class PCMNetV3(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.architecture = AUDIO_V3_DOMAIN
            self.body = torch.nn.Sequential(
                Conv(CHANNELS, 32),
                Residual(32, 32),
                Residual(32, 32),
                Residual(32, 64, 2),
                Residual(64, 128, 2),
                torch.nn.AdaptiveAvgPool1d(1),
                torch.nn.Flatten(),
            )
            self.classifier = torch.nn.Linear(128, 2, dtype=torch.float32)

        def forward(self, values):
            return self.classifier(self.body(values))

    return PCMNetV3()


def optimizer(torch: Any, model):
    """AdamW with decoupled L2 on weights only, as in v1's decay grouping."""
    decay: list[Any] = []
    no_decay: list[Any] = []
    for name, parameter in model.named_parameters():
        (decay if parameter.ndim > 1 and not name.endswith("bias") else no_decay).append(parameter)
    return torch.optim.AdamW(
        [
            {"params": decay, "weight_decay": WEIGHT_DECAY},
            {"params": no_decay, "weight_decay": 0.0},
        ],
        lr=LEARNING_RATE,
    )


V3_RECIPE = CNNRecipe(AUDIO_V3_DOMAIN, inputs, network, optimizer)

steganography/benchmarking/alaska2.py.utf8:
"""Frozen ALASKA2 native-score evaluation; no training or threshold selection."""

from __future__ import annotations

import argparse
import hashlib
import importlib.metadata
import io
import json
import os
import platform
import random
import re
import shutil
import stat
import time
from collections import Counter
from concurrent.futures import ProcessPoolExecutor
from pathlib import Path
from typing import Any

import numpy as np
from PIL import Image

from core.service import AnalysisService
from steganography.benchmarking.metrics import classification_metrics

METHODS = ("JMiPOD", "JUNIWARD", "UERD")
REQUIRED = (
    "image_jpeg",
    "image_jpeg_dct",
    "filestruct_appended",
    "filestruct_exif",
    "file_structure",
    "signatures",
)
MAX_IMAGE = 2 * 1024 * 1024
MAX_MANIFEST = 8 * 1024 * 1024
SEED = 20261004
DETECTOR_REVISION = "f929429a1603e5819156c8462d124ba1fe84c36a"


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def no_symlinks(path: Path) -> None:
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("symlink paths are forbidden")


def bounded_read(path: Path, maximum: int) -> bytes:
    no_symlinks(path)
    # Nonblocking open prevents a FIFO from hanging before the regular-file check.
    fd = os.open(path, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or not 0 <= info.st_size <= maximum:
            raise ValueError("input is not a bounded regular file")
        data = stream.read(maximum + 1)
    if len(data) > maximum:
        raise ValueError("input exceeds byte limit")
    return data


def detector_fingerprint() -> str:
    root = Path(__file__).resolve().parents[2]
    paths = sorted(
        [
            *root.joinpath("core").rglob("*.py"),
            *root.joinpath("modules").rglob("*.py"),
            root / "registry.py",
            root / "config.py",
        ]
    )
    return digest(
        b"".join(
            path.relative_to(root).as_posix().encode()
            + b"\0"
            + digest(bounded_read(path, MAX_MANIFEST)).encode()
            + b"\n"
            for path in paths
        )
    )


def load_source(root: Path, expected_sha256: str) -> tuple[dict[str, Any], str]:
    raw = bounded_read(root / "source.json", MAX_MANIFEST)
    if digest(raw) != expected_sha256:
        raise ValueError("source manifest checksum mismatch")
    source = json.loads(raw)
    if source.get("schema_version") != "alaska2-acquisition-v1":
        raise ValueError("unsupported acquisition schema")
    selection = bounded_read(root / "selection.json", MAX_MANIFEST)
    if digest(selection) != source.get("selection_sha256"):
        raise ValueError("selection checksum mismatch")
    samples = source.get("samples", [])
    if not 4 <= len(samples) <= 4000 or source.get("source_group") != "ALASKA2":
        raise ValueError("invalid ALASKA2 sample count or source")
    groups: dict[str, dict[str, dict[str, Any]]] = {}
    for row in samples:
        path = row.get("path", "")
        if not isinstance(path, str) or not re.fullmatch(
            r"(Cover|JMiPOD|JUNIWARD|UERD)/[0-9]{5}\.jpg", path
        ):
            raise ValueError("unsafe sample path")
        folder, name = path.split("/")
        group = groups.setdefault(name, {})
        if folder in group:
            raise ValueError("duplicate sample path")
        group[folder] = row
        if (
            row.get("split") != "test"
            or row.get("source_group") != "ALASKA2"
            or row.get("label") != ("cover" if folder == "Cover" else "stego")
            or row.get("method") != (None if folder == "Cover" else folder)
            or row.get("format") != "JPEG"
            or (row.get("width"), row.get("height")) != (512, 512)
            or type(row.get("size")) is not int
            or not 0 < row["size"] <= MAX_IMAGE
            or not re.fullmatch(r"[a-f0-9]{64}", str(row.get("sha256", "")))
        ):
            raise ValueError("invalid sample provenance")
    lineages = set()
    for group in groups.values():
        if set(group) != {"Cover", *METHODS}:
            raise ValueError("incomplete four-way lineage")
        lineage = group["Cover"]["sha256"]
        if lineage in lineages or any(r.get("lineage") != lineage for r in group.values()):
            raise ValueError("invalid or duplicate cover lineage")
        lineages.add(lineage)
    selected = json.loads(selection).get("members", [])
    if sorted(r["path"] for r in samples) != sorted(r["path"] for r in selected):
        raise ValueError("selection membership mismatch")
    return source, digest(raw)


def score_sample(item: tuple[str, dict[str, Any]]) -> dict[str, Any]:
    root, sample = item
    # Copy only explicitly portable fields, never arbitrary source metadata.
    row = {key: sample[key] for key in ("path", "sha256", "label", "method", "lineage")}
    row.update(score=None, status="failed", coverage={}, signals=[])
    started = time.monotonic()
    try:
        if not re.fullmatch(r"(Cover|JMiPOD|JUNIWARD|UERD)/[0-9]{5}\.jpg", row["path"]):
            raise ValueError("unsafe sample path")
        path = Path(root) / row["path"]
        data = bounded_read(path, MAX_IMAGE)
        if digest(data) != sample["sha256"] or len(data) != sample["size"]:
            raise ValueError("sample checksum or size mismatch")
        with Image.open(io.BytesIO(data)) as image:
            if image.format != "JPEG" or image.size != (512, 512):
                raise ValueError("unexpected JPEG dimensions")
            image.load()
        report = AnalysisService(
            profile="balanced", ai_provider=None, max_file_size=MAX_IMAGE
        ).analyze(path)
        if (
            report.file.sha256 != sample["sha256"]
            or digest(bounded_read(path, MAX_IMAGE)) != row["sha256"]
        ):
            raise ValueError("sample changed during analysis")
        row.update(
            score=report.overall_score,
            status="completed",
            coverage={r.analyzer: r.status for r in report.results if r.analyzer != "ai_triage"},
            signals=[
                {"analyzer": r.analyzer, "code": s.name, "score": s.score}
                for r in report.results
                if r.analyzer != "ai_triage"
                for s in r.signals
                if s.score >= 30
            ],
        )
    except Exception as exc:
        # Exception messages and plugin details can contain host paths or secrets.
        row["failure"] = type(exc).__name__
    row["seconds"] = time.monotonic() - started
    return row


def fixed_metrics(rows: list[dict[str, Any]]) -> dict[str, Any]:
    metrics = classification_metrics(
        [(r["label"] == "stego", r["score"]) for r in rows],
        threshold=70,
        recommend_threshold=False,
    )
    for key in ("recommended_threshold", "average_precision"):
        metrics.pop(key)
    return metrics


def summarize(rows: list[dict[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {
        "samples": len(rows),
        "failed_samples": sum(r["status"] != "completed" for r in rows),
        "analysis_error_samples": sum("error" in r["coverage"].values() for r in rows),
        "missing_required_samples": sum(
            any(r["coverage"].get(name) != "ok" for name in REQUIRED) for r in rows
        ),
        "coverage": {
            name: dict(Counter(r["coverage"].get(name, "missing") for r in rows))
            for name in sorted({*REQUIRED, *(n for r in rows for n in r["coverage"])})
        },
        "status": "unavailable",
        "metrics": None,
    }
    if not rows or any(
        result[k] for k in ("failed_samples", "analysis_error_samples", "missing_required_samples")
    ):
        return result
    result.update(status="completed", metrics=fixed_metrics(rows))
    groups: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        groups.setdefault(row["lineage"], []).append(row)
    grouped = list(groups.values())
    draws: dict[str, list[float]] = {
        key: [] for key in ("roc_auc", "balanced_accuracy", "recall", "false_positive_rate")
    }
    rng = random.Random(SEED)  # noqa: S311 - fixed statistical bootstrap, not cryptography
    for _ in range(200):
        metrics = fixed_metrics([r for g in rng.choices(grouped, k=len(grouped)) for r in g])
        for key, values in draws.items():
            if metrics[key] is not None:
                values.append(metrics[key])
    result["lineage_bootstrap_95_ci"] = {
        key: [float(np.percentile(values, 2.5)), float(np.percentile(values, 97.5))]
        for key, values in draws.items()
        if values
    }
    return result


def evaluate(
    root: Path, out: Path, *, source_sha256: str, protocol: Path, workers: int = 4
) -> dict[str, Any]:
    if not 1 <= workers <= 4:
        raise ValueError("workers must be 1..4")
    source, source_hash = load_source(root, source_sha256)
    protocol_hash = digest(bounded_read(protocol, MAX_MANIFEST))
    no_symlinks(out)
    out.mkdir(parents=True, exist_ok=False)
    provenance = {
        "schema_version": "alaska2-baseline-v1",
        "reference_detector_revision": DETECTOR_REVISION,
        "detector_code_sha256": detector_fingerprint(),
        "source_sha256": source_hash,
        "selection_sha256": source["selection_sha256"],
        "protocol_sha256": protocol_hash,
        "runner_sha256": digest(Path(__file__).read_bytes()),
        "threshold": 70,
        "profile": "balanced",
        "ai_enabled": False,
        "training_performed": False,
        "threshold_search_performed": False,
        "support_status": "experimental",
        "cross_source_gate": "unavailable",
        "ece": {"status": "unavailable", "reason": "uncalibrated heuristic scores"},
        "environment": {
            "python": platform.python_version(),
            "platform": platform.platform(),
            "logical_cpus": os.cpu_count(),
            "workers": workers,
            "packages": {n: importlib.metadata.version(n) for n in ("numpy", "Pillow")},
            "tools_available": {
                n: bool(shutil.which(n)) for n in ("exiftool", "stegseek", "zsteg")
            },
        },
    }
    try:
        provenance["environment"]["packages"]["jpeglib"] = importlib.metadata.version("jpeglib")
    except importlib.metadata.PackageNotFoundError:
        provenance["environment"]["packages"]["jpeglib"] = "unavailable"
    write_json(out / "run.json", provenance)
    started = time.monotonic()
    rows = []
    with (
        (out / "scores.jsonl").open("x", encoding="utf-8") as stream,
        ProcessPoolExecutor(max_workers=workers) as executor,
    ):
        for row in executor.map(score_sample, ((str(root), s) for s in source["samples"])):
            rows.append(row)
            stream.write(json.dumps(row) + "\n")
            stream.flush()
            if len(rows) % 100 == 0:
                print(f"analyzed {len(rows)}/{len(source['samples'])}", flush=True)
    covers = {r["lineage"]: r for r in rows if r["label"] == "cover"}
    ambiguous = [
        r["path"]
        for r in rows
        if r["label"] == "stego" and r["sha256"] == covers[r["lineage"]]["sha256"]
    ]
    ambiguous_uerd = {
        r["lineage"] for r in rows if r["method"] == "UERD" and r["path"] in ambiguous
    }
    by_method = {m: summarize([r for r in rows if r["method"] in (None, m)]) for m in METHODS}
    result = {
        **provenance,
        "samples": len(rows),
        "lineages": len(covers),
        "status": "completed"
        if all(m["status"] == "completed" for m in by_method.values())
        else "unavailable",
        "by_method": by_method,
        "byte_identical_stego_paths": ambiguous,
        "uerd_sensitivity_excluding_identical_pairs": summarize(
            [
                r
                for r in rows
                if r["method"] in (None, "UERD") and r["lineage"] not in ambiguous_uerd
            ]
        ),
        "scores_sha256": digest(bounded_read(out / "scores.jsonl", 32 * 1024 * 1024)),
        "elapsed_seconds": time.monotonic() - started,
        "latency": {
            "median_seconds": float(np.median([r["seconds"] for r in rows])),
            "p95_seconds": float(np.percentile([r["seconds"] for r in rows], 95)),
        },
    }
    write_json(out / "report.json", result)
    return result


def write_json(path: Path, value: Any) -> None:
    with path.open("x", encoding="utf-8") as stream:
        json.dump(value, stream, indent=2)
        stream.write("\n")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--source-sha256", required=True)
    parser.add_argument("--protocol", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=4)
    args = parser.parse_args()
    try:
        report = evaluate(
            args.source,
            args.out,
            source_sha256=args.source_sha256,
            protocol=args.protocol,
            workers=args.workers,
        )
    except (ValueError, OSError, KeyError, TypeError) as exc:
        parser.exit(2, f"evaluation failed ({type(exc).__name__}); details withheld\n")
    print(f"evaluation {report['status']}: {report['samples']} files", flush=True)
    if report["status"] != "completed":
        parser.exit(1)


if __name__ == "__main__":
    main()

